import type { NodeShape, NodeType, PortSide, PortType } from './types';
import type { LinkRouting } from './link';
import { Diagram } from './diagram';
import { Node } from './node';
import { GroupNode } from './group-node';
import { Link } from './link';
import { Port } from './port';
import type { NodeId, LinkId, PortId } from './types';

/**
 * JSON-serializable port data for save/load and paste.
 */
export interface PortDto {
  id: PortId;
  nodeId: string;
  side: PortSide;
  offset: number;
  type: PortType;
  maxLinks?: number;
}

/**
 * JSON-serializable node data for save/load and paste.
 * Includes group-specific fields when nodeType is 'group'.
 */
export interface NodeDto {
  id: NodeId;
  x: number;
  y: number;
  width?: number;
  height?: number;
  label?: string;
  shape?: NodeShape;
  rotation?: number;
  nodeType?: NodeType;
  customShapeId?: string;
  childNodeIds?: NodeId[];
  childLinkIds?: LinkId[];
  originalPositions?: Record<NodeId, { x: number; y: number }>;
  scale?: number;
  zIndex?: number;
  locked?: boolean;
  ports: PortDto[];
}

/**
 * JSON-serializable link data for save/load and paste.
 */
export interface LinkDto {
  id: LinkId;
  sourcePortId: PortId;
  targetPortId: PortId;
  points?: Array<{ x: number; y: number }>;
  routing?: LinkRouting;
  zIndex?: number;
  locked?: boolean;
}

/**
 * JSON-serializable diagram data; format for file storage and undo/redo snapshots.
 */
export interface DiagramJson {
  nodes: NodeDto[];
  links: LinkDto[];
}

/**
 * Serialize a diagram to a plain JSON-serializable object (for save, undo stack, clipboard).
 * @param diagram - Current diagram instance
 * @returns DiagramJson
 */
export function serializeDiagram(diagram: Diagram): DiagramJson {
  const nodes: NodeDto[] = diagram.nodes.map((node) => {
    const dto: NodeDto = {
      id: node.id,
      x: node.x,
      y: node.y,
      width: node.width,
      height: node.height,
      label: node.label,
      shape: node.shape,
      rotation: node.rotation,
      ...(node.customShapeId != null && { customShapeId: node.customShapeId }),
      ...(node.zIndex !== 0 && { zIndex: node.zIndex }),
      ...(node.locked && { locked: node.locked }),
      ports: node.ports.map((p) => ({
        id: p.id,
        nodeId: p.nodeId,
        side: p.side,
        offset: p.offset,
        type: p.type,
        ...(p.maxLinks !== undefined && { maxLinks: p.maxLinks }),
      })),
    };
    
    // Add group-specific properties if this is a GroupNode
    if (node.nodeType === 'group' && node instanceof GroupNode) {
      dto.nodeType = 'group';
      dto.childNodeIds = Array.from(node.childNodeIds);
      dto.childLinkIds = Array.from(node.childLinkIds);
      dto.scale = node.scale;
      
      // Convert Map to Record for JSON serialization
      const originalPositions: Record<NodeId, { x: number; y: number }> = {};
      for (const [nodeId, pos] of node.originalPositions.entries()) {
        originalPositions[nodeId] = { x: pos.x, y: pos.y };
      }
      dto.originalPositions = originalPositions;
    }
    
    return dto;
  });

  const links: LinkDto[] = diagram.links.map((link) => {
    const dto: LinkDto = {
      id: link.id,
      sourcePortId: link.sourcePortId,
      targetPortId: link.targetPortId,
    };
    if (link.points.length > 0) {
      dto.points = link.points.map((p) => ({ x: p.x, y: p.y }));
    }
    if (link.routing !== 'straight') {
      dto.routing = link.routing;
    }
    if (link.zIndex !== 0) {
      dto.zIndex = link.zIndex;
    }
    if (link.locked) {
      dto.locked = link.locked;
    }
    return dto;
  });

  return { nodes, links };
}

/**
 * Deserialize a diagram from a plain JSON object (load file, undo/redo restore).
 * @param json - Valid DiagramJson (nodes and links arrays)
 * @returns New Diagram instance
 */
export function deserializeDiagram(json: DiagramJson): Diagram {
  const diagram = new Diagram();

  for (const nd of json.nodes ?? []) {
    const ports = (nd.ports ?? []).map(
      (p) =>
        new Port({
          id: p.id,
          nodeId: p.nodeId,
          side: p.side,
          offset: p.offset,
          type: p.type,
          ...(p.maxLinks !== undefined && { maxLinks: p.maxLinks }),
        })
    );
    
    let node: Node;
    
    // Create GroupNode if nodeType is 'group'
    if (nd.nodeType === 'group') {
      const originalPositions = new Map<NodeId, { x: number; y: number }>();
      if (nd.originalPositions) {
        for (const [nodeId, pos] of Object.entries(nd.originalPositions)) {
          originalPositions.set(nodeId as NodeId, pos);
        }
      }
      
      node = new GroupNode({
        id: nd.id,
        x: nd.x,
        y: nd.y,
        width: nd.width,
        height: nd.height,
        label: nd.label,
        rotation: nd.rotation,
        childNodeIds: nd.childNodeIds,
        childLinkIds: nd.childLinkIds,
        originalPositions,
        scale: nd.scale,
        zIndex: nd.zIndex,
        locked: nd.locked,
        ports,
      });
    } else {
      node = new Node({
        id: nd.id,
        x: nd.x,
        y: nd.y,
        width: nd.width,
        height: nd.height,
        label: nd.label,
        shape: nd.shape,
        rotation: nd.rotation,
        nodeType: nd.nodeType,
        customShapeId: nd.customShapeId,
        zIndex: nd.zIndex,
        locked: nd.locked,
        ports,
      });
    }
    
    diagram.addNode(node);
  }

  for (const ld of json.links ?? []) {
    diagram.addLink(
      new Link({
        id: ld.id,
        sourcePortId: ld.sourcePortId,
        targetPortId: ld.targetPortId,
        points: ld.points,
        routing: ld.routing,
        zIndex: ld.zIndex,
        locked: ld.locked,
      })
    );
  }

  return diagram;
}

/**
 * Clone a DiagramJson with new node/link/port ids and position offset (for paste).
 * Node ids become n{startNodeCounter+1}, n{startNodeCounter+2}, ...; links l{startLinkCounter+1}, ...
 * @param json - Source diagram JSON (e.g. from clipboard)
 * @param offsetX - Added to every node x
 * @param offsetY - Added to every node y
 * @param startNodeCounter - Current max node number (e.g. from state); new nodes get higher numbers
 * @param startLinkCounter - Current max link number; new links get higher numbers
 * @returns New DiagramJson and list of new node ids (for selecting pasted nodes)
 */
export function cloneDiagramJsonForPaste(
  json: DiagramJson,
  offsetX: number,
  offsetY: number,
  startNodeCounter: number,
  startLinkCounter: number
): { json: DiagramJson; newNodeIds: NodeId[] } {
  const nodeIdMap = new Map<string, NodeId>();
  const portIdMap = new Map<string, PortId>();
  let nodeCounter = startNodeCounter;
  let linkCounter = startLinkCounter;

  const newNodes: NodeDto[] = (json.nodes ?? []).map((nd) => {
    nodeCounter++;
    const newNodeId = `n${nodeCounter}` as NodeId;
    nodeIdMap.set(nd.id, newNodeId);
    const newPorts: PortDto[] = (nd.ports ?? []).map((p, i) => {
      const newPortId = `${newNodeId}-p${i}` as PortId;
      portIdMap.set(p.id, newPortId);
      return {
        ...p,
        id: newPortId,
        nodeId: newNodeId,
      };
    });
    const newNode: NodeDto = {
      ...nd,
      id: newNodeId,
      x: nd.x + offsetX,
      y: nd.y + offsetY,
      rotation: nd.rotation,
      ports: newPorts,
    };
    
    // Update child node IDs for group nodes
    if (nd.nodeType === 'group' && nd.childNodeIds) {
      newNode.childNodeIds = nd.childNodeIds.map((childId) => nodeIdMap.get(childId) ?? childId);
    }
    
    return newNode;
  });

  const newNodeIds = newNodes.map((n) => n.id);

  const newLinks: LinkDto[] = (json.links ?? []).map((ld) => {
    linkCounter++;
    const newLinkId = `l${linkCounter}` as LinkId;
    return {
      ...ld,
      id: newLinkId,
      sourcePortId: portIdMap.get(ld.sourcePortId) ?? ld.sourcePortId,
      targetPortId: portIdMap.get(ld.targetPortId) ?? ld.targetPortId,
    };
  });

  return {
    json: { nodes: newNodes, links: newLinks },
    newNodeIds,
  };
}

import type { ActionContext } from './action-context';

/**
 * Base interface for all graph editor actions (command pattern).
 * Actions are executed by {@link GraphEditorActionDispatcher}.
 * When {@link pushUndoBeforeExecute} is true, the dispatcher pushes the current
 * diagram state onto the undo stack before executing (e.g. add node, delete).
 * When false, the caller is responsible for pushing once (e.g. move nodes during drag).
 */
export interface GraphEditorAction {
  /** If true, dispatcher calls undoRedo.pushState() before execute(). */
  readonly pushUndoBeforeExecute: boolean;

  /**
   * Execute the action using the provided context.
   * @param ctx - Access to state, coordinate, and link geometry services
   */
  execute(ctx: ActionContext): void;
}

import { InjectionToken } from '@angular/core';
import type { Signal } from '@angular/core';
import type { NodeShape } from '../../../../graph-core';
import type { DiagramJson } from '../../../../graph-core';

/** Token for injecting the current editor config (as a Signal). Provided by GraphEditorComponent. */
export const GRAPH_EDITOR_CONFIG = new InjectionToken<Signal<GraphEditorConfig>>(
  'GRAPH_EDITOR_CONFIG'
);

/** Toolbar feature flags. */
export interface GraphEditorToolbarConfig {
  visible?: boolean;
  addNode?: boolean;
  delete?: boolean;
  rotate?: boolean;
  align?: boolean;
  groupUngroup?: boolean;
  bringToFrontSendToBack?: boolean;
  lockUnlock?: boolean;
  connectorStyle?: boolean;
  zoom?: boolean;
  panTool?: boolean;
  zoomReset100?: boolean;
  zoomIndicator?: boolean;
  tooltips?: boolean;
  snapToGrid?: boolean;
  examples?: boolean;
  saveLoad?: boolean;
  fieldMapperDemo?: boolean;
  lodToggle?: boolean;
  viewportCullingToggle?: boolean;
  /** Show "Max links per port" input in toolbar. Default true. */
  maxLinksPerPort?: boolean;
}

/** Palette feature flags. */
export interface GraphEditorPaletteConfig {
  visible?: boolean;
  shapes?: NodeShape[] | 'all';
}

/** Keyboard shortcut feature flags. */
export interface GraphEditorKeyboardConfig {
  spacePan?: boolean;
  escape?: boolean;
  selectAll?: boolean;
  copyPaste?: boolean;
  duplicate?: boolean;
  undoRedo?: boolean;
  delete?: boolean;
  rotate?: boolean;
  groupUngroup?: boolean;
}

/** Canvas interaction feature flags. */
export interface GraphEditorInteractionsConfig {
  pan?: boolean;
  rubberBandSelection?: boolean;
  nodeDrag?: boolean;
  linkCreation?: boolean;
  /** When true, link drag can start from both input and output ports; when false, only from output. Default false. */
  linkCreationBidirectional?: boolean;
  linkWaypoints?: boolean;
  nodeContextMenu?: boolean;
  linkContextMenu?: boolean;
  groupResize?: boolean;
  /** Max links per port (0 = unlimited). Default 1. */
  maxLinksPerPort?: number;
}

/** Undo/redo configuration. */
export interface GraphEditorUndoRedoConfig {
  enabled: boolean;
  maxSteps?: number;
}

/** LOD (Level of Detail): simplified render and optional Canvas 2D when zoomed out. */
export interface GraphEditorLodConfig {
  /** Enable LOD at low zoom (scale below threshold). Default false. */
  enabled?: boolean;
  /** When LOD is active, use Canvas 2D for rendering. Default true when LOD enabled. */
  useCanvas?: boolean;
  /** Scale threshold: canvas-only (no interaction) when scale < this. Default 0.5. */
  scaleThreshold?: number;
  /** Scale above which SVG culled is allowed when node count is below forceCanvasAboveNodeCount. Default 1.2. */
  interactiveScaleThreshold?: number;
  /** Never render all nodes in SVG when node count >= this; use canvas+hit instead. Default 500. */
  forceCanvasAboveNodeCount?: number;
  /** Hysteresis: enter canvas-only when scale < this. Default 0.45. */
  scaleThresholdEnter?: number;
  /** Hysteresis: leave canvas-only when scale >= this. Default 0.55. */
  scaleThresholdLeave?: number;
  /** Hysteresis: leave canvas+hit for SVG when scale >= this. Default 1.2. */
  interactiveScaleThresholdLeave?: number;
  /** Hysteresis: leave SVG culled when scale < this. Default 1.1. */
  interactiveScaleThresholdEnter?: number;
  /**
   * When set, switch to SVG (svgCulled) at close zoom even when node count >= forceCanvasAboveNodeCount.
   * Example: 1.5 or 2 — at scale >= this value use SVG for crisp rendering; culling keeps only visible nodes/links.
   */
  scaleAboveForceSvg?: number;
}

/**
 * Unified configuration for the graph editor.
 * All features are enabled by default except toolbar.visible (false).
 */
export interface GraphEditorConfig {
  undoRedo?: GraphEditorUndoRedoConfig;
  toolbar?: GraphEditorToolbarConfig;
  palette?: GraphEditorPaletteConfig;
  keyboard?: GraphEditorKeyboardConfig;
  interactions?: GraphEditorInteractionsConfig;
  /** LOD and optional Canvas 2D when zoomed out. */
  lod?: GraphEditorLodConfig;
  snapToGrid?: boolean;
  gridVisible?: boolean;
  /** null = empty diagram, omit = MOCK_DIAGRAM_CHAIN for demo */
  initialDiagram?: DiagramJson | null;
  /** null = disable localStorage */
  storageKey?: string | null;
}

const DEFAULT_TOOLBAR: Required<GraphEditorToolbarConfig> = {
  visible: false,
  addNode: true,
  delete: true,
  rotate: true,
  align: true,
  groupUngroup: true,
  bringToFrontSendToBack: true,
  lockUnlock: true,
  connectorStyle: true,
  zoom: true,
  panTool: true,
  zoomReset100: true,
  zoomIndicator: true,
  tooltips: true,
  snapToGrid: true,
  examples: true,
  saveLoad: true,
  fieldMapperDemo: true,
  lodToggle: true,
  viewportCullingToggle: true,
  maxLinksPerPort: true,
};

const DEFAULT_PALETTE: Required<GraphEditorPaletteConfig> = {
  visible: true,
  shapes: 'all',
};

const DEFAULT_KEYBOARD: Required<GraphEditorKeyboardConfig> = {
  spacePan: true,
  escape: true,
  selectAll: true,
  copyPaste: true,
  duplicate: true,
  undoRedo: true,
  delete: true,
  rotate: true,
  groupUngroup: true,
};

const DEFAULT_INTERACTIONS: Required<GraphEditorInteractionsConfig> = {
  pan: true,
  rubberBandSelection: true,
  nodeDrag: true,
  linkCreation: true,
  linkCreationBidirectional: false,
  linkWaypoints: true,
  nodeContextMenu: true,
  linkContextMenu: true,
  groupResize: true,
  maxLinksPerPort: 1,
};

const DEFAULT_UNDO_REDO: Required<GraphEditorUndoRedoConfig> = {
  enabled: true,
  maxSteps: 50,
};

/** Default LOD: disabled, useCanvas true, scaleThreshold 0.5. */
export const DEFAULT_LOD_SCALE_THRESHOLD = 0.5;

export const DEFAULT_LOD_INTERACTIVE_SCALE_THRESHOLD = 1.2;
export const DEFAULT_LOD_FORCE_CANVAS_ABOVE_NODE_COUNT = 500;

export const DEFAULT_LOD_SCALE_THRESHOLD_ENTER = 0.45;
export const DEFAULT_LOD_SCALE_THRESHOLD_LEAVE = 0.55;
export const DEFAULT_LOD_INTERACTIVE_SCALE_THRESHOLD_ENTER = 1.1;
export const DEFAULT_LOD_INTERACTIVE_SCALE_THRESHOLD_LEAVE = 1.2;

const DEFAULT_LOD: Omit<Required<GraphEditorLodConfig>, 'scaleAboveForceSvg'> = {
  enabled: false,
