        return `${w / 2},0 ${w},${h / 2} ${w / 2},${h} 0,${h / 2}`;
      case 'triangle':
        return `${w / 2},0 ${w},${h} 0,${h}`;
      case 'hexagon':
        return `${w / 2},0 ${w},${h / 4} ${w},${(3 * h) / 4} ${w / 2},${h} 0,${(3 * h) / 4} 0,${h / 4}`;
      case 'parallelogram': {
        const s = w * 0.2;
        return `${s},0 ${w},0 ${w - s},${h} 0,${h}`;
      }
      case 'pentagon':
        return `${w / 2},0 ${w},${h * 0.4} ${w * 0.8},${h} ${w * 0.2},${h} 0,${h * 0.4}`;
      default:
        return '';
    }
  }

  protected getPreviewShapePath(shape: NodeShape, w: number, h: number): string {
    if (shape !== 'cross') return '';
    const vx1 = w * 0.4;
    const vx2 = w * 0.6;
    const hy1 = h * 0.4;
    const hy2 = h * 0.6;
    return `M ${vx1} 0 L ${vx2} 0 L ${vx2} ${h} L ${vx1} ${h} Z M 0 ${hy1} L ${w} ${hy1} L ${w} ${hy2} L 0 ${hy2} Z`;
  }

  /** Preview area: padding and vertical space for label. */
  private static readonly PREVIEW_PADDING = 20;
  private static readonly PREVIEW_TOP = 30;
  private static readonly PREVIEW_BOTTOM = 50;

  /** Calculate preview transform: fit full bounds, centered in preview area. */
  protected getPreviewTransform(): string {
    const groupNode = this.node();
    const bounds = groupNode.getBounds();
    const scale = groupNode.scale;
    const p = GraphGroupNodeComponent.PREVIEW_PADDING;
    const top = GraphGroupNodeComponent.PREVIEW_TOP;
    const availableWidth = groupNode.width - 2 * p;
    const availableHeight = groupNode.height - GraphGroupNodeComponent.PREVIEW_BOTTOM - top;

    // Center scaled content in preview area
    const offsetX = p + (availableWidth - bounds.width * scale) / 2 - bounds.x * scale;
    const offsetY = top + (availableHeight - bounds.height * scale) / 2 - bounds.y * scale;

    return `translate(${offsetX}, ${offsetY}) scale(${scale})`;
  }

  /** Whether to show generic placeholder instead of detailed preview (scale too small). */
  protected showPlaceholder(): boolean {
    return this.node().shouldShowPlaceholder();
  }

  /** Get label for external port (shows original port info). */
  protected getPortLabel(port: Port): string {
    // Extract label from port ID (e.g., "g1-ext-n2-out" -> "n2-out")
    const parts = port.id.split('-ext-');
    if (parts.length > 1) {
      return parts[1];
    }
    return port.id;
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  computed,
  NO_ERRORS_SCHEMA,
} from '@angular/core';
import type { GroupNode, Port, Diagram, Link, Node } from '../../../../graph-core';
import type { NodeShape } from '../../../../graph-core';

/** Emitted when user interacts with the group node body. */
export interface GroupNodePointerEvent {
  node: GroupNode;
  event: PointerEvent;
  shiftKey: boolean;
}

/** Emitted when user pointer-downs on a port. */
export interface GroupPortPointerEvent {
  port: Port;
  node: GroupNode;
  event: PointerEvent;
}

/** Emitted on group node context menu (right-click). */
export interface GroupNodeContextMenuEvent {
  node: GroupNode;
  event: MouseEvent;
}

/** Emitted when user starts resizing the group. */
export interface ResizeHandlePointerEvent {
  node: GroupNode;
  handle: ResizeHandle;
  event: PointerEvent;
}

export type ResizeHandle = 'nw' | 'n' | 'ne' | 'e' | 'se' | 's' | 'sw' | 'w';

/** Presentational component for a group node. Renders container, preview, ports, and resize handles. */
@Component({
  selector: 'g[app-graph-group-node]',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  schemas: [NO_ERRORS_SCHEMA],
  host: {
    '[attr.transform]': 'transformValue()',
    '(pointerdown)': 'onNodePointerDown($event)',
    '(pointermove)': 'onNodePointerMove($event)',
    '(pointerup)': 'onNodePointerUp($event)',
    '(pointerleave)': 'onNodePointerUp($event)',
    '(contextmenu)': 'onNodeContextMenu($event)',
  },
  templateUrl: './graph-group-node.component.html',
  styleUrl: './graph-group-node.component.scss',
})
export class GraphGroupNodeComponent {
  readonly node = input.required<GroupNode>();
  readonly diagram = input.required<Diagram>();
  readonly renderTick = input<number>(0);
  readonly selected = input<boolean>(false);

  readonly nodePointerDown = output<GroupNodePointerEvent>();
  readonly nodePointerMove = output<GroupNodePointerEvent>();
  readonly nodePointerUp = output<GroupNodePointerEvent>();
  readonly nodeContextMenu = output<GroupNodeContextMenuEvent>();
  readonly portPointerDown = output<GroupPortPointerEvent>();
  readonly resizeHandlePointerDown = output<ResizeHandlePointerEvent>();

  /** SVG transform: translate to node position (groups don't rotate). */
  protected readonly transformValue = computed(() => {
    this.renderTick();
    const n = this.node();
    return `translate(${n.x},${n.y})`;
  });

  /** Emit nodePointerDown if target is not a port or resize handle. */
  protected onNodePointerDown(event: PointerEvent): void {
    const target = event.target as Element;
    if (target.closest('[data-port-id]') || target.closest('[data-resize-handle]')) {
      return;
    }
    this.nodePointerDown.emit({ node: this.node(), event, shiftKey: event.shiftKey });
  }

  /** Forward pointer move to parent (for drag). */
  protected onNodePointerMove(event: PointerEvent): void {
    this.nodePointerMove.emit({ node: this.node(), event, shiftKey: event.shiftKey });
  }

  /** Forward pointer up to parent (end drag or apply click selection). */
  protected onNodePointerUp(event: PointerEvent): void {
    this.nodePointerUp.emit({ node: this.node(), event, shiftKey: event.shiftKey });
  }

  /** Emit nodeContextMenu if target is not a port or resize handle. */
  protected onNodeContextMenu(event: MouseEvent): void {
    const target = event.target as Element;
    if (target.closest('[data-port-id]') || target.closest('[data-resize-handle]')) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    this.nodeContextMenu.emit({ node: this.node(), event });
  }

  /** Emit portPointerDown and stop propagation. */
  protected onPortPointerDown(port: Port, event: PointerEvent): void {
    event.stopPropagation();
    this.portPointerDown.emit({ port, node: this.node(), event });
  }

  /** Emit resizeHandlePointerDown and stop propagation. */
  protected onResizeHandlePointerDown(handle: ResizeHandle, event: PointerEvent): void {
    event.stopPropagation();
    this.resizeHandlePointerDown.emit({ node: this.node(), handle, event });
  }

  /** Port position relative to node origin (for template). */
  protected getPortPosition(port: Port): { x: number; y: number } {
    const node = this.node();
    const pos = port.getAbsolutePosition(node.getRect());
    return { x: pos.x - node.x, y: pos.y - node.y };
  }

  /** Get resize handle positions. */
  protected getResizeHandles(): Array<{ handle: ResizeHandle; x: number; y: number; cursor: string }> {
    const n = this.node();
    const w = n.width;
    const h = n.height;
    const handleSize = 8;

    return [
      { handle: 'nw', x: -handleSize / 2, y: -handleSize / 2, cursor: 'nwse-resize' },
      { handle: 'n', x: w / 2 - handleSize / 2, y: -handleSize / 2, cursor: 'ns-resize' },
      { handle: 'ne', x: w - handleSize / 2, y: -handleSize / 2, cursor: 'nesw-resize' },
      { handle: 'e', x: w - handleSize / 2, y: h / 2 - handleSize / 2, cursor: 'ew-resize' },
      { handle: 'se', x: w - handleSize / 2, y: h - handleSize / 2, cursor: 'nwse-resize' },
      { handle: 's', x: w / 2 - handleSize / 2, y: h - handleSize / 2, cursor: 'ns-resize' },
      { handle: 'sw', x: -handleSize / 2, y: h - handleSize / 2, cursor: 'nesw-resize' },
      { handle: 'w', x: -handleSize / 2, y: h / 2 - handleSize / 2, cursor: 'ew-resize' },
    ];
  }

  /** Get child nodes for preview rendering. */
  protected getChildNodes(): Node[] {
    return this.node().getStoredChildNodes();
  }

  /** Get child links for preview rendering (internal links only). */
  protected getChildLinks(): Link[] {
    return this.node().getStoredChildLinks();
  }

  /** Build SVG path d for a link in preview (content coordinates). */
  protected getLinkPathD(link: Link): string {
    const groupNode = this.node();
    const children = groupNode.getStoredChildNodes();
    const getPortPos = (portId: string): { x: number; y: number } | null => {
      for (const n of children) {
        const port = n.getPort(portId);
        if (!port) continue;
        const pos = groupNode.getOriginalPosition(n.id) ?? { x: n.x, y: n.y };
        const rect = { x: pos.x, y: pos.y, width: n.width, height: n.height };
        const p = port.getAbsolutePosition(rect);
        return { x: p.x, y: p.y };
      }
      return null;
    };
    const source = getPortPos(link.sourcePortId);
    const target = getPortPos(link.targetPortId);
    if (!source || !target) return '';

    const pts: Array<{ x: number; y: number }> = [source];
    for (const p of link.points) {
      pts.push({ x: p.x, y: p.y });
    }
    pts.push(target);

    const parts = [`M ${pts[0].x} ${pts[0].y}`];
    for (let i = 1; i < pts.length; i++) {
      parts.push(`L ${pts[i].x} ${pts[i].y}`);
    }
    return parts.join(' ');
  }

  /** Shape points/path for preview node (same logic as graph-node). */
  protected getPreviewShapePoints(shape: NodeShape, w: number, h: number): string {
    switch (shape) {
      case 'diamond':
        return `${w / 2},0 ${w},${h / 2} ${w / 2},${h} 0,${h / 2}`;
      case 'triangle':
        return `${w / 2},0 ${w},${h} 0,${h}`;
      case 'hexagon':
        return `${w / 2},0 ${w},${h / 4} ${w},${(3 * h) / 4} ${w / 2},${h} 0,${(3 * h) / 4} 0,${h / 4}`;
      case 'parallelogram': {
        const s = w * 0.2;
        return `${s},0 ${w},0 ${w - s},${h} 0,${h}`;
      }
      case 'pentagon':
        return `${w / 2},0 ${w},${h * 0.4} ${w * 0.8},${h} ${w * 0.2},${h} 0,${h * 0.4}`;
      default:
        return '';
    }
  }

  protected getPreviewShapePath(shape: NodeShape, w: number, h: number): string {
    if (shape !== 'cross') return '';
    const vx1 = w * 0.4;
    const vx2 = w * 0.6;
    const hy1 = h * 0.4;
    const hy2 = h * 0.6;
    return `M ${vx1} 0 L ${vx2} 0 L ${vx2} ${h} L ${vx1} ${h} Z M 0 ${hy1} L ${w} ${hy1} L ${w} ${hy2} L 0 ${hy2} Z`;
  }

  /** Preview area: padding and vertical space for label. */
  private static readonly PREVIEW_PADDING = 20;
  private static readonly PREVIEW_TOP = 30;
  private static readonly PREVIEW_BOTTOM = 50;

  /** Calculate preview transform: fit full bounds, centered in preview area. */
  protected getPreviewTransform(): string {
    const groupNode = this.node();
    const bounds = groupNode.getBounds();
    const scale = groupNode.scale;
    const p = GraphGroupNodeComponent.PREVIEW_PADDING;
    const top = GraphGroupNodeComponent.PREVIEW_TOP;
    const availableWidth = groupNode.width - 2 * p;
    const availableHeight = groupNode.height - GraphGroupNodeComponent.PREVIEW_BOTTOM - top;

    // Center scaled content in preview area
    const offsetX = p + (availableWidth - bounds.width * scale) / 2 - bounds.x * scale;
    const offsetY = top + (availableHeight - bounds.height * scale) / 2 - bounds.y * scale;

    return `translate(${offsetX}, ${offsetY}) scale(${scale})`;
  }

  /** Whether to show generic placeholder instead of detailed preview (scale too small). */
  protected showPlaceholder(): boolean {
    return this.node().shouldShowPlaceholder();
  }

  /** Get label for external port (shows original port info). */
  protected getPortLabel(port: Port): string {
    // Extract label from port ID (e.g., "g1-ext-n2-out" -> "n2-out")
    const parts = port.id.split('-ext-');
    if (parts.length > 1) {
      return parts[1];
    }
    return port.id;
  }
}

import { Injectable } from '@angular/core';
import type { Diagram, Link, Node } from '../../../../graph-core';
import type { NodeId, LinkId } from '../../../../graph-core';
import type { PointLike, Rect } from '../../../../graph-core';
import { GraphLinkGeometryService } from './graph-link-geometry.service';
import { GRID_STEP } from './graph-coordinate.service';
import { getVisibleInViewBox } from './viewport-culling';

export interface LodCanvasDrawOptions {
  gridVisible?: boolean;
  gridStep?: number;
  /** When true (default), only draw nodes/links intersecting viewBox. When false, draw all. */
  viewportCulling?: boolean;
}

/** Encode hit index to RGB. Use 1-based: 0 = no hit, 1..n = nodes, n+1..n+m = links. Max ~16M. */
export function indexToRgb(index: number): string {
  if (index <= 0) return 'rgb(0,0,0)';
  const r = index & 0xff;
  const g = (index >> 8) & 0xff;
  const b = (index >> 16) & 0xff;
  return `rgb(${r},${g},${b})`;
}

/** Decode RGB from ImageData to 1-based hit index. Returns 0 if no hit. */
export function rgbToIndex(r: number, g: number, b: number): number {
  return r + (g << 8) + (b << 16);
}

export interface HitBufferResult {
  nodeIds: NodeId[];
  linkIds: LinkId[];
}

/**
 * Draws the graph diagram onto a 2D canvas for LOD (Level of Detail) when zoomed out.
 * Transforms SVG coordinates to canvas pixels via viewBox. Draws grid (optional), links, then nodes.
 */
@Injectable({ providedIn: 'root' })
export class GraphLodCanvasService {
  constructor(private readonly linkGeometry: GraphLinkGeometryService) {}

  /**
   * Draw diagram onto the canvas. Coordinate transform: svg -> px
   * pxX = (svgX - viewBox.x) / viewBox.width * canvasWidth, same for Y.
   */
  draw(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    options: LodCanvasDrawOptions = {}
  ): void {
    const { gridVisible = false, gridStep = GRID_STEP, viewportCulling = true } = options;

    const toPx = (svgX: number, svgY: number): { x: number; y: number } => ({
      x: ((svgX - viewBox.x) / viewBox.width) * canvasWidth,
      y: ((svgY - viewBox.y) / viewBox.height) * canvasHeight,
    });

    ctx.save();
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    if (gridVisible && viewBox.width > 0 && viewBox.height > 0) {
      this.drawGrid(ctx, viewBox, canvasWidth, canvasHeight, gridStep, toPx);
    }

    const { nodeIds: visibleNodeIds, linkIds: visibleLinkIds } =
      viewportCulling && viewBox.width > 0 && viewBox.height > 0
        ? getVisibleInViewBox(diagram, viewBox as Rect, this.linkGeometry)
        : {
            nodeIds: new Set(diagram.nodes.map((n) => n.id)),
            linkIds: new Set(diagram.links.map((l) => l.id)),
          };

    const links = [...diagram.links]
      .filter((l) => visibleLinkIds.has(l.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    for (const link of links) {
      this.drawLink(ctx, diagram, link, toPx);
    }

    const nodes = [...diagram.nodes]
      .filter((n) => visibleNodeIds.has(n.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    for (const node of nodes) {
      this.drawNode(ctx, node, toPx);
    }

    ctx.restore();
  }

  /**
   * Draw hit buffer: same geometry as draw(), but each node/link filled with encoded index color.
   * Index 1..nodeCount = nodes, nodeCount+1..nodeCount+linkCount = links. 0 = no hit.
   * Caller uses nodeIds = diagram.nodes.map(n => n.id), linkIds = diagram.links.map(l => l.id) for decode.
   */
  drawHitBuffer(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    options: LodCanvasDrawOptions = {}
  ): HitBufferResult {
    const { viewportCulling = true } = options;

    const toPx = (svgX: number, svgY: number): { x: number; y: number } => ({
      x: ((svgX - viewBox.x) / viewBox.width) * canvasWidth,
      y: ((svgY - viewBox.y) / viewBox.height) * canvasHeight,
    });

    ctx.save();
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    const { nodeIds: visibleNodeIds, linkIds: visibleLinkIds } =
      viewportCulling && viewBox.width > 0 && viewBox.height > 0
        ? getVisibleInViewBox(diagram, viewBox as Rect, this.linkGeometry)
        : {
            nodeIds: new Set(diagram.nodes.map((n) => n.id)),
            linkIds: new Set(diagram.links.map((l) => l.id)),
          };

    const links = [...diagram.links]
      .filter((l) => visibleLinkIds.has(l.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    const nodes = [...diagram.nodes]
      .filter((n) => visibleNodeIds.has(n.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    const nodeIds: NodeId[] = nodes.map((n) => n.id);
    const linkIds: LinkId[] = links.map((l) => l.id);

    links.forEach((link, j) => {
      ctx.fillStyle = indexToRgb(nodeIds.length + 1 + j);
      this.drawLinkPathOnly(ctx, diagram, link, toPx);
    });
    nodes.forEach((node, i) => {
      ctx.fillStyle = indexToRgb(i + 1);
      this.drawNodePathOnly(ctx, node, toPx);
    });

    ctx.restore();
    return { nodeIds, linkIds };
  }

  private drawLinkPathOnly(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    link: Link,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const pts = this.linkGeometry.getPathPoints(link, diagram);
    if (pts.length < 2) return;
    ctx.beginPath();
    const first = toPx(pts[0].x, pts[0].y);
    ctx.moveTo(first.x, first.y);
    for (let i = 1; i < pts.length; i++) {
      const p = toPx(pts[i].x, pts[i].y);
      ctx.lineTo(p.x, p.y);
    }
    ctx.strokeStyle = ctx.fillStyle!;
    ctx.lineWidth = 20;
    ctx.stroke();
  }

  private drawNodePathOnly(
    ctx: CanvasRenderingContext2D,
    node: Node,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const r = node.getRect();
    const x = r.x;
    const y = r.y;
    const w = r.width;
    const h = r.height;
    const cx = x + w / 2;
    const cy = y + h / 2;

    const tl = toPx(x, y);
    const br = toPx(x + w, y + h);
    const pxW = br.x - tl.x;
    const pxH = br.y - tl.y;
    const pxCx = tl.x + pxW / 2;
    const pxCy = tl.y + pxH / 2;

    ctx.beginPath();
    switch (node.shape) {
      case 'roundedRect': {
        const rx = Math.min(pxW / 4, 30);
        const ry = Math.min(pxH / 4, 15);
        this.roundRect(ctx, tl.x, tl.y, pxW, pxH, rx, ry);
        break;
      }
      case 'circle':
      case 'ellipse':
        ctx.ellipse(pxCx, pxCy, pxW / 2, pxH / 2, 0, 0, Math.PI * 2);
        break;
      case 'diamond': {
        const dx = toPx(cx, y);
        const dy = toPx(cx, y + h);
        const l = toPx(x, cy);
        const ri = toPx(x + w, cy);
        ctx.moveTo(dx.x, dx.y);
        ctx.lineTo(ri.x, ri.y);
        ctx.lineTo(dy.x, dy.y);
        ctx.lineTo(l.x, l.y);
        ctx.closePath();
        break;
      }
      case 'triangle': {
        const t = toPx(cx, y);
        const bl = toPx(x, y + h);
        const br_ = toPx(x + w, y + h);
        ctx.moveTo(t.x, t.y);
        ctx.lineTo(br_.x, br_.y);
        ctx.lineTo(bl.x, bl.y);
        ctx.closePath();
        break;
      }
      default:
        ctx.rect(tl.x, tl.y, pxW, pxH);
        break;
    }
    ctx.fill();
  }

  private drawGrid(
    ctx: CanvasRenderingContext2D,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    gridStep: number,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--grid-stroke')
      .trim() || '#ddd';
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 0.5;

    const xMin = Math.floor(viewBox.x / gridStep) * gridStep;
    const xMax = viewBox.x + viewBox.width;
    const yMin = Math.floor(viewBox.y / gridStep) * gridStep;
    const yMax = viewBox.y + viewBox.height;

    ctx.beginPath();
    for (let x = xMin; x <= xMax; x += gridStep) {
      const p0 = toPx(x, viewBox.y);
      const p1 = toPx(x, viewBox.y + viewBox.height);
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
    }
    for (let y = yMin; y <= yMax; y += gridStep) {
      const p0 = toPx(viewBox.x, y);
      const p1 = toPx(viewBox.x + viewBox.width, y);
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
    }
    ctx.stroke();
  }

  private drawLink(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    link: Link,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const pts = this.linkGeometry.getPathPoints(link, diagram);
    if (pts.length < 2) return;

    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--link-stroke')
      .trim() || '#666';
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 2;
    ctx.beginPath();
    const first = toPx(pts[0].x, pts[0].y);
    ctx.moveTo(first.x, first.y);
    for (let i = 1; i < pts.length; i++) {
      const p = toPx(pts[i].x, pts[i].y);
      ctx.lineTo(p.x, p.y);
    }
    ctx.stroke();
  }

  private drawNode(
    ctx: CanvasRenderingContext2D,
    node: Node,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const r = node.getRect();
    const x = r.x;
    const y = r.y;
    const w = r.width;
    const h = r.height;
    const cx = x + w / 2;
    const cy = y + h / 2;

    const tl = toPx(x, y);
    const br = toPx(x + w, y + h);
    const pxW = br.x - tl.x;
    const pxH = br.y - tl.y;
    const pxCx = tl.x + pxW / 2;
    const pxCy = tl.y + pxH / 2;

    const fill = getComputedStyle(document.documentElement)
      .getPropertyValue('--node-fill')
      .trim() || '#fff';
    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--node-stroke')
      .trim() || '#333';
    ctx.fillStyle = fill;
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1.5;

    ctx.beginPath();
    switch (node.shape) {
      case 'roundedRect':
        const rx = Math.min(pxW / 4, 30);
        const ry = Math.min(pxH / 4, 15);
        this.roundRect(ctx, tl.x, tl.y, pxW, pxH, rx, ry);
        break;
      case 'circle':
      case 'ellipse':
        ctx.ellipse(pxCx, pxCy, pxW / 2, pxH / 2, 0, 0, Math.PI * 2);
        break;
      case 'diamond': {
        const dx = toPx(cx, y);
        const dy = toPx(cx, y + h);
        const l = toPx(x, cy);
        const ri = toPx(x + w, cy);
        ctx.moveTo(dx.x, dx.y);
        ctx.lineTo(ri.x, ri.y);
        ctx.lineTo(dy.x, dy.y);
        ctx.lineTo(l.x, l.y);
        ctx.closePath();
        break;
      }
      case 'triangle': {
        const t = toPx(cx, y);
        const bl = toPx(x, y + h);
        const br_ = toPx(x + w, y + h);
        ctx.moveTo(t.x, t.y);
        ctx.lineTo(br_.x, br_.y);
        ctx.lineTo(bl.x, bl.y);
        ctx.closePath();
        break;
      }
      case 'hexagon':
      case 'parallelogram':
      case 'pentagon':
      case 'cross':
      case 'custom':
      case 'rectangle':
      default:
        ctx.rect(tl.x, tl.y, pxW, pxH);
        break;
    }
    ctx.fill();
    ctx.stroke();
  }

  private roundRect(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
    rx: number,
    ry: number
  ): void {
    ctx.moveTo(x + rx, y);
    ctx.lineTo(x + w - rx, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + ry);
    ctx.lineTo(x + w, y + h - ry);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rx, y + h);
    ctx.lineTo(x + rx, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - ry);
    ctx.lineTo(x, y + ry);
    ctx.quadraticCurveTo(x, y, x + rx, y);
  }
}

import { Point } from './point';
import type { LinkId, PortId } from './types';
import type { Diagram } from './diagram';

/** Routing style for links: straight (free angles) or orthogonal (H/V only). */
export type LinkRouting = 'straight' | 'orthogonal';

/**
 * Configuration for creating a Link.
 */
export interface LinkConfig {
  /** Unique link identifier. */
  id: LinkId;
  /** Source (output) port id. */
  sourcePortId: PortId;
  /** Target (input) port id. */
  targetPortId: PortId;
  /** Optional waypoints for polyline; otherwise straight between ports. */
  points?: Array<{ x: number; y: number }>;
  /** Path routing; defaults to 'straight'. */
  routing?: LinkRouting;
  /** Z-order for stacking; higher = on top. Default 0. */
  zIndex?: number;
  /** When true, link cannot be edited (waypoints) or deleted. Default false. */
  locked?: boolean;
}

/**
 * Link – connection between two ports. Optional waypoints for polyline; otherwise straight line.
 * With orthogonal routing, segments are horizontal or vertical only.
 */
export class Link implements LinkConfig {
  readonly id: LinkId;
  readonly sourcePortId: PortId;
  readonly targetPortId: PortId;
  points: Point[] = [];
  routing: LinkRouting = 'straight';
  zIndex: number;
  locked: boolean;

  constructor(config: LinkConfig) {
    this.id = config.id;
    this.sourcePortId = config.sourcePortId;
    this.targetPortId = config.targetPortId;
    this.points = (config.points ?? []).map((p) => new Point(p.x, p.y));
    this.routing = config.routing ?? 'straight';
    this.zIndex = config.zIndex ?? 0;
    this.locked = config.locked ?? false;
  }

  /** Set z-order (higher = on top). */
  setZIndex(value: number): void {
    this.zIndex = value;
  }

  /** Set locked state (when true, link cannot be edited or deleted). */
  setLocked(value: boolean): void {
    this.locked = value;
  }

  /**
   * Build SVG path d attribute: M source L target, or M source L waypoint... L target.
   * For orthogonal routing, inserts corner points so segments are H or V only.
   * @param diagram - Used to resolve port positions
   * @returns Path d string, or '' if port positions not found
   */
  buildPath(diagram: Diagram): string {
    const source = diagram.getPortPosition(this.sourcePortId);
    const target = diagram.getPortPosition(this.targetPortId);
    if (!source || !target) {
      return '';
    }

    const pts = [source, ...this.points, target];

    if (this.routing === 'orthogonal') {
      return this.buildOrthogonalPath(pts);
    }

    const segments: string[] = [`M ${pts[0].x} ${pts[0].y}`];
    for (let i = 1; i < pts.length; i++) {
      segments.push(`L ${pts[i].x} ${pts[i].y}`);
    }
    return segments.join(' ');
  }

  /**
   * Build orthogonal path: only horizontal and vertical segments.
   * Between non-aligned points A and B, inserts corner (B.x, A.y) or (A.x, B.y).
   */
  private buildOrthogonalPath(pts: Array<{ x: number; y: number }>): string {
    if (pts.length < 2) return '';
    const result: string[] = [`M ${pts[0].x} ${pts[0].y}`];

    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i];
      const b = pts[i + 1];
      if (a.x === b.x || a.y === b.y) {
        result.push(`L ${b.x} ${b.y}`);
      } else {
        const corner = this.orthogonalCorner(a, b);
        result.push(`L ${corner.x} ${corner.y} L ${b.x} ${b.y}`);
      }
    }
    return result.join(' ');
  }

  /** Choose corner for A->B: horizontal first from A, then vertical. */
  private orthogonalCorner(
    a: { x: number; y: number },
    b: { x: number; y: number }
  ): { x: number; y: number } {
    return { x: b.x, y: a.y };
  }
}

import type { NodeShape, NodeType, PortSide, PortType } from './types';
import type { LinkRouting } from './link';
import { Diagram } from './diagram';
import { Node } from './node';
import { GroupNode } from './group-node';
import { Link } from './link';
import { Port } from './port';
import type { NodeId, LinkId, PortId } from './types';

/**
 * JSON-serializable port data for save/load and paste.
 */
export interface PortDto {
  id: PortId;
  nodeId: string;
  side: PortSide;
  offset: number;
  type: PortType;
  maxLinks?: number;
}

/**
 * JSON-serializable node data for save/load and paste.
 * Includes group-specific fields when nodeType is 'group'.
 */
export interface NodeDto {
  id: NodeId;
  x: number;
  y: number;
  width?: number;
  height?: number;
  label?: string;
  shape?: NodeShape;
  rotation?: number;
  nodeType?: NodeType;
  customShapeId?: string;
  childNodeIds?: NodeId[];
  childLinkIds?: LinkId[];
  originalPositions?: Record<NodeId, { x: number; y: number }>;
  scale?: number;
  zIndex?: number;
  locked?: boolean;
  ports: PortDto[];
}

/**
 * JSON-serializable link data for save/load and paste.
 */
export interface LinkDto {
  id: LinkId;
  sourcePortId: PortId;
  targetPortId: PortId;
  points?: Array<{ x: number; y: number }>;
  routing?: LinkRouting;
  zIndex?: number;
  locked?: boolean;
}

/**
 * JSON-serializable diagram data; format for file storage and undo/redo snapshots.
 */
export interface DiagramJson {
  nodes: NodeDto[];
  links: LinkDto[];
}

/**
 * Serialize a diagram to a plain JSON-serializable object (for save, undo stack, clipboard).
 * @param diagram - Current diagram instance
 * @returns DiagramJson
 */
export function serializeDiagram(diagram: Diagram): DiagramJson {
  const nodes: NodeDto[] = diagram.nodes.map((node) => {
    const dto: NodeDto = {
      id: node.id,
      x: node.x,
      y: node.y,
      width: node.width,
      height: node.height,
      label: node.label,
      shape: node.shape,
      rotation: node.rotation,
      ...(node.customShapeId != null && { customShapeId: node.customShapeId }),
      ...(node.zIndex !== 0 && { zIndex: node.zIndex }),
      ...(node.locked && { locked: node.locked }),
      ports: node.ports.map((p) => ({
        id: p.id,
        nodeId: p.nodeId,
        side: p.side,
        offset: p.offset,
        type: p.type,
        ...(p.maxLinks !== undefined && { maxLinks: p.maxLinks }),
      })),
    };
    
    // Add group-specific properties if this is a GroupNode
    if (node.nodeType === 'group' && node instanceof GroupNode) {
      dto.nodeType = 'group';
      dto.childNodeIds = Array.from(node.childNodeIds);
      dto.childLinkIds = Array.from(node.childLinkIds);
      dto.scale = node.scale;
      
      // Convert Map to Record for JSON serialization
      const originalPositions: Record<NodeId, { x: number; y: number }> = {};
      for (const [nodeId, pos] of node.originalPositions.entries()) {
        originalPositions[nodeId] = { x: pos.x, y: pos.y };
      }
      dto.originalPositions = originalPositions;
    }
    
    return dto;
  });

  const links: LinkDto[] = diagram.links.map((link) => {
    const dto: LinkDto = {
      id: link.id,
      sourcePortId: link.sourcePortId,
      targetPortId: link.targetPortId,
    };
    if (link.points.length > 0) {
      dto.points = link.points.map((p) => ({ x: p.x, y: p.y }));
    }
    if (link.routing !== 'straight') {
      dto.routing = link.routing;
    }
    if (link.zIndex !== 0) {
      dto.zIndex = link.zIndex;
    }
    if (link.locked) {
      dto.locked = link.locked;
    }
    return dto;
  });

  return { nodes, links };
}

/**
 * Deserialize a diagram from a plain JSON object (load file, undo/redo restore).
 * @param json - Valid DiagramJson (nodes and links arrays)
 * @returns New Diagram instance
 */
export function deserializeDiagram(json: DiagramJson): Diagram {
  const diagram = new Diagram();

  for (const nd of json.nodes ?? []) {
    const ports = (nd.ports ?? []).map(
      (p) =>
        new Port({
          id: p.id,
          nodeId: p.nodeId,
          side: p.side,
          offset: p.offset,
          type: p.type,
          ...(p.maxLinks !== undefined && { maxLinks: p.maxLinks }),
        })
    );
    
    let node: Node;
    
    // Create GroupNode if nodeType is 'group'
    if (nd.nodeType === 'group') {
      const originalPositions = new Map<NodeId, { x: number; y: number }>();
      if (nd.originalPositions) {
        for (const [nodeId, pos] of Object.entries(nd.originalPositions)) {
          originalPositions.set(nodeId as NodeId, pos);
        }
      }
      
      node = new GroupNode({
        id: nd.id,
        x: nd.x,
        y: nd.y,
        width: nd.width,
        height: nd.height,
        label: nd.label,
        rotation: nd.rotation,
        childNodeIds: nd.childNodeIds,
        childLinkIds: nd.childLinkIds,
        originalPositions,
        scale: nd.scale,
        zIndex: nd.zIndex,
        locked: nd.locked,
        ports,
      });
    } else {
      node = new Node({
        id: nd.id,
        x: nd.x,
        y: nd.y,
        width: nd.width,
        height: nd.height,
        label: nd.label,
        shape: nd.shape,
        rotation: nd.rotation,
        nodeType: nd.nodeType,
        customShapeId: nd.customShapeId,
        zIndex: nd.zIndex,
        locked: nd.locked,
        ports,
      });
    }
    
    diagram.addNode(node);
  }

  for (const ld of json.links ?? []) {
    diagram.addLink(
      new Link({
        id: ld.id,
        sourcePortId: ld.sourcePortId,
        targetPortId: ld.targetPortId,
        points: ld.points,
        routing: ld.routing,
        zIndex: ld.zIndex,
        locked: ld.locked,
      })
    );
  }

  return diagram;
}

/**
 * Clone a DiagramJson with new node/link/port ids and position offset (for paste).
 * Node ids become n{startNodeCounter+1}, n{startNodeCounter+2}, ...; links l{startLinkCounter+1}, ...
 * @param json - Source diagram JSON (e.g. from clipboard)
 * @param offsetX - Added to every node x
 * @param offsetY - Added to every node y
 * @param startNodeCounter - Current max node number (e.g. from state); new nodes get higher numbers
 * @param startLinkCounter - Current max link number; new links get higher numbers
 * @returns New DiagramJson and list of new node ids (for selecting pasted nodes)
 */
export function cloneDiagramJsonForPaste(
  json: DiagramJson,
  offsetX: number,
  offsetY: number,
  startNodeCounter: number,
  startLinkCounter: number
): { json: DiagramJson; newNodeIds: NodeId[] } {
  const nodeIdMap = new Map<string, NodeId>();
  const portIdMap = new Map<string, PortId>();
  let nodeCounter = startNodeCounter;
  let linkCounter = startLinkCounter;

  const newNodes: NodeDto[] = (json.nodes ?? []).map((nd) => {
    nodeCounter++;
    const newNodeId = `n${nodeCounter}` as NodeId;
    nodeIdMap.set(nd.id, newNodeId);
    const newPorts: PortDto[] = (nd.ports ?? []).map((p, i) => {
      const newPortId = `${newNodeId}-p${i}` as PortId;
      portIdMap.set(p.id, newPortId);
      return {
        ...p,
        id: newPortId,
        nodeId: newNodeId,
      };
    });
    const newNode: NodeDto = {
      ...nd,
      id: newNodeId,
      x: nd.x + offsetX,
      y: nd.y + offsetY,
      rotation: nd.rotation,
      ports: newPorts,
    };
    
    // Update child node IDs for group nodes
    if (nd.nodeType === 'group' && nd.childNodeIds) {
      newNode.childNodeIds = nd.childNodeIds.map((childId) => nodeIdMap.get(childId) ?? childId);
    }
    
    return newNode;
  });

  const newNodeIds = newNodes.map((n) => n.id);

  const newLinks: LinkDto[] = (json.links ?? []).map((ld) => {
    linkCounter++;
    const newLinkId = `l${linkCounter}` as LinkId;
    return {
      ...ld,
      id: newLinkId,
      sourcePortId: portIdMap.get(ld.sourcePortId) ?? ld.sourcePortId,
      targetPortId: portIdMap.get(ld.targetPortId) ?? ld.targetPortId,
    };
  });

  return {
    json: { nodes: newNodes, links: newLinks },
    newNodeIds,
  };
}

import type { Diagram, Link } from '../../../../graph-core';
import type { NodeId, LinkId } from '../../../../graph-core';
import type { Rect } from '../../../../graph-core';
import type { PointLike } from '../../../../graph-core';

function rectsIntersect(a: Rect, b: Rect): boolean {
  return !(
    a.x + a.width < b.x ||
    b.x + b.width < a.x ||
    a.y + a.height < b.y ||
    b.y + b.height < a.y
  );
}

function pathBbox(pts: PointLike[]): Rect | null {
  if (pts.length === 0) return null;
  let xMin = pts[0].x;
  let yMin = pts[0].y;
  let xMax = pts[0].x;
  let yMax = pts[0].y;
  for (let i = 1; i < pts.length; i++) {
    xMin = Math.min(xMin, pts[i].x);
    yMin = Math.min(yMin, pts[i].y);
    xMax = Math.max(xMax, pts[i].x);
    yMax = Math.max(yMax, pts[i].y);
  }
  return { x: xMin, y: yMin, width: xMax - xMin, height: yMax - yMin };
}

export interface VisibleInViewBoxResult {
  nodeIds: Set<NodeId>;
  linkIds: Set<LinkId>;
}

export interface LinkGeometryLike {
  getPathPoints(link: Link, diagram: Diagram): PointLike[];
}

/**
 * Returns node and link IDs that intersect the viewBox.
 * Nodes: rect intersection with viewBox.
 * Links: visible if path bbox intersects viewBox.
 */
export function getVisibleInViewBox(
  diagram: Diagram,
  viewBox: Rect,
  linkGeometry: LinkGeometryLike
): VisibleInViewBoxResult {
  const nodeIds = new Set<NodeId>();
  const linkIds = new Set<LinkId>();

  for (const node of diagram.nodes) {
    const r = node.getRect();
    if (rectsIntersect(r, viewBox)) nodeIds.add(node.id);
  }

  for (const link of diagram.links) {
    const pts = linkGeometry.getPathPoints(link, diagram);
    const bbox = pathBbox(pts);
    if (bbox && rectsIntersect(bbox, viewBox)) linkIds.add(link.id);
  }

  return { nodeIds, linkIds };
}

import { Injectable, signal, computed } from '@angular/core';
import { deserializeDiagram } from '../../../../graph-core';
import type { Diagram } from '../../../../graph-core';
import type { DiagramJson } from '../../../../graph-core';
import type { LinkRouting } from '../../../../graph-core';
import type { NodeId, LinkId, PortId } from '../../../../graph-core';

/**
 * State while user is dragging a new link from an output port.
 * Used to draw preview line and to complete link on pointer up.
 */
export interface LinkingFromState {
  portId: PortId;
  nodeId: NodeId;
  portType: 'output' | 'input';
}

/** Rubber-band selection rectangle (any two corners as x1,y1 and x2,y2). */
export interface SelectionRect {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

/**
 * Holds all reactive state for the graph editor: diagram, selection, linking preview,
 * viewBox, render tick, id counters, and clipboard. Single source of truth for UI binding.
 * Signals: diagram, renderTick, viewBox, linkingFrom, linkingPreviewPoint, selectedNodeIds,
 * selectedLinkIds, hasSelection (computed).
 */
@Injectable({ providedIn: 'root' })
export class GraphEditorStateService {
  readonly diagram = signal<Diagram | null>(null);
  readonly renderTick = signal(0);
  readonly viewBox = signal({ x: 0, y: 0, width: 800, height: 600 });

  readonly linkingFrom = signal<LinkingFromState | null>(null);
  readonly linkingPreviewPoint = signal<{ x: number; y: number } | null>(null);

  readonly selectedNodeIds = signal<Set<NodeId>>(new Set());
  readonly selectedLinkIds = signal<Set<LinkId>>(new Set());
  readonly selectionRect = signal<SelectionRect | null>(null);
  readonly hasSelection = computed(
    () =>
      this.selectedNodeIds().size > 0 || this.selectedLinkIds().size > 0
  );

  /** When true, node positions snap to grid (add, move, paste, palette drop). */
  readonly snapToGridEnabled = signal(true);

  /** When true, LOD (Level of Detail) and Canvas rendering are enabled at low zoom. */
  readonly lodEnabled = signal(false);

  /** When true, only nodes/links intersecting the viewport are rendered (SVG and LOD canvas). */
  readonly viewportCullingEnabled = signal(true);

  /** Default link routing for newly created links (used by createLink). */
  readonly defaultLinkRouting = signal<LinkRouting>('orthogonal');

  /** Default max links per port (0 = unlimited). Used when port has no maxLinks set. */
  readonly defaultMaxLinksPerPort = signal<number>(1);

  /** True while Space is held (for pan-with-left-drag cursor). */
  readonly spaceKeyDown = signal(false);

  /** True when Pan tool is active in toolbar (left-drag pans without Space). */
  readonly panToolActive = signal(false);

  /** Set Space key state (used by keyboard directive). */
  setSpaceKeyDown(value: boolean): void {
    this.spaceKeyDown.set(value);
  }

  /** Set Pan tool active (used by toolbar toggle). */
  setPanToolActive(value: boolean): void {
    this.panToolActive.set(value);
  }

  /** Set snap-to-grid on or off. */
  setSnapToGridEnabled(value: boolean): void {
    this.snapToGridEnabled.set(value);
  }

  /** Toggle snap-to-grid (for toolbar button). */
  toggleSnapToGrid(): void {
    this.snapToGridEnabled.update((v) => !v);
  }

  /** Set LOD and Canvas rendering on or off. */
  setLodEnabled(value: boolean): void {
    this.lodEnabled.set(value);
  }

  /** Toggle LOD and Canvas (for toolbar button). */
  toggleLodEnabled(): void {
    this.lodEnabled.update((v) => !v);
  }

  /** Set viewport culling on or off. */
  setViewportCullingEnabled(value: boolean): void {
    this.viewportCullingEnabled.set(value);
  }

  /** Toggle viewport culling (for toolbar button). */
  toggleViewportCulling(): void {
    this.viewportCullingEnabled.update((v) => !v);
  }

  /** Set default link routing (for new links and toolbar select when no links selected). */
  setDefaultLinkRouting(routing: LinkRouting): void {
    this.defaultLinkRouting.set(routing);
  }

  /** Set default max links per port (0 = unlimited). Used by toolbar "apply to all". */
  setDefaultMaxLinksPerPort(value: number): void {
    this.defaultMaxLinksPerPort.set(value);
  }

  private _nodeIdCounter = 0;
  private _linkIdCounter = 0;
  private _clipboard: DiagramJson | null = null;

  /** Current diagram instance (mutable). Use diagram() for reactive reads. */
  getDiagram(): Diagram | null {
    return this.diagram();
  }

  /** Set diagram and optionally bump render tick. */
  setDiagram(d: Diagram | null, bumpTick = true): void {
    this.diagram.set(d);
    if (bumpTick) this.incrementRenderTick();
  }

  /** Replace diagram with deserialized JSON; clear selection and sync id counters. Used by load/undo/redo. */
  setDiagramFromJson(json: DiagramJson): void {
    const d = deserializeDiagram(json);
    this.setDiagram(d, true);
    this.clearSelection();
    this.syncCountersFromDiagram();
  }

  /** Increment render tick to trigger template updates after in-place diagram mutations. */
  incrementRenderTick(): void {
    this.renderTick.update((v) => v + 1);
  }

  /** Sync node/link id counters from current diagram (e.g. after load/restore). */
  syncCountersFromDiagram(): void {
    const d = this.diagram();
    if (!d) return;
    let maxN = 0;
    let maxL = 0;
    for (const node of d.nodes) {
      const m = /^n(\d+)$/.exec(node.id);
      if (m) maxN = Math.max(maxN, parseInt(m[1], 10));
    }
    for (const link of d.links) {
      const m = /^l(\d+)$/.exec(link.id);
      if (m) maxL = Math.max(maxL, parseInt(m[1], 10));
    }
    this._nodeIdCounter = maxN;
    this._linkIdCounter = maxL;
  }

  /** Current node id counter (n1, n2, ...). */
  getNodeIdCounter(): number {
    return this._nodeIdCounter;
  }

  /** Set node id counter (e.g. after load or paste). */
  setNodeIdCounter(value: number): void {
    this._nodeIdCounter = value;
  }

  /** Increment and return new node id counter. */
  incrementNodeIdCounter(): number {
    this._nodeIdCounter++;
    return this._nodeIdCounter;
  }

  /** Current link id counter (l1, l2, ...). */
  getLinkIdCounter(): number {
    return this._linkIdCounter;
  }

  /** Set link id counter (e.g. after load or paste). */
  setLinkIdCounter(value: number): void {
    this._linkIdCounter = value;
  }

  /** Increment and return new link id counter. */
  incrementLinkIdCounter(): number {
    this._linkIdCounter++;
    return this._linkIdCounter;
  }

  /** Clipboard content (DiagramJson) for paste. */
  getClipboard(): DiagramJson | null {
    return this._clipboard;
  }

  /** Set clipboard (e.g. after copy). */
  setClipboard(json: DiagramJson | null): void {
    this._clipboard = json;
  }

  /** Clear node and link selection. */
  clearSelection(): void {
    this.selectedNodeIds.set(new Set());
    this.selectedLinkIds.set(new Set());
  }

  /** Set selected nodes and clear link selection. */
  setNodeSelection(ids: Set<NodeId>): void {
    this.selectedNodeIds.set(ids);
    this.selectedLinkIds.set(new Set());
  }

  /** Set selected links and clear node selection. */
  setLinkSelection(ids: Set<LinkId>): void {
    this.selectedLinkIds.set(ids);
    this.selectedNodeIds.set(new Set());
  }

  /** Set both node and link selection at once (e.g. rubber-band selection). */
  setNodeAndLinkSelection(nodeIds: Set<NodeId>, linkIds: Set<LinkId>): void {
    this.selectedNodeIds.set(nodeIds);
    this.selectedLinkIds.set(linkIds);
  }

  /** Toggle one node in selection (Shift+click); clear link selection. */
  toggleNodeSelection(nodeId: NodeId): void {
    const next = new Set(this.selectedNodeIds());
    if (next.has(nodeId)) next.delete(nodeId);
    else next.add(nodeId);
    this.selectedNodeIds.set(next);
    this.selectedLinkIds.set(new Set());
  }

  /** Toggle one link in selection (Shift+click); clear node selection. */
  toggleLinkSelection(linkId: LinkId): void {
    const next = new Set(this.selectedLinkIds());
    if (next.has(linkId)) next.delete(linkId);
    else next.add(linkId);
    this.selectedLinkIds.set(next);
    this.selectedNodeIds.set(new Set());
  }

  /** Select all nodes and links in the current diagram. */
  selectAllNodesAndLinks(): void {
    const d = this.diagram();
    if (!d) return;
    this.selectedNodeIds.set(new Set(d.nodes.map((n) => n.id)));
    this.selectedLinkIds.set(new Set(d.links.map((l) => l.id)));
  }

  /** Set linking-from state (start or cancel link drag). */
  setLinkingFrom(state: LinkingFromState | null): void {
    this.linkingFrom.set(state);
  }

  /** Set preview point for link-in-progress. */
  setLinkingPreviewPoint(point: { x: number; y: number } | null): void {
    this.linkingPreviewPoint.set(point);
  }

  /** Set viewBox (for pan/zoom). */
  setViewBox(vb: { x: number; y: number; width: number; height: number }): void {
    this.viewBox.set(vb);
  }

  /** Set rubber-band selection rectangle (null to clear). */
  setSelectionRect(rect: SelectionRect | null): void {
    this.selectionRect.set(rect);
  }

  /** Select all nodes whose rect intersects the given rect; clears selectionRect. */
  selectNodesInRect(rect: SelectionRect): void {
    const d = this.getDiagram();
    if (!d) {
      this.setSelectionRect(null);
      return;
    }
    const xMin = Math.min(rect.x1, rect.x2);
    const xMax = Math.max(rect.x1, rect.x2);
    const yMin = Math.min(rect.y1, rect.y2);
    const yMax = Math.max(rect.y1, rect.y2);
    const ids = new Set<NodeId>();
    for (const node of d.nodes) {
      const r = node.getRect();
      const intersects =
        r.x + r.width >= xMin &&
        r.x <= xMax &&
        r.y + r.height >= yMin &&
        r.y <= yMax;
      if (intersects) ids.add(node.id);
    }
    this.setNodeSelection(ids);
    this.setSelectionRect(null);
  }
}

import { Injectable } from '@angular/core';
import type { Diagram, Link, Node } from '../../../../graph-core';
import type { NodeId, LinkId } from '../../../../graph-core';
import type { PointLike, Rect } from '../../../../graph-core';
import { GraphLinkGeometryService } from './graph-link-geometry.service';
import { GRID_STEP } from './graph-coordinate.service';
import { getVisibleInViewBox } from './viewport-culling';

export interface LodCanvasDrawOptions {
  gridVisible?: boolean;
  gridStep?: number;
  /** When true (default), only draw nodes/links intersecting viewBox. When false, draw all. */
  viewportCulling?: boolean;
}

/** Encode hit index to RGB. Use 1-based: 0 = no hit, 1..n = nodes, n+1..n+m = links. Max ~16M. */
export function indexToRgb(index: number): string {
  if (index <= 0) return 'rgb(0,0,0)';
  const r = index & 0xff;
  const g = (index >> 8) & 0xff;
  const b = (index >> 16) & 0xff;
  return `rgb(${r},${g},${b})`;
}

/** Decode RGB from ImageData to 1-based hit index. Returns 0 if no hit. */
export function rgbToIndex(r: number, g: number, b: number): number {
  return r + (g << 8) + (b << 16);
}

export interface HitBufferResult {
  nodeIds: NodeId[];
  linkIds: LinkId[];
}

/**
 * Draws the graph diagram onto a 2D canvas for LOD (Level of Detail) when zoomed out.
 * Transforms SVG coordinates to canvas pixels via viewBox. Draws grid (optional), links, then nodes.
 */
@Injectable({ providedIn: 'root' })
export class GraphLodCanvasService {
  constructor(private readonly linkGeometry: GraphLinkGeometryService) {}

  /**
   * Draw diagram onto the canvas. Coordinate transform: svg -> px
   * pxX = (svgX - viewBox.x) / viewBox.width * canvasWidth, same for Y.
   */
  draw(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    options: LodCanvasDrawOptions = {}
  ): void {
    const { gridVisible = false, gridStep = GRID_STEP, viewportCulling = true } = options;

    const toPx = (svgX: number, svgY: number): { x: number; y: number } => ({
      x: ((svgX - viewBox.x) / viewBox.width) * canvasWidth,
      y: ((svgY - viewBox.y) / viewBox.height) * canvasHeight,
    });

    ctx.save();
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    if (gridVisible && viewBox.width > 0 && viewBox.height > 0) {
      this.drawGrid(ctx, viewBox, canvasWidth, canvasHeight, gridStep, toPx);
    }

    const { nodeIds: visibleNodeIds, linkIds: visibleLinkIds } =
      viewportCulling && viewBox.width > 0 && viewBox.height > 0
        ? getVisibleInViewBox(diagram, viewBox as Rect, this.linkGeometry)
        : {
            nodeIds: new Set(diagram.nodes.map((n) => n.id)),
            linkIds: new Set(diagram.links.map((l) => l.id)),
          };

    const links = [...diagram.links]
      .filter((l) => visibleLinkIds.has(l.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    for (const link of links) {
      this.drawLink(ctx, diagram, link, toPx);
    }

    const nodes = [...diagram.nodes]
      .filter((n) => visibleNodeIds.has(n.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    for (const node of nodes) {
      this.drawNode(ctx, node, toPx);
    }

    ctx.restore();
  }

  /**
   * Draw hit buffer: same geometry as draw(), but each node/link filled with encoded index color.
   * Index 1..nodeCount = nodes, nodeCount+1..nodeCount+linkCount = links. 0 = no hit.
   * Caller uses nodeIds = diagram.nodes.map(n => n.id), linkIds = diagram.links.map(l => l.id) for decode.
   */
  drawHitBuffer(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    options: LodCanvasDrawOptions = {}
  ): HitBufferResult {
    const { viewportCulling = true } = options;

    const toPx = (svgX: number, svgY: number): { x: number; y: number } => ({
      x: ((svgX - viewBox.x) / viewBox.width) * canvasWidth,
      y: ((svgY - viewBox.y) / viewBox.height) * canvasHeight,
    });

    ctx.save();
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    const { nodeIds: visibleNodeIds, linkIds: visibleLinkIds } =
      viewportCulling && viewBox.width > 0 && viewBox.height > 0
        ? getVisibleInViewBox(diagram, viewBox as Rect, this.linkGeometry)
        : {
            nodeIds: new Set(diagram.nodes.map((n) => n.id)),
            linkIds: new Set(diagram.links.map((l) => l.id)),
          };

    const links = [...diagram.links]
      .filter((l) => visibleLinkIds.has(l.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    const nodes = [...diagram.nodes]
      .filter((n) => visibleNodeIds.has(n.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    const nodeIds: NodeId[] = nodes.map((n) => n.id);
    const linkIds: LinkId[] = links.map((l) => l.id);

    links.forEach((link, j) => {
      ctx.fillStyle = indexToRgb(nodeIds.length + 1 + j);
      this.drawLinkPathOnly(ctx, diagram, link, toPx);
    });
    nodes.forEach((node, i) => {
      ctx.fillStyle = indexToRgb(i + 1);
      this.drawNodePathOnly(ctx, node, toPx);
    });

    ctx.restore();
    return { nodeIds, linkIds };
  }

  private drawLinkPathOnly(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    link: Link,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const pts = this.linkGeometry.getPathPoints(link, diagram);
    if (pts.length < 2) return;
    ctx.beginPath();
    const first = toPx(pts[0].x, pts[0].y);
    ctx.moveTo(first.x, first.y);
    for (let i = 1; i < pts.length; i++) {
      const p = toPx(pts[i].x, pts[i].y);
      ctx.lineTo(p.x, p.y);
    }
    ctx.strokeStyle = ctx.fillStyle!;
    ctx.lineWidth = 20;
    ctx.stroke();
  }

  private drawNodePathOnly(
    ctx: CanvasRenderingContext2D,
    node: Node,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const r = node.getRect();
    const x = r.x;
    const y = r.y;
    const w = r.width;
    const h = r.height;
    const cx = x + w / 2;
    const cy = y + h / 2;

    const tl = toPx(x, y);
    const br = toPx(x + w, y + h);
    const pxW = br.x - tl.x;
    const pxH = br.y - tl.y;
    const pxCx = tl.x + pxW / 2;
    const pxCy = tl.y + pxH / 2;

    ctx.beginPath();
    switch (node.shape) {
      case 'roundedRect': {
        const rx = Math.min(pxW / 4, 30);
        const ry = Math.min(pxH / 4, 15);
        this.roundRect(ctx, tl.x, tl.y, pxW, pxH, rx, ry);
        break;
      }
      case 'circle':
      case 'ellipse':
        ctx.ellipse(pxCx, pxCy, pxW / 2, pxH / 2, 0, 0, Math.PI * 2);
        break;
      case 'diamond': {
        const dx = toPx(cx, y);
        const dy = toPx(cx, y + h);
        const l = toPx(x, cy);
        const ri = toPx(x + w, cy);
        ctx.moveTo(dx.x, dx.y);
        ctx.lineTo(ri.x, ri.y);
        ctx.lineTo(dy.x, dy.y);
        ctx.lineTo(l.x, l.y);
        ctx.closePath();
        break;
      }
      case 'triangle': {
        const t = toPx(cx, y);
        const bl = toPx(x, y + h);
        const br_ = toPx(x + w, y + h);
        ctx.moveTo(t.x, t.y);
        ctx.lineTo(br_.x, br_.y);
        ctx.lineTo(bl.x, bl.y);
        ctx.closePath();
        break;
      }
      default:
        ctx.rect(tl.x, tl.y, pxW, pxH);
        break;
    }
    ctx.fill();
  }

  private drawGrid(
    ctx: CanvasRenderingContext2D,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    gridStep: number,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--grid-stroke')
      .trim() || '#ddd';
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 0.5;

    const xMin = Math.floor(viewBox.x / gridStep) * gridStep;
    const xMax = viewBox.x + viewBox.width;
    const yMin = Math.floor(viewBox.y / gridStep) * gridStep;
    const yMax = viewBox.y + viewBox.height;

    ctx.beginPath();
    for (let x = xMin; x <= xMax; x += gridStep) {
      const p0 = toPx(x, viewBox.y);
      const p1 = toPx(x, viewBox.y + viewBox.height);
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
    }
    for (let y = yMin; y <= yMax; y += gridStep) {
      const p0 = toPx(viewBox.x, y);
      const p1 = toPx(viewBox.x + viewBox.width, y);
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
    }
    ctx.stroke();
  }

  private drawLink(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    link: Link,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const pts = this.linkGeometry.getPathPoints(link, diagram);
    if (pts.length < 2) return;

    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--link-stroke')
      .trim() || '#666';
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 2;
    ctx.beginPath();
    const first = toPx(pts[0].x, pts[0].y);
    ctx.moveTo(first.x, first.y);
    for (let i = 1; i < pts.length; i++) {
      const p = toPx(pts[i].x, pts[i].y);
      ctx.lineTo(p.x, p.y);
    }
    ctx.stroke();
  }

  private drawNode(
    ctx: CanvasRenderingContext2D,
    node: Node,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const r = node.getRect();
    const x = r.x;
    const y = r.y;
    const w = r.width;
    const h = r.height;
    const cx = x + w / 2;
    const cy = y + h / 2;

    const tl = toPx(x, y);
    const br = toPx(x + w, y + h);
    const pxW = br.x - tl.x;
    const pxH = br.y - tl.y;
    const pxCx = tl.x + pxW / 2;
    const pxCy = tl.y + pxH / 2;

    const fill = getComputedStyle(document.documentElement)
      .getPropertyValue('--node-fill')
      .trim() || '#fff';
    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--node-stroke')
      .trim() || '#333';
    ctx.fillStyle = fill;
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1.5;

    ctx.beginPath();
    switch (node.shape) {
      case 'roundedRect':
        const rx = Math.min(pxW / 4, 30);
        const ry = Math.min(pxH / 4, 15);
        this.roundRect(ctx, tl.x, tl.y, pxW, pxH, rx, ry);
        break;
      case 'circle':
      case 'ellipse':
        ctx.ellipse(pxCx, pxCy, pxW / 2, pxH / 2, 0, 0, Math.PI * 2);
        break;
      case 'diamond': {
        const dx = toPx(cx, y);
        const dy = toPx(cx, y + h);
        const l = toPx(x, cy);
        const ri = toPx(x + w, cy);
        ctx.moveTo(dx.x, dx.y);
        ctx.lineTo(ri.x, ri.y);
        ctx.lineTo(dy.x, dy.y);
        ctx.lineTo(l.x, l.y);
        ctx.closePath();
        break;
      }
      case 'triangle': {
        const t = toPx(cx, y);
        const bl = toPx(x, y + h);
        const br_ = toPx(x + w, y + h);
        ctx.moveTo(t.x, t.y);
        ctx.lineTo(br_.x, br_.y);
        ctx.lineTo(bl.x, bl.y);
        ctx.closePath();
        break;
      }
      case 'hexagon':
      case 'parallelogram':
      case 'pentagon':
      case 'cross':
      case 'custom':
      case 'rectangle':
      default:
        ctx.rect(tl.x, tl.y, pxW, pxH);
        break;
    }
    ctx.fill();
    ctx.stroke();
  }

  private roundRect(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
    rx: number,
    ry: number
  ): void {
    ctx.moveTo(x + rx, y);
    ctx.lineTo(x + w - rx, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + ry);
    ctx.lineTo(x + w, y + h - ry);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rx, y + h);
    ctx.lineTo(x + rx, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - ry);
    ctx.lineTo(x, y + ry);
    ctx.quadraticCurveTo(x, y, x + rx, y);
  }
}

export interface TreeNode {
  id: string;
  label: string;
  /** Present for parent nodes; absent or empty for leaves. */
  children?: TreeNode[];
  /** True when node is a leaf (no children). Leaves have columns. */
  isLeaf: boolean;
  /** For leaves only: values for the 4 columns. */
  columns?: [string, string, string, string];
}

/** One connection from a source leaf to a target leaf. */
export interface Mapping {
  sourceLeafId: string;
  targetLeafId: string;
}

/** Stable key for a mapping (for selection / lookup). */
export function mappingKey(m: Mapping): string {
  return `${m.sourceLeafId}\0${m.targetLeafId}`;
}

/** Filter state per column (e.g. search string). */
export interface ColumnFilter {
  value: string;
}

/** Expanded state: set of node ids that are expanded. */
export type ExpandedIds = Set<string>;

/** Anchor position for drawing links (in container/SVG coordinates). */
export interface AnchorPoint {
  x: number;
  y: number;
}

/** Optional Bezier path options (control point offset). */
export interface BezierPathOptions {
  /** Horizontal offset for control points as fraction of width. Default 0.3. */
  controlOffset?: number;
}

export const COLUMN_COUNT = 4;

import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  computed,
  NO_ERRORS_SCHEMA,
} from '@angular/core';
import type { Mapping, AnchorPoint } from '../models/field-mapper.model';
import { mappingKey } from '../models/field-mapper.model';
import { buildBezierPath } from '../utils/bezier-path';

export interface MappingClickPayload {
  sourceLeafId: string;
  targetLeafId: string;
}

@Component({
  selector: 'app-mapper-links-overlay',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  schemas: [NO_ERRORS_SCHEMA],
  templateUrl: './mapper-links-overlay.component.html',
  styleUrl: './mapper-links-overlay.component.scss',
})
export class MapperLinksOverlayComponent {
  readonly mappings = input<Mapping[]>([]);
  /** Map leafId -> anchor position in overlay pixel coordinates */
  readonly anchorByLeafId = input<Map<string, AnchorPoint>>(new Map());
  readonly previewFrom = input<AnchorPoint | null>(null);
  readonly previewTo = input<AnchorPoint | null>(null);
  readonly width = input<number>(1);
  readonly height = input<number>(1);
  readonly selectedMappingKey = input<string | null>(null);

  readonly mappingClick = output<MappingClickPayload>();

  readonly pathItems = computed(() => {
    const map = this.anchorByLeafId();
    const list = this.mappings();
    return list
      .map((m) => {
        const from = map.get(m.sourceLeafId);
        const to = map.get(m.targetLeafId);
        if (!from || !to) return null;
        return { pathD: buildBezierPath(from, to), mapping: m };
      })
      .filter((x): x is { pathD: string; mapping: Mapping } => x !== null);
  });

  protected isSelected(mapping: Mapping): boolean {
    return mappingKey(mapping) === this.selectedMappingKey();
  }

  protected getMappingKey(mapping: Mapping): string {
    return mappingKey(mapping);
  }

  protected onPathClick(mapping: Mapping, event: MouseEvent): void {
    event.stopPropagation();
    this.mappingClick.emit({
      sourceLeafId: mapping.sourceLeafId,
      targetLeafId: mapping.targetLeafId,
    });
  }

  readonly previewPathD = computed(() => {
    const from = this.previewFrom();
    const to = this.previewTo();
    if (!from || !to) return '';
    return buildBezierPath(from, to);
  });
}

import { Port } from './port';
import type { NodeId, NodeShape, NodeType, PortId, PointLike } from './types';
import type { Rect } from './types';

/**
 * Configuration for creating a Node.
 */
export interface NodeConfig {
  /** Unique node identifier. */
  id: NodeId;
  /** X position in diagram coordinates. */
  x: number;
  /** Y position in diagram coordinates. */
  y: number;
  /** Width; defaults to 120. */
  width?: number;
  /** Height; defaults to 60. */
  height?: number;
  /** Display label. */
  label?: string;
  /** Geometric shape for rendering. */
  shape?: NodeShape;
  /** Rotation in degrees (clockwise). */
  rotation?: number;
  /** Regular or group node. */
  nodeType?: NodeType;
  /** Custom shape identifier when shape is 'custom'. */
  customShapeId?: string;
  /** Z-order for stacking; higher = on top. Default 0. */
  zIndex?: number;
  /** When true, node cannot be moved, resized, rotated, or deleted. Default false. */
  locked?: boolean;
  /** Initial ports (input/output). */
  ports?: Port[];
}

/**
 * Node – graph element with position, size, label, and ports. Mutations (setPosition) are in-place.
 */
export class Node implements NodeConfig {
  readonly id: NodeId;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
  shape: NodeShape;
  rotation: number;
  nodeType: NodeType;
  customShapeId?: string;
  zIndex: number;
  locked: boolean;
  private _ports: Map<PortId, Port> = new Map();

  constructor(config: NodeConfig) {
    this.id = config.id;
    this.x = config.x;
    this.y = config.y;
    this.width = config.width ?? 120;
    this.height = config.height ?? 60;
    this.label = config.label ?? '';
    this.shape = config.shape ?? 'rectangle';
    this.rotation = config.rotation ?? 0;
    this.nodeType = config.nodeType ?? 'regular';
    this.customShapeId = config.customShapeId;
    this.zIndex = config.zIndex ?? 0;
    this.locked = config.locked ?? false;
    for (const p of config.ports ?? []) {
      this._ports.set(p.id, p);
    }
  }

  /**
   * Bounding rectangle for layout and port position.
   * @returns Rect with x, y, width, height
   */
  getRect(): Rect {
    return { x: this.x, y: this.y, width: this.width, height: this.height };
  }

  /** All ports on this node. */
  get ports(): Port[] {
    return Array.from(this._ports.values());
  }

  /**
   * Add a port (e.g. input or output).
   * @param port - Port to add; replaces existing port with same id
   */
  addPort(port: Port): void {
    this._ports.set(port.id, port);
  }

  /**
   * Remove port by id.
   * @param id - Port id to remove
   * @returns true if the port existed and was removed
   */
  removePort(id: PortId): boolean {
    return this._ports.delete(id);
  }

  /**
   * Get port by id.
   * @param id - Port id
   * @returns Port or undefined
   */
  getPort(id: PortId): Port | undefined {
    return this._ports.get(id);
  }

  /**
   * Set node position (in-place).
   * @param x - New x
   * @param y - New y
   */
  setPosition(x: number, y: number): void {
    this.x = x;
    this.y = y;
  }

  /**
   * Set position from a point-like object.
   * @param p - Point or { x, y }
   */
  setPositionFromPoint(p: PointLike): void {
    this.x = p.x;
    this.y = p.y;
  }

  /**
   * Set node rotation in degrees (clockwise). In-place.
   * @param deg - Rotation in degrees
   */
  setRotation(deg: number): void {
    this.rotation = deg;
  }

  /** Set z-order (higher = on top). */
  setZIndex(value: number): void {
    this.zIndex = value;
  }

  /** Set locked state (when true, node cannot be moved, resized, rotated, or deleted). */
  setLocked(value: boolean): void {
    this.locked = value;
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  computed,
  NO_ERRORS_SCHEMA,
} from '@angular/core';
import type { Node, Port } from '../../../../graph-core';

/** Emitted when user interacts with the node body (not a port). Used for drag and click selection. */
export interface NodePointerEvent {
  node: Node;
  event: PointerEvent;
  shiftKey: boolean;
}

/** Emitted when user pointer-downs on a port. Used to start link drag from output port. */
export interface PortPointerEvent {
  port: Port;
  node: Node;
  event: PointerEvent;
}

/** Emitted on node body context menu (right-click). Used for rotate menu. */
export interface NodeContextMenuEvent {
  node: Node;
  event: MouseEvent;
}

