import type { DiagramJson, NodeDto, PortDto, LinkDto } from '../serialization';

const ROWS = 50;
const NODE_WIDTH = 120;
const NODE_HEIGHT = 60;
const SPACING_X = 220;
const SPACING_Y = 100;

/**
 * Stress test diagram creation metrics.
 */
export interface StressTestMetrics {
  nodes: number;
  links: number;
  creationMs: number;
}

/**
 * Creates a stress test diagram with the given number of nodes in a chain topology.
 * Nodes are laid out in a grid (~50 per row). Links connect consecutive nodes n1→n2→...→nN.
 *
 * @param nodeCount - Number of nodes (and nodeCount - 1 links)
 * @param options - Optional: logToConsole to output metrics to console
 * @returns DiagramJson and metrics
 */
export function createStressTestDiagram(
  nodeCount: number,
  options?: { logToConsole?: boolean }
): { diagram: DiagramJson; metrics: StressTestMetrics } {
  const logToConsole = options?.logToConsole ?? true;

  performance.mark('stress-create-start');

  const nodes: NodeDto[] = [];
  const links: LinkDto[] = [];

  for (let i = 1; i <= nodeCount; i++) {
    const nodeId = `n${i}`;
    const x = ((i - 1) % ROWS) * SPACING_X;
    const y = Math.floor((i - 1) / ROWS) * SPACING_Y;

    const ports: PortDto[] = [
      {
        id: `p${i}-in`,
        nodeId,
        side: 'left',
        offset: NODE_HEIGHT / 2,
        type: 'input',
      },
      {
        id: `p${i}-out`,
        nodeId,
        side: 'right',
        offset: NODE_HEIGHT / 2,
        type: 'output',
      },
    ];

    nodes.push({
      id: nodeId,
      x,
      y,
      width: NODE_WIDTH,
      height: NODE_HEIGHT,
      label: `Node ${i}`,
      ports,
    });
  }

  for (let i = 1; i < nodeCount; i++) {
    links.push({
      id: `l${i}`,
      sourcePortId: `p${i}-out`,
      targetPortId: `p${i + 1}-in`,
    });
  }

  performance.mark('stress-create-end');
  performance.measure('stress-diagram-create', 'stress-create-start', 'stress-create-end');

  const measure = performance.getEntriesByName('stress-diagram-create', 'measure')[0];
  const creationMs = measure?.duration ?? 0;

  const metrics: StressTestMetrics = {
    nodes: nodeCount,
    links: nodeCount - 1,
    creationMs,
  };

  if (logToConsole) {
    console.log(
      `[Stress Test] Diagram created: ${metrics.nodes} nodes, ${metrics.links} links in ${creationMs.toFixed(1)} ms`
    );
    console.log('[Stress Test] Performance measures: create=', creationMs.toFixed(1), 'ms');
  }

  return {
    diagram: { nodes, links },
    metrics,
  };
}

export interface TreeNode {
  id: string;
  label: string;
  /** Present for parent nodes; absent or empty for leaves. */
  children?: TreeNode[];
  /** True when node is a leaf (no children). Leaves have columns. */
  isLeaf: boolean;
  /** For leaves only: values for the 4 columns. */
  columns?: [string, string, string, string];
}

/** One connection from a source leaf to a target leaf. */
export interface Mapping {
  sourceLeafId: string;
  targetLeafId: string;
}

/** Stable key for a mapping (for selection / lookup). */
export function mappingKey(m: Mapping): string {
  return `${m.sourceLeafId}\0${m.targetLeafId}`;
}

/** Filter state per column (e.g. search string). */
export interface ColumnFilter {
  value: string;
}

/** Expanded state: set of node ids that are expanded. */
export type ExpandedIds = Set<string>;

/** Anchor position for drawing links (in container/SVG coordinates). */
export interface AnchorPoint {
  x: number;
  y: number;
}

/** Optional Bezier path options (control point offset). */
export interface BezierPathOptions {
  /** Horizontal offset for control points as fraction of width. Default 0.3. */
  controlOffset?: number;
}

export const COLUMN_COUNT = 4;

export interface User {
  name: string;
}

import type { Diagram, Link } from '../../../../graph-core';
import type { NodeId, LinkId } from '../../../../graph-core';
import type { Rect } from '../../../../graph-core';
import type { PointLike } from '../../../../graph-core';

function rectsIntersect(a: Rect, b: Rect): boolean {
  return !(
    a.x + a.width < b.x ||
    b.x + b.width < a.x ||
    a.y + a.height < b.y ||
    b.y + b.height < a.y
  );
}

function pathBbox(pts: PointLike[]): Rect | null {
  if (pts.length === 0) return null;
  let xMin = pts[0].x;
  let yMin = pts[0].y;
  let xMax = pts[0].x;
  let yMax = pts[0].y;
  for (let i = 1; i < pts.length; i++) {
    xMin = Math.min(xMin, pts[i].x);
    yMin = Math.min(yMin, pts[i].y);
    xMax = Math.max(xMax, pts[i].x);
    yMax = Math.max(yMax, pts[i].y);
  }
  return { x: xMin, y: yMin, width: xMax - xMin, height: yMax - yMin };
}

export interface VisibleInViewBoxResult {
  nodeIds: Set<NodeId>;
  linkIds: Set<LinkId>;
}

export interface LinkGeometryLike {
  getPathPoints(link: Link, diagram: Diagram): PointLike[];
}

/**
 * Returns node and link IDs that intersect the viewBox.
 * Nodes: rect intersection with viewBox.
 * Links: visible if path bbox intersects viewBox.
 */
export function getVisibleInViewBox(
  diagram: Diagram,
  viewBox: Rect,
  linkGeometry: LinkGeometryLike
): VisibleInViewBoxResult {
  const nodeIds = new Set<NodeId>();
  const linkIds = new Set<LinkId>();

  for (const node of diagram.nodes) {
    const r = node.getRect();
    if (rectsIntersect(r, viewBox)) nodeIds.add(node.id);
  }

  for (const link of diagram.links) {
    const pts = linkGeometry.getPathPoints(link, diagram);
    const bbox = pathBbox(pts);
    if (bbox && rectsIntersect(bbox, viewBox)) linkIds.add(link.id);
  }

  return { nodeIds, linkIds };
}

import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  computed,
  viewChildren,
  ElementRef,
  inject,
  NO_ERRORS_SCHEMA,
} from '@angular/core';
import type { TreeNode, ColumnFilter, ExpandedIds, AnchorPoint } from '../models/field-mapper.model';

/** Visible row for rendering: node, depth, is leaf. */
export interface VisibleRow {
  node: TreeNode;
  depth: number;
  isLeaf: boolean;
}

@Component({
  selector: 'app-tree-table',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  schemas: [NO_ERRORS_SCHEMA],
  templateUrl: './tree-table.component.html',
  styleUrl: './tree-table.component.scss',
})
export class TreeTableComponent {
  private readonly host = inject(ElementRef<HTMLElement>);

  readonly root = input.required<TreeNode>();
  readonly expandedIds = input<ExpandedIds>(new Set());
  readonly filters = input<ColumnFilter[]>([
    { value: '' },
    { value: '' },
    { value: '' },
    { value: '' },
  ]);
  /** 'left' = sources (draggable), 'right' = receivers (droppable) */
  readonly side = input<'left' | 'right'>('left');
  /** When set, the leaf row with this id is highlighted as drop target. */
  readonly dropTargetLeafId = input<string | null>(null);

  readonly dragStart = output<{ leafId: string; event: PointerEvent }>();
  readonly filterChange = output<{ columnIndex: number; value: string }>();
  readonly toggleExpand = output<string>();

  readonly rowRefs = viewChildren<ElementRef<HTMLElement>>('rowRef');

  /** Filtered and expanded tree flattened to visible rows. */
  readonly visibleRows = computed(() => {
    const rootNode = this.root();
    const expanded = this.expandedIds();
    const filterVals = this.filters();
    const out: VisibleRow[] = [];
    const push = (node: TreeNode, depth: number) => {
      const isLeaf = node.isLeaf;
      if (isLeaf) {
        const cols = node.columns ?? ['', '', '', ''];
        const match = filterVals.every((f, i) => !f.value || (cols[i] ?? '').toLowerCase().includes(f.value.toLowerCase()));
        if (match) out.push({ node, depth, isLeaf: true });
      } else {
        const hasVisibleChild = (n: TreeNode): boolean => {
          if (n.isLeaf) {
            const cols = n.columns ?? ['', '', '', ''];
            return filterVals.every((f, i) => !f.value || (cols[i] ?? '').toLowerCase().includes(f.value.toLowerCase()));
          }
          return (n.children ?? []).some(hasVisibleChild);
        };
        const visible = (node.children ?? []).some(hasVisibleChild);
        if (visible) {
          out.push({ node, depth, isLeaf: false });
          if (expanded.has(node.id)) {
            for (const c of node.children ?? []) push(c, depth + 1);
          }
        }
      }
    };
    push(rootNode, 0);
    return out;
  });

  readonly columnHeaders = computed(() => {
    const f = this.filters();
    return [
      { label: 'Col 1', filterValue: f[0]?.value ?? '' },
      { label: 'Col 2', filterValue: f[1]?.value ?? '' },
      { label: 'Col 3', filterValue: f[2]?.value ?? '' },
      { label: 'Col 4', filterValue: f[3]?.value ?? '' },
    ];
  });

  onDragStart(leafId: string, event: PointerEvent): void {
    event.preventDefault();
    this.dragStart.emit({ leafId, event });
  }

  onFilterChange(columnIndex: number, value: string): void {
    this.filterChange.emit({ columnIndex, value });
  }

  onToggleExpand(nodeId: string): void {
    this.toggleExpand.emit(nodeId);
  }

  /**
   * Returns map of leafId -> anchor position in the given overlay container's coordinate system.
   * For visible leaf rows uses row rect; for leaves under a collapsed parent uses parent row rect.
   */
  getAnchorPositions(overlayRect: DOMRect): Map<string, AnchorPoint> {
    const result = new Map<string, AnchorPoint>();
    const hostEl = this.host.nativeElement;
    const isLeft = this.side() === 'left';
    const rows = this.visibleRows();
    const expanded = this.expandedIds();

    const leafIdToRowIndex = new Map<string, number>();
    const nodeIdToRowIndex = new Map<string, number>();
    rows.forEach((r, i) => {
      if (r.isLeaf) leafIdToRowIndex.set(r.node.id, i);
      else nodeIdToRowIndex.set(r.node.id, i);
    });

    const getRowElement = (index: number): HTMLElement | null => {
      const refs = this.rowRefs();
      const el = refs[index]?.nativeElement;
      return el ?? null;
    };

    const allLeafIds = this.collectLeafIds(this.root());
    const pathToLeaf = (node: TreeNode, id: string): TreeNode[] | null => {
      if (node.id === id) return [node];
      if (node.isLeaf) return null;
      for (const c of node.children ?? []) {
        const p = pathToLeaf(c, id);
        if (p) return [node, ...p];
      }
      return null;
    };

    for (const leafId of allLeafIds) {
      let rowIdx = leafIdToRowIndex.get(leafId);
      if (rowIdx === undefined) {
        const path = pathToLeaf(this.root(), leafId);
        if (path) {
          const collapsedAncestor = path.find((n) => !n.isLeaf && !expanded.has(n.id));
          if (collapsedAncestor) rowIdx = nodeIdToRowIndex.get(collapsedAncestor.id);
        }
      }
      const el = rowIdx !== undefined ? getRowElement(rowIdx) : null;
      if (el) {
        const r = el.getBoundingClientRect();
        const x = isLeft ? r.right - overlayRect.left : r.left - overlayRect.left;
        const y = (r.top + r.bottom) / 2 - overlayRect.top;
        result.set(leafId, { x, y });
      }
    }
    return result;
  }

  private collectLeafIds(node: TreeNode): string[] {
    if (node.isLeaf) return [node.id];
    const out: string[] = [];
    for (const c of node.children ?? []) out.push(...this.collectLeafIds(c));
    return out;
  }

  protected trackByNodeId(_index: number, row: VisibleRow): string {
    return row.node.id;
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  inject,
  input,
  output,
  computed,
  signal,
  NO_ERRORS_SCHEMA,
} from '@angular/core';
import type { Diagram, Link, PointLike } from '../../../../graph-core';
import { GraphLinkGeometryService } from '../services/graph-link-geometry.service';

export interface WaypointPointerPayload {
  link: Link;
  pointIndex: number;
  event: PointerEvent;
}

export interface PathPointerPayload {
  link: Link;
  event: PointerEvent;
}

export interface SegmentMidpointPayload {
  link: Link;
  insertIndex: number;
  x: number;
  y: number;
  event: PointerEvent;
}

/** Presentational component for one graph link. Renders SVG path; supports preview, waypoint handles, path hit area. */
@Component({
  selector: 'g[app-graph-link]',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  schemas: [NO_ERRORS_SCHEMA],
  templateUrl: './graph-link.component.html',
  styleUrl: './graph-link.component.scss',
})
export class GraphLinkComponent {
  private readonly linkGeometry = inject(GraphLinkGeometryService);

  readonly link = input.required<Link>();
  readonly diagram = input.required<Diagram>();
  readonly previewTarget = input<PointLike | null>(null);
  /** When diagram is mutated in place (e.g. node rotation), bump so path recomputes. */
  readonly renderTick = input<number>(0);
  readonly selected = input<boolean>(false);
  /** Which waypoint index is selected (for this link); null if none. */
  readonly selectedWaypointIndex = input<number | null>(null);

  /** True when the pointer is over the link (path or handles). */
  protected readonly hovered = signal(false);

  readonly linkClick = output<{ link: Link; shiftKey: boolean }>();
  readonly waypointPointerDown = output<WaypointPointerPayload>();
  readonly pathPointerDown = output<PathPointerPayload>();
  readonly segmentMidpointPointerDown = output<SegmentMidpointPayload>();
  readonly waypointDoubleClick = output<{ link: Link; pointIndex: number }>();
  readonly linkContextMenu = output<{ link: Link; event: MouseEvent }>();

  protected readonly pathD = computed(() => {
    this.renderTick(); // depend on tick so port positions (e.g. after node rotation) update
    const linkVal = this.link();
    const diagramVal = this.diagram();
    const target = this.previewTarget();

    if (target) {
      const source = diagramVal.getPortPosition(linkVal.sourcePortId);
      if (!source) return '';
      return `M ${source.x} ${source.y} L ${target.x} ${target.y}`;
    }

    return linkVal.buildPath(diagramVal);
  });

  /**
   * Waypoint display: for straight routing = link.points with their index;
   * for orthogonal = expanded path inner points, with pointIndex when the point is in link.points (selectable/removable).
   */
  protected readonly displayWaypoints = computed(() => {
    this.renderTick();
    const linkVal = this.link();
    const diagramVal = this.diagram();
    if (this.previewTarget()) return [];
    if (linkVal.routing === 'orthogonal') {
      const expanded = this.linkGeometry.getPathPoints(linkVal, diagramVal);
      if (expanded.length < 3) return [];
      const inner = expanded.slice(1, -1);
      return inner.map((pt) => {
        const idx = linkVal.points.findIndex((p) => p.x === pt.x && p.y === pt.y);
        return { x: pt.x, y: pt.y, pointIndex: idx >= 0 ? idx : null };
      });
    }
    return linkVal.points.map((p, i) => ({ x: p.x, y: p.y, pointIndex: i }));
  });

  /** Midpoints for each segment. For orthogonal uses expanded path so positions match the visible path. */
  protected readonly segmentMidpoints = computed(() => {
    this.renderTick();
    const linkVal = this.link();
    const diagramVal = this.diagram();
    if (this.previewTarget()) return [];
    const source = diagramVal.getPortPosition(linkVal.sourcePortId);
    const target = diagramVal.getPortPosition(linkVal.targetPortId);
    if (!source || !target) return [];
    const pts =
      linkVal.routing === 'orthogonal'
        ? this.linkGeometry.getPathPoints(linkVal, diagramVal)
        : [source, ...linkVal.points, target];
    const result: Array<{ segmentIndex: number; insertIndex: number; x: number; y: number }> = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i];
      const b = pts[i + 1];
      const pointInsertIndex =
        linkVal.routing === 'orthogonal'
          ? this.linkGeometry.segmentToPointInsertIndex(linkVal, diagramVal, i)
          : i;
      result.push({
        segmentIndex: i,
        insertIndex: pointInsertIndex,
        x: (a.x + b.x) / 2,
        y: (a.y + b.y) / 2,
      });
    }
    return result;
  });

  /** Emit linkClick with link and shiftKey for selection. */
  protected onLinkClick(event: MouseEvent): void {
    event.stopPropagation();
    this.linkClick.emit({ link: this.link(), shiftKey: event.shiftKey });
  }

  /** Emit pathPointerDown for segment grab (add waypoint). */
  protected onPathPointerDown(event: PointerEvent): void {
    event.stopPropagation();
    this.pathPointerDown.emit({ link: this.link(), event });
  }

  /** Emit waypointPointerDown for waypoint drag; on corner (pointIndex null) only stop propagation. */
  protected onWaypointHitPointerDown(
    event: PointerEvent,
    item: { x: number; y: number; pointIndex: number | null }
  ): void {
    event.stopPropagation();
    if (item.pointIndex !== null) {
      this.waypointPointerDown.emit({ link: this.link(), pointIndex: item.pointIndex, event });
    }
  }

  /** Emit waypointPointerDown for waypoint drag. */
  protected onWaypointPointerDown(event: PointerEvent, index: number): void {
    event.stopPropagation();
    this.waypointPointerDown.emit({ link: this.link(), pointIndex: index, event });
  }

  /** Emit waypointDoubleClick for remove waypoint. */
  protected onWaypointDoubleClick(index: number): void {
    this.waypointDoubleClick.emit({ link: this.link(), pointIndex: index });
  }

  /** Right-click on waypoint or corner: prevent default; remove waypoint only if pointIndex set. */
  protected onWaypointHitContextMenu(
    event: MouseEvent,
    item: { x: number; y: number; pointIndex: number | null }
  ): void {
    event.preventDefault();
    event.stopPropagation();
    if (item.pointIndex !== null) {
      this.waypointDoubleClick.emit({ link: this.link(), pointIndex: item.pointIndex });
    }
  }

  /** Right-click on waypoint: remove. */
  protected onWaypointContextMenu(event: MouseEvent, index: number): void {
    event.preventDefault();
    this.waypointDoubleClick.emit({ link: this.link(), pointIndex: index });
  }

  /** Right-click on link path: emit for context menu (e.g. Clear waypoints). */
  protected onLinkContextMenu(event: MouseEvent): void {
    this.linkContextMenu.emit({ link: this.link(), event });
  }

  /** Emit segmentMidpointPointerDown when grabbing a segment midpoint to add waypoint. */
  protected onSegmentMidpointPointerDown(
    event: PointerEvent,
    seg: { segmentIndex: number; insertIndex: number; x: number; y: number }
  ): void {
    event.stopPropagation();
    this.segmentMidpointPointerDown.emit({
      link: this.link(),
      insertIndex: seg.insertIndex,
      x: seg.x,
      y: seg.y,
      event,
    });
  }
}

