import { Injectable } from '@angular/core';
import type { Mapping } from '../models/field-mapper.model';

const MAX_UNDO = 50;

/**
 * Undo/redo for field-mapper mappings only. Stores snapshots of Mapping[].
 * Provide at FieldMapperComponent (or demo modal) level, not in root.
 */
@Injectable()
export class FieldMapperUndoRedoService {
  private _undoStack: Mapping[][] = [];
  private _redoStack: Mapping[][] = [];

  /** Push current mappings onto undo stack; clear redo. */
  pushState(mappings: Mapping[]): void {
    const snapshot = mappings.map((m) => ({ ...m }));
    this._undoStack.push(snapshot);
    if (this._undoStack.length > MAX_UNDO) {
      this._undoStack.shift();
    }
    this._redoStack = [];
  }

  /**
   * Undo one step: push current to redo, pop from undo and return snapshot to apply.
   * Caller must set mappings to the returned value.
   */
  undo(current: Mapping[]): Mapping[] | null {
    if (this._undoStack.length === 0) return null;
    this._redoStack.push(current.map((m) => ({ ...m })));
    return this._undoStack.pop() ?? null;
  }

  /**
   * Redo one step: push current to undo, pop from redo and return snapshot to apply.
   */
  redo(current: Mapping[]): Mapping[] | null {
    if (this._redoStack.length === 0) return null;
    this._undoStack.push(current.map((m) => ({ ...m })));
    return this._redoStack.pop() ?? null;
  }

  get canUndo(): boolean {
    return this._undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this._redoStack.length > 0;
  }
}

import { Injectable } from '@angular/core';

/** Grid step in SVG units; used for snap and future pathfinding. */
export const GRID_STEP = 20;

/**
 * Service for converting between screen (client) coordinates and SVG coordinate space,
 * and for snapping coordinates to the grid.
 */
@Injectable({ providedIn: 'root' })
export class GraphCoordinateService {
  /**
   * Converts client (screen) coordinates to coordinates in the SVG's coordinate system.
   * Uses the SVG element's current transform (viewBox, zoom, etc.).
   *
   * @param svgElement - The root SVGSVGElement (e.g. canvas container)
   * @param clientX - Client X from PointerEvent
   * @param clientY - Client Y from PointerEvent
   * @returns Point in SVG coordinates, or { x: 0, y: 0 } if element/CTM unavailable
   */
  clientToSvg(
    svgElement: SVGSVGElement | null | undefined,
    clientX: number,
    clientY: number
  ): { x: number; y: number } {
    if (!svgElement) return { x: 0, y: 0 };
    const pt = svgElement.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const ctm = svgElement.getScreenCTM();
    const svgP = ctm ? pt.matrixTransform(ctm.inverse()) : pt;
    return { x: svgP.x, y: svgP.y };
  }

  /**
   * Snaps a point to the grid. Single source for grid step (pathfinding, snap).
   */
  snapToGrid(x: number, y: number): { x: number; y: number } {
    return {
      x: Math.round(x / GRID_STEP) * GRID_STEP,
      y: Math.round(y / GRID_STEP) * GRID_STEP,
    };
  }
}

import { inject, Injectable } from '@angular/core';
import type { GraphEditorAction } from './graph-editor-action';
import type { ActionContext } from './action-context';
import { GraphEditorStateService } from '../services/graph-editor-state.service';
import { GraphUndoRedoService } from '../services/graph-undo-redo.service';
import { GraphCoordinateService } from '../services/graph-coordinate.service';
import { GraphLinkGeometryService } from '../services/graph-link-geometry.service';
import { GRAPH_EDITOR_CONFIG } from '../config/graph-editor-config';

/**
 * Dispatches graph editor actions: pushes undo state when required,
 * then executes the action with a shared context (state, coordinate, linkGeometry).
 * Used by {@link GraphOperationsService} as the single entry point for undoable mutations.
 */
@Injectable()
export class GraphEditorActionDispatcher {
  private readonly context: ActionContext;
  private readonly configSignal = inject(GRAPH_EDITOR_CONFIG, { optional: true });

  constructor(
    private readonly state: GraphEditorStateService,
    private readonly undoRedo: GraphUndoRedoService,
    private readonly coordinate: GraphCoordinateService,
    private readonly linkGeometry: GraphLinkGeometryService
  ) {
    this.context = {
      state: this.state,
      coordinate: this.coordinate,
      linkGeometry: this.linkGeometry,
    };
  }

  /**
   * Execute an action. Pushes current diagram onto undo stack first if the action requests it
   * and undo/redo is enabled in config.
   */
  dispatch(action: GraphEditorAction): void {
    if (action.pushUndoBeforeExecute) {
      const cfg = this.configSignal?.();
      if (cfg?.undoRedo?.enabled !== false) {
        this.undoRedo.pushState();
      }
    }
    action.execute(this.context);
  }
}

import { Injectable, signal, computed } from '@angular/core';
import { deserializeDiagram } from '../../../../graph-core';
import type { Diagram } from '../../../../graph-core';
import type { DiagramJson } from '../../../../graph-core';
import type { LinkRouting } from '../../../../graph-core';
import type { NodeId, LinkId, PortId } from '../../../../graph-core';

/**
 * State while user is dragging a new link from an output port.
 * Used to draw preview line and to complete link on pointer up.
 */
export interface LinkingFromState {
  portId: PortId;
  nodeId: NodeId;
  portType: 'output' | 'input';
}

/** Rubber-band selection rectangle (any two corners as x1,y1 and x2,y2). */
export interface SelectionRect {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

/**
 * Holds all reactive state for the graph editor: diagram, selection, linking preview,
 * viewBox, render tick, id counters, and clipboard. Single source of truth for UI binding.
 * Signals: diagram, renderTick, viewBox, linkingFrom, linkingPreviewPoint, selectedNodeIds,
 * selectedLinkIds, hasSelection (computed).
 */
@Injectable({ providedIn: 'root' })
export class GraphEditorStateService {
  readonly diagram = signal<Diagram | null>(null);
  readonly renderTick = signal(0);
  readonly viewBox = signal({ x: 0, y: 0, width: 800, height: 600 });

  readonly linkingFrom = signal<LinkingFromState | null>(null);
  readonly linkingPreviewPoint = signal<{ x: number; y: number } | null>(null);

  readonly selectedNodeIds = signal<Set<NodeId>>(new Set());
  readonly selectedLinkIds = signal<Set<LinkId>>(new Set());
  readonly selectionRect = signal<SelectionRect | null>(null);
  readonly hasSelection = computed(
    () =>
      this.selectedNodeIds().size > 0 || this.selectedLinkIds().size > 0
  );

  /** When true, node positions snap to grid (add, move, paste, palette drop). */
  readonly snapToGridEnabled = signal(true);

  /** When true, LOD (Level of Detail) and Canvas rendering are enabled at low zoom. */
  readonly lodEnabled = signal(false);

  /** When true, only nodes/links intersecting the viewport are rendered (SVG and LOD canvas). */
  readonly viewportCullingEnabled = signal(true);

  /** Default link routing for newly created links (used by createLink). */
  readonly defaultLinkRouting = signal<LinkRouting>('orthogonal');

  /** Default max links per port (0 = unlimited). Used when port has no maxLinks set. */
  readonly defaultMaxLinksPerPort = signal<number>(1);

  /** True while Space is held (for pan-with-left-drag cursor). */
  readonly spaceKeyDown = signal(false);

  /** True when Pan tool is active in toolbar (left-drag pans without Space). */
  readonly panToolActive = signal(false);

  /** Set Space key state (used by keyboard directive). */
  setSpaceKeyDown(value: boolean): void {
    this.spaceKeyDown.set(value);
  }

  /** Set Pan tool active (used by toolbar toggle). */
  setPanToolActive(value: boolean): void {
    this.panToolActive.set(value);
  }

  /** Set snap-to-grid on or off. */
  setSnapToGridEnabled(value: boolean): void {
    this.snapToGridEnabled.set(value);
  }

  /** Toggle snap-to-grid (for toolbar button). */
  toggleSnapToGrid(): void {
    this.snapToGridEnabled.update((v) => !v);
  }

  /** Set LOD and Canvas rendering on or off. */
  setLodEnabled(value: boolean): void {
    this.lodEnabled.set(value);
  }

  /** Toggle LOD and Canvas (for toolbar button). */
  toggleLodEnabled(): void {
    this.lodEnabled.update((v) => !v);
  }

  /** Set viewport culling on or off. */
  setViewportCullingEnabled(value: boolean): void {
    this.viewportCullingEnabled.set(value);
  }

  /** Toggle viewport culling (for toolbar button). */
  toggleViewportCulling(): void {
    this.viewportCullingEnabled.update((v) => !v);
  }

  /** Set default link routing (for new links and toolbar select when no links selected). */
  setDefaultLinkRouting(routing: LinkRouting): void {
    this.defaultLinkRouting.set(routing);
  }

  /** Set default max links per port (0 = unlimited). Used by toolbar "apply to all". */
  setDefaultMaxLinksPerPort(value: number): void {
    this.defaultMaxLinksPerPort.set(value);
  }

  private _nodeIdCounter = 0;
  private _linkIdCounter = 0;
  private _clipboard: DiagramJson | null = null;

  /** Current diagram instance (mutable). Use diagram() for reactive reads. */
  getDiagram(): Diagram | null {
    return this.diagram();
  }

  /** Set diagram and optionally bump render tick. */
  setDiagram(d: Diagram | null, bumpTick = true): void {
    this.diagram.set(d);
    if (bumpTick) this.incrementRenderTick();
  }

  /** Replace diagram with deserialized JSON; clear selection and sync id counters. Used by load/undo/redo. */
  setDiagramFromJson(json: DiagramJson): void {
    const d = deserializeDiagram(json);
    this.setDiagram(d, true);
    this.clearSelection();
    this.syncCountersFromDiagram();
  }

  /** Increment render tick to trigger template updates after in-place diagram mutations. */
  incrementRenderTick(): void {
    this.renderTick.update((v) => v + 1);
  }

  /** Sync node/link id counters from current diagram (e.g. after load/restore). */
  syncCountersFromDiagram(): void {
    const d = this.diagram();
    if (!d) return;
    let maxN = 0;
    let maxL = 0;
    for (const node of d.nodes) {
      const m = /^n(\d+)$/.exec(node.id);
      if (m) maxN = Math.max(maxN, parseInt(m[1], 10));
    }
    for (const link of d.links) {
      const m = /^l(\d+)$/.exec(link.id);
      if (m) maxL = Math.max(maxL, parseInt(m[1], 10));
    }
    this._nodeIdCounter = maxN;
    this._linkIdCounter = maxL;
  }

  /** Current node id counter (n1, n2, ...). */
  getNodeIdCounter(): number {
    return this._nodeIdCounter;
  }

  /** Set node id counter (e.g. after load or paste). */
  setNodeIdCounter(value: number): void {
    this._nodeIdCounter = value;
  }

  /** Increment and return new node id counter. */
  incrementNodeIdCounter(): number {
    this._nodeIdCounter++;
    return this._nodeIdCounter;
  }

  /** Current link id counter (l1, l2, ...). */
  getLinkIdCounter(): number {
    return this._linkIdCounter;
  }

  /** Set link id counter (e.g. after load or paste). */
  setLinkIdCounter(value: number): void {
    this._linkIdCounter = value;
  }

  /** Increment and return new link id counter. */
  incrementLinkIdCounter(): number {
    this._linkIdCounter++;
    return this._linkIdCounter;
  }

  /** Clipboard content (DiagramJson) for paste. */
  getClipboard(): DiagramJson | null {
    return this._clipboard;
  }

  /** Set clipboard (e.g. after copy). */
  setClipboard(json: DiagramJson | null): void {
    this._clipboard = json;
  }

  /** Clear node and link selection. */
  clearSelection(): void {
    this.selectedNodeIds.set(new Set());
    this.selectedLinkIds.set(new Set());
  }

  /** Set selected nodes and clear link selection. */
  setNodeSelection(ids: Set<NodeId>): void {
    this.selectedNodeIds.set(ids);
    this.selectedLinkIds.set(new Set());
  }

  /** Set selected links and clear node selection. */
  setLinkSelection(ids: Set<LinkId>): void {
    this.selectedLinkIds.set(ids);
    this.selectedNodeIds.set(new Set());
  }

  /** Set both node and link selection at once (e.g. rubber-band selection). */
  setNodeAndLinkSelection(nodeIds: Set<NodeId>, linkIds: Set<LinkId>): void {
    this.selectedNodeIds.set(nodeIds);
    this.selectedLinkIds.set(linkIds);
  }

  /** Toggle one node in selection (Shift+click); clear link selection. */
  toggleNodeSelection(nodeId: NodeId): void {
    const next = new Set(this.selectedNodeIds());
    if (next.has(nodeId)) next.delete(nodeId);
    else next.add(nodeId);
    this.selectedNodeIds.set(next);
    this.selectedLinkIds.set(new Set());
  }

  /** Toggle one link in selection (Shift+click); clear node selection. */
  toggleLinkSelection(linkId: LinkId): void {
    const next = new Set(this.selectedLinkIds());
    if (next.has(linkId)) next.delete(linkId);
    else next.add(linkId);
    this.selectedLinkIds.set(next);
    this.selectedNodeIds.set(new Set());
  }

  /** Select all nodes and links in the current diagram. */
  selectAllNodesAndLinks(): void {
    const d = this.diagram();
    if (!d) return;
    this.selectedNodeIds.set(new Set(d.nodes.map((n) => n.id)));
    this.selectedLinkIds.set(new Set(d.links.map((l) => l.id)));
  }

  /** Set linking-from state (start or cancel link drag). */
  setLinkingFrom(state: LinkingFromState | null): void {
    this.linkingFrom.set(state);
  }

  /** Set preview point for link-in-progress. */
  setLinkingPreviewPoint(point: { x: number; y: number } | null): void {
    this.linkingPreviewPoint.set(point);
  }

  /** Set viewBox (for pan/zoom). */
  setViewBox(vb: { x: number; y: number; width: number; height: number }): void {
    this.viewBox.set(vb);
  }

  /** Set rubber-band selection rectangle (null to clear). */
  setSelectionRect(rect: SelectionRect | null): void {
    this.selectionRect.set(rect);
  }

  /** Select all nodes whose rect intersects the given rect; clears selectionRect. */
  selectNodesInRect(rect: SelectionRect): void {
    const d = this.getDiagram();
    if (!d) {
      this.setSelectionRect(null);
      return;
    }
    const xMin = Math.min(rect.x1, rect.x2);
    const xMax = Math.max(rect.x1, rect.x2);
    const yMin = Math.min(rect.y1, rect.y2);
    const yMax = Math.max(rect.y1, rect.y2);
    const ids = new Set<NodeId>();
    for (const node of d.nodes) {
      const r = node.getRect();
      const intersects =
        r.x + r.width >= xMin &&
        r.x <= xMax &&
        r.y + r.height >= yMin &&
        r.y <= yMax;
      if (intersects) ids.add(node.id);
    }
    this.setNodeSelection(ids);
    this.setSelectionRect(null);
  }
}

import { Injectable } from '@angular/core';
import type { Diagram, Link, PointLike } from '../../../../graph-core';

/** Result of finding the closest path segment to a point: segment index and projected point. */
export interface ClosestSegmentResult {
  segIdx: number;
  projected: PointLike;
}

const HIT_TOLERANCE = 12;

/**
 * Geometry utilities for link paths: hit-test, orthogonal expansion, point projection.
 */
@Injectable({ providedIn: 'root' })
export class GraphLinkGeometryService {
  /**
   * Get all path points for hit-test and segment lookup.
   * For straight: [source, ...points, target].
   * For orthogonal: expanded path with corner points.
   */
  getPathPoints(link: Link, diagram: Diagram): PointLike[] {
    const source = diagram.getPortPosition(link.sourcePortId);
    const target = diagram.getPortPosition(link.targetPortId);
    if (!source || !target) return [];

    const pts: PointLike[] = [source, ...link.points, target];

    if (link.routing === 'orthogonal') {
      return this.expandOrthogonalPath(pts);
    }
    return pts;
  }

  /**
   * Expand path for orthogonal routing: insert corner points so each segment is H or V.
   */
  expandOrthogonalPath(pts: PointLike[]): PointLike[] {
    if (pts.length < 2) return pts;
    const result: PointLike[] = [pts[0]];

    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i];
      const b = pts[i + 1];
      if (a.x === b.x || a.y === b.y) {
        result.push(b);
      } else {
        result.push({ x: b.x, y: a.y });
        result.push(b);
      }
    }
    return result;
  }

  /**
   * Project point P onto segment A-B, clamped to the segment.
   */
  projectPointOnSegment(P: PointLike, A: PointLike, B: PointLike): PointLike {
    const ax = B.x - A.x;
    const ay = B.y - A.y;
    const lenSq = ax * ax + ay * ay;
    if (lenSq === 0) return { x: A.x, y: A.y };
    let t = ((P.x - A.x) * ax + (P.y - A.y) * ay) / lenSq;
    t = Math.max(0, Math.min(1, t));
    return { x: A.x + t * ax, y: A.y + t * ay };
  }

  /**
   * Distance from point P to segment A-B.
   */
  distanceToSegment(P: PointLike, A: PointLike, B: PointLike): number {
    const q = this.projectPointOnSegment(P, A, B);
    const dx = P.x - q.x;
    const dy = P.y - q.y;
    return Math.sqrt(dx * dx + dy * dy);
  }

  /**
   * Find the closest segment to point pt and the projected point on that segment.
   * @returns { segIdx, projected } or null if no segment within tolerance
   */
  findClosestSegment(
    pts: PointLike[],
    pt: PointLike,
    tolerance = HIT_TOLERANCE
  ): ClosestSegmentResult | null {
    if (pts.length < 2) return null;
    let bestDist = tolerance;
    let bestSegIdx = -1;
    let bestProjected: PointLike = { x: pt.x, y: pt.y };

    for (let i = 0; i < pts.length - 1; i++) {
      const dist = this.distanceToSegment(pt, pts[i], pts[i + 1]);
      if (dist < bestDist) {
        bestDist = dist;
        bestSegIdx = i;
        bestProjected = this.projectPointOnSegment(pt, pts[i], pts[i + 1]);
      }
    }
    if (bestSegIdx >= 0) {
      return { segIdx: bestSegIdx, projected: bestProjected };
    }
    return null;
  }

  /**
   * Snap a newly inserted waypoint for orthogonal routing.
   * Keeps one coordinate from prev and one from next so segments stay H or V.
   */
  snapToOrthogonal(
    inserted: PointLike,
    prev: PointLike,
    next: PointLike
  ): PointLike {
    const dxPrev = Math.abs(inserted.x - prev.x);
    const dyPrev = Math.abs(inserted.y - prev.y);
    const dxNext = Math.abs(inserted.x - next.x);
    const dyNext = Math.abs(inserted.y - next.y);
    if (dxPrev < dyPrev) {
      return { x: prev.x, y: next.y };
    }
    return { x: next.x, y: prev.y };
  }

  /**
   * Map segment index (from findClosestSegment on getPathPoints result) to link.points insert index.
   * For straight: segIdx equals insert index.
   * For orthogonal: count waypoints that appear at or before segment start in expanded path.
   */
  segmentToPointInsertIndex(link: Link, diagram: Diagram, segIdx: number): number {
    const pts = this.getPathPoints(link, diagram);
    if (segIdx < 0 || segIdx >= pts.length - 1) return 0;
    if (link.routing === 'straight') return segIdx;

    const source = diagram.getPortPosition(link.sourcePortId)!;
    const target = diagram.getPortPosition(link.targetPortId)!;
    const waypoints = link.points;
    if (waypoints.length === 0) return 0;

    const expanded = this.expandOrthogonalPath([source, ...waypoints, target]);
    let insertIdx = 0;
    for (const wp of waypoints) {
      const wpIdx = expanded.findIndex((p) => p.x === wp.x && p.y === wp.y);
      if (wpIdx >= 0 && wpIdx <= segIdx) insertIdx++;
    }
    return insertIdx;
  }
}

import { Injectable } from '@angular/core';
import type { Diagram, Link, Node } from '../../../../graph-core';
import type { NodeId, LinkId } from '../../../../graph-core';
import type { PointLike, Rect } from '../../../../graph-core';
import { GraphLinkGeometryService } from './graph-link-geometry.service';
import { GRID_STEP } from './graph-coordinate.service';
import { getVisibleInViewBox } from './viewport-culling';

export interface LodCanvasDrawOptions {
  gridVisible?: boolean;
  gridStep?: number;
  /** When true (default), only draw nodes/links intersecting viewBox. When false, draw all. */
  viewportCulling?: boolean;
}

/** Encode hit index to RGB. Use 1-based: 0 = no hit, 1..n = nodes, n+1..n+m = links. Max ~16M. */
export function indexToRgb(index: number): string {
  if (index <= 0) return 'rgb(0,0,0)';
  const r = index & 0xff;
  const g = (index >> 8) & 0xff;
  const b = (index >> 16) & 0xff;
  return `rgb(${r},${g},${b})`;
}

/** Decode RGB from ImageData to 1-based hit index. Returns 0 if no hit. */
export function rgbToIndex(r: number, g: number, b: number): number {
  return r + (g << 8) + (b << 16);
}

export interface HitBufferResult {
  nodeIds: NodeId[];
  linkIds: LinkId[];
}

/**
 * Draws the graph diagram onto a 2D canvas for LOD (Level of Detail) when zoomed out.
 * Transforms SVG coordinates to canvas pixels via viewBox. Draws grid (optional), links, then nodes.
 */
@Injectable({ providedIn: 'root' })
export class GraphLodCanvasService {
  constructor(private readonly linkGeometry: GraphLinkGeometryService) {}

  /**
   * Draw diagram onto the canvas. Coordinate transform: svg -> px
   * pxX = (svgX - viewBox.x) / viewBox.width * canvasWidth, same for Y.
   */
  draw(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    options: LodCanvasDrawOptions = {}
  ): void {
    const { gridVisible = false, gridStep = GRID_STEP, viewportCulling = true } = options;

    const toPx = (svgX: number, svgY: number): { x: number; y: number } => ({
      x: ((svgX - viewBox.x) / viewBox.width) * canvasWidth,
      y: ((svgY - viewBox.y) / viewBox.height) * canvasHeight,
    });

    ctx.save();
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    if (gridVisible && viewBox.width > 0 && viewBox.height > 0) {
      this.drawGrid(ctx, viewBox, canvasWidth, canvasHeight, gridStep, toPx);
    }

    const { nodeIds: visibleNodeIds, linkIds: visibleLinkIds } =
      viewportCulling && viewBox.width > 0 && viewBox.height > 0
        ? getVisibleInViewBox(diagram, viewBox as Rect, this.linkGeometry)
        : {
            nodeIds: new Set(diagram.nodes.map((n) => n.id)),
            linkIds: new Set(diagram.links.map((l) => l.id)),
          };

    const links = [...diagram.links]
      .filter((l) => visibleLinkIds.has(l.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    for (const link of links) {
      this.drawLink(ctx, diagram, link, toPx);
    }

    const nodes = [...diagram.nodes]
      .filter((n) => visibleNodeIds.has(n.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    for (const node of nodes) {
      this.drawNode(ctx, node, toPx);
    }

    ctx.restore();
  }

  /**
   * Draw hit buffer: same geometry as draw(), but each node/link filled with encoded index color.
   * Index 1..nodeCount = nodes, nodeCount+1..nodeCount+linkCount = links. 0 = no hit.
   * Caller uses nodeIds = diagram.nodes.map(n => n.id), linkIds = diagram.links.map(l => l.id) for decode.
   */
  drawHitBuffer(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    options: LodCanvasDrawOptions = {}
  ): HitBufferResult {
    const { viewportCulling = true } = options;

    const toPx = (svgX: number, svgY: number): { x: number; y: number } => ({
      x: ((svgX - viewBox.x) / viewBox.width) * canvasWidth,
      y: ((svgY - viewBox.y) / viewBox.height) * canvasHeight,
    });

    ctx.save();
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    const { nodeIds: visibleNodeIds, linkIds: visibleLinkIds } =
      viewportCulling && viewBox.width > 0 && viewBox.height > 0
        ? getVisibleInViewBox(diagram, viewBox as Rect, this.linkGeometry)
        : {
            nodeIds: new Set(diagram.nodes.map((n) => n.id)),
            linkIds: new Set(diagram.links.map((l) => l.id)),
          };

    const links = [...diagram.links]
      .filter((l) => visibleLinkIds.has(l.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    const nodes = [...diagram.nodes]
      .filter((n) => visibleNodeIds.has(n.id))
      .sort((a, b) => a.zIndex - b.zIndex);
    const nodeIds: NodeId[] = nodes.map((n) => n.id);
    const linkIds: LinkId[] = links.map((l) => l.id);

    links.forEach((link, j) => {
      ctx.fillStyle = indexToRgb(nodeIds.length + 1 + j);
      this.drawLinkPathOnly(ctx, diagram, link, toPx);
    });
    nodes.forEach((node, i) => {
      ctx.fillStyle = indexToRgb(i + 1);
      this.drawNodePathOnly(ctx, node, toPx);
    });

    ctx.restore();
    return { nodeIds, linkIds };
  }

  private drawLinkPathOnly(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    link: Link,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const pts = this.linkGeometry.getPathPoints(link, diagram);
    if (pts.length < 2) return;
    ctx.beginPath();
    const first = toPx(pts[0].x, pts[0].y);
    ctx.moveTo(first.x, first.y);
    for (let i = 1; i < pts.length; i++) {
      const p = toPx(pts[i].x, pts[i].y);
      ctx.lineTo(p.x, p.y);
    }
    ctx.strokeStyle = ctx.fillStyle!;
    ctx.lineWidth = 20;
    ctx.stroke();
  }

  private drawNodePathOnly(
    ctx: CanvasRenderingContext2D,
    node: Node,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const r = node.getRect();
    const x = r.x;
    const y = r.y;
    const w = r.width;
    const h = r.height;
    const cx = x + w / 2;
    const cy = y + h / 2;

    const tl = toPx(x, y);
    const br = toPx(x + w, y + h);
    const pxW = br.x - tl.x;
    const pxH = br.y - tl.y;
    const pxCx = tl.x + pxW / 2;
    const pxCy = tl.y + pxH / 2;

    ctx.beginPath();
    switch (node.shape) {
      case 'roundedRect': {
        const rx = Math.min(pxW / 4, 30);
        const ry = Math.min(pxH / 4, 15);
        this.roundRect(ctx, tl.x, tl.y, pxW, pxH, rx, ry);
        break;
      }
      case 'circle':
      case 'ellipse':
        ctx.ellipse(pxCx, pxCy, pxW / 2, pxH / 2, 0, 0, Math.PI * 2);
        break;
      case 'diamond': {
        const dx = toPx(cx, y);
        const dy = toPx(cx, y + h);
        const l = toPx(x, cy);
        const ri = toPx(x + w, cy);
        ctx.moveTo(dx.x, dx.y);
        ctx.lineTo(ri.x, ri.y);
        ctx.lineTo(dy.x, dy.y);
        ctx.lineTo(l.x, l.y);
        ctx.closePath();
        break;
      }
      case 'triangle': {
        const t = toPx(cx, y);
        const bl = toPx(x, y + h);
        const br_ = toPx(x + w, y + h);
        ctx.moveTo(t.x, t.y);
        ctx.lineTo(br_.x, br_.y);
        ctx.lineTo(bl.x, bl.y);
        ctx.closePath();
        break;
      }
      default:
        ctx.rect(tl.x, tl.y, pxW, pxH);
        break;
    }
    ctx.fill();
  }

  private drawGrid(
    ctx: CanvasRenderingContext2D,
    viewBox: { x: number; y: number; width: number; height: number },
    canvasWidth: number,
    canvasHeight: number,
    gridStep: number,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--grid-stroke')
      .trim() || '#ddd';
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 0.5;

    const xMin = Math.floor(viewBox.x / gridStep) * gridStep;
    const xMax = viewBox.x + viewBox.width;
    const yMin = Math.floor(viewBox.y / gridStep) * gridStep;
    const yMax = viewBox.y + viewBox.height;

    ctx.beginPath();
    for (let x = xMin; x <= xMax; x += gridStep) {
      const p0 = toPx(x, viewBox.y);
      const p1 = toPx(x, viewBox.y + viewBox.height);
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
    }
    for (let y = yMin; y <= yMax; y += gridStep) {
      const p0 = toPx(viewBox.x, y);
      const p1 = toPx(viewBox.x + viewBox.width, y);
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
    }
    ctx.stroke();
  }

  private drawLink(
    ctx: CanvasRenderingContext2D,
    diagram: Diagram,
    link: Link,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const pts = this.linkGeometry.getPathPoints(link, diagram);
    if (pts.length < 2) return;

    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--link-stroke')
      .trim() || '#666';
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 2;
    ctx.beginPath();
    const first = toPx(pts[0].x, pts[0].y);
    ctx.moveTo(first.x, first.y);
    for (let i = 1; i < pts.length; i++) {
      const p = toPx(pts[i].x, pts[i].y);
      ctx.lineTo(p.x, p.y);
    }
    ctx.stroke();
  }

  private drawNode(
    ctx: CanvasRenderingContext2D,
    node: Node,
    toPx: (x: number, y: number) => { x: number; y: number }
  ): void {
    const r = node.getRect();
    const x = r.x;
    const y = r.y;
    const w = r.width;
    const h = r.height;
    const cx = x + w / 2;
    const cy = y + h / 2;

    const tl = toPx(x, y);
    const br = toPx(x + w, y + h);
    const pxW = br.x - tl.x;
    const pxH = br.y - tl.y;
    const pxCx = tl.x + pxW / 2;
    const pxCy = tl.y + pxH / 2;

    const fill = getComputedStyle(document.documentElement)
      .getPropertyValue('--node-fill')
      .trim() || '#fff';
    const stroke = getComputedStyle(document.documentElement)
      .getPropertyValue('--node-stroke')
      .trim() || '#333';
    ctx.fillStyle = fill;
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1.5;

    ctx.beginPath();
    switch (node.shape) {
      case 'roundedRect':
        const rx = Math.min(pxW / 4, 30);
        const ry = Math.min(pxH / 4, 15);
        this.roundRect(ctx, tl.x, tl.y, pxW, pxH, rx, ry);
        break;
      case 'circle':
      case 'ellipse':
        ctx.ellipse(pxCx, pxCy, pxW / 2, pxH / 2, 0, 0, Math.PI * 2);
        break;
      case 'diamond': {
        const dx = toPx(cx, y);
        const dy = toPx(cx, y + h);
        const l = toPx(x, cy);
        const ri = toPx(x + w, cy);
        ctx.moveTo(dx.x, dx.y);
        ctx.lineTo(ri.x, ri.y);
        ctx.lineTo(dy.x, dy.y);
        ctx.lineTo(l.x, l.y);
        ctx.closePath();
        break;
      }
      case 'triangle': {
        const t = toPx(cx, y);
        const bl = toPx(x, y + h);
        const br_ = toPx(x + w, y + h);
        ctx.moveTo(t.x, t.y);
        ctx.lineTo(br_.x, br_.y);
        ctx.lineTo(bl.x, bl.y);
        ctx.closePath();
        break;
      }
      case 'hexagon':
      case 'parallelogram':
      case 'pentagon':
      case 'cross':
      case 'custom':
      case 'rectangle':
      default:
        ctx.rect(tl.x, tl.y, pxW, pxH);
        break;
    }
    ctx.fill();
    ctx.stroke();
  }

  private roundRect(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
    rx: number,
    ry: number
  ): void {
    ctx.moveTo(x + rx, y);
    ctx.lineTo(x + w - rx, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + ry);
    ctx.lineTo(x + w, y + h - ry);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rx, y + h);
    ctx.lineTo(x + rx, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - ry);
    ctx.lineTo(x, y + ry);
    ctx.quadraticCurveTo(x, y, x + rx, y);
  }
}

import { Injectable } from '@angular/core';
import { GroupNode } from '../../../../graph-core';
import type { LinkId, LinkRouting, NodeId, NodeShape, PortId } from '../../../../graph-core';
import { GraphEditorStateService } from './graph-editor-state.service';
import { GraphEditorActionDispatcher } from '../actions/action-dispatcher.service';
import {
  AddNodeAction,
  AddNodeFromPaletteAction,
  MoveNodesAction,
  RotateNodesAction,
  AlignNodesAction,
  GroupNodesAction,
  UngroupNodeAction,
  ResizeGroupNodeAction,
  CreateLinkAction,
  SetSelectedLinksRoutingAction,
  SetPortMaxLinksAction,
  AddLinkWaypointAction,
  MoveLinkWaypointAction,
  RemoveLinkWaypointAction,
  MoveLinkSegmentAction,
  ClearLinkWaypointsAction,
  CopyAction,
  PasteAction,
  DeleteSelectionAction,
  BringToFrontAction,
  SendToBackAction,
  ToggleLockSelectionAction,
} from '../actions';
import type { AlignMode } from '../actions';

/** Re-export for consumers that import from the operations service. */
export type { AlignMode };

/**
 * Facade over graph editor actions. All mutating operations are delegated to
 * {@link GraphEditorActionDispatcher}; return values and pre-checks (e.g. group delete
 * confirmation) are handled here for API compatibility with the component and resize service.
 */
@Injectable()
export class GraphOperationsService {
  constructor(
    private readonly state: GraphEditorStateService,
    private readonly dispatcher: GraphEditorActionDispatcher
  ) {}

  addNode(): void {
    this.dispatcher.dispatch(new AddNodeAction());
  }

  addNodeFromPalette(
    shape: NodeShape,
    svgX: number,
    svgY: number,
    customShapeId?: string
  ): void {
    this.dispatcher.dispatch(new AddNodeFromPaletteAction(shape, svgX, svgY, customShapeId));
  }

  moveNodes(
    initialPositions: Map<NodeId, { x: number; y: number }>,
    dx: number,
    dy: number
  ): void {
    this.dispatcher.dispatch(new MoveNodesAction(initialPositions, dx, dy));
  }

  rotateSelectedNodes(angleDeg: number): void {
    this.dispatcher.dispatch(new RotateNodesAction(angleDeg));
  }

  alignSelectedNodes(mode: AlignMode): void {
    this.dispatcher.dispatch(new AlignNodesAction(mode));
  }

  createLink(
    sourcePortId: PortId,
    _sourceNodeId: NodeId,
    targetPortId: PortId,
    targetNodeId: NodeId
  ): void {
    this.dispatcher.dispatch(new CreateLinkAction(sourcePortId, targetPortId, targetNodeId));
  }

  /** Set max links per port on all ports of the given nodes. */
  setPortMaxLinksForNodes(nodeIds: NodeId[], value: number): void {
    if (nodeIds.length === 0) return;
    this.dispatcher.dispatch(new SetPortMaxLinksAction(nodeIds, value));
  }

  setSelectedLinksRouting(routing: LinkRouting): boolean {
    const d = this.state.getDiagram();
    const linkIds = this.state.selectedLinkIds();
    if (!d || linkIds.size === 0) return false;
    this.dispatcher.dispatch(new SetSelectedLinksRoutingAction(routing));
    return true;
  }

  deleteSelection(): boolean {
    const d = this.state.getDiagram();
    if (!d) return false;
    const nodeIds = this.state.selectedNodeIds();
    const linkIds = this.state.selectedLinkIds();
    if (nodeIds.size === 0 && linkIds.size === 0) return false;
    let hasGroups = false;
    for (const nodeId of nodeIds) {
      const node = d.getNode(nodeId);
      if (node instanceof GroupNode) {
        hasGroups = true;
        break;
      }
    }
    if (hasGroups && !DeleteSelectionAction.confirmGroupDelete()) return false;
    this.dispatcher.dispatch(new DeleteSelectionAction());
    return true;
  }

  copy(): void {
    this.dispatcher.dispatch(new CopyAction());
  }

  paste(): boolean {
    const clipboard = this.state.getClipboard();
    const d = this.state.getDiagram();
    if (!clipboard || !d) return false;
    this.dispatcher.dispatch(new PasteAction());
    return true;
  }

  /** Duplicate selection (copy then paste with offset). Uses undo; selects pasted nodes. */
  duplicateSelection(): void {
    const nodeIds = this.state.selectedNodeIds();
    if (nodeIds.size === 0) return;
    this.copy();
    this.paste();
  }

  addLinkWaypoint(linkId: LinkId, index: number, x: number, y: number): boolean {
    const d = this.state.getDiagram();
    const link = d?.getLink(linkId);
    if (!d || !link) return false;
    this.dispatcher.dispatch(new AddLinkWaypointAction(linkId, index, x, y));
    return true;
  }

  moveLinkWaypoint(linkId: LinkId, index: number, x: number, y: number): boolean {
    const d = this.state.getDiagram();
    const link = d?.getLink(linkId);
    if (!d || !link || index < 0 || index >= link.points.length) return false;
    this.dispatcher.dispatch(new MoveLinkWaypointAction(linkId, index, x, y));
    return true;
  }

  removeLinkWaypoint(linkId: LinkId, index: number): boolean {
    const d = this.state.getDiagram();
    const link = d?.getLink(linkId);
    if (!d || !link || index < 0 || index >= link.points.length) return false;
    this.dispatcher.dispatch(new RemoveLinkWaypointAction(linkId, index));
    return true;
  }

  moveLinkSegment(linkId: LinkId, segmentIndex: number, dx: number, dy: number): boolean {
    const d = this.state.getDiagram();
    const link = d?.getLink(linkId);
    if (!d || !link || link.points.length === 0) return false;
    this.dispatcher.dispatch(new MoveLinkSegmentAction(linkId, segmentIndex, dx, dy));
    return true;
  }

  clearLinkWaypoints(linkId: LinkId): boolean {
    const d = this.state.getDiagram();
    const link = d?.getLink(linkId);
    if (!d || !link || link.points.length === 0) return false;
    this.dispatcher.dispatch(new ClearLinkWaypointsAction(linkId));
    return true;
  }

  groupSelectedNodes(): boolean {
    const d = this.state.getDiagram();
    const selectedNodeIds = this.state.selectedNodeIds();
    if (!d || selectedNodeIds.size < 2) return false;
    for (const nodeId of selectedNodeIds) {
      const node = d.getNode(nodeId);
      if (!node || node.nodeType === 'group') return false;
    }
    this.dispatcher.dispatch(new GroupNodesAction());
    return true;
  }

  ungroupNode(groupId: NodeId): boolean {
    const d = this.state.getDiagram();
    const groupNode = d?.getNode(groupId);
    if (!d || !groupNode || !(groupNode instanceof GroupNode)) return false;
    this.dispatcher.dispatch(new UngroupNodeAction(groupId));
    return true;
  }

  resizeGroupNode(groupId: NodeId, newWidth: number, newHeight: number): void {
    this.dispatcher.dispatch(new ResizeGroupNodeAction(groupId, newWidth, newHeight));
  }

  bringToFront(): boolean {
    const d = this.state.getDiagram();
    if (!d) return false;
    const hasSelection =
      this.state.selectedNodeIds().size > 0 || this.state.selectedLinkIds().size > 0;
    if (!hasSelection) return false;
    this.dispatcher.dispatch(new BringToFrontAction());
    return true;
  }

  sendToBack(): boolean {
    const d = this.state.getDiagram();
    if (!d) return false;
    const hasSelection =
      this.state.selectedNodeIds().size > 0 || this.state.selectedLinkIds().size > 0;
    if (!hasSelection) return false;
    this.dispatcher.dispatch(new SendToBackAction());
    return true;
  }

  toggleLockSelection(): boolean {
    const d = this.state.getDiagram();
    if (!d) return false;
    const hasSelection =
      this.state.selectedNodeIds().size > 0 || this.state.selectedLinkIds().size > 0;
    if (!hasSelection) return false;
    this.dispatcher.dispatch(new ToggleLockSelectionAction());
    return true;
  }
}

import { inject, Injectable } from '@angular/core';
import { GroupNode } from '../../../../graph-core';
import type { NodeId } from '../../../../graph-core';
import { GraphEditorStateService } from './graph-editor-state.service';
import { GraphOperationsService } from './graph-operations.service';
import { GraphUndoRedoService } from './graph-undo-redo.service';
import { GRAPH_EDITOR_CONFIG } from '../config/graph-editor-config';

export type ResizeHandle = 'nw' | 'n' | 'ne' | 'e' | 'se' | 's' | 'sw' | 'w';

interface ResizeState {
  nodeId: NodeId;
  handle: ResizeHandle;
  initialWidth: number;
  initialHeight: number;
  initialX: number;
  initialY: number;
  startX: number;
  startY: number;
}

/**
 * Service for handling node resize operations (primarily for GroupNodes).
 * Manages resize state and applies transformations based on handle dragging.
 */
@Injectable()
export class GraphResizeService {
  private resizeState: ResizeState | null = null;
  private readonly configSignal = inject(GRAPH_EDITOR_CONFIG, { optional: true });

  constructor(
    private state: GraphEditorStateService,
    private operations: GraphOperationsService,
    private undoRedo: GraphUndoRedoService
  ) {}

  /**
   * Start a resize operation.
   * @param nodeId - ID of the node being resized
   * @param handle - Which resize handle was grabbed
   * @param startX - Initial pointer X position (SVG coordinates)
   * @param startY - Initial pointer Y position (SVG coordinates)
   */
  startResize(nodeId: NodeId, handle: ResizeHandle, startX: number, startY: number): boolean {
    const d = this.state.getDiagram();
    const node = d?.getNode(nodeId);
    if (!d || !node || !(node instanceof GroupNode)) return false;

    const cfg = this.configSignal?.();
    if (cfg?.undoRedo?.enabled !== false) {
      this.undoRedo.pushState();
    }

    this.resizeState = {
      nodeId,
      handle,
      initialWidth: node.width,
      initialHeight: node.height,
      initialX: node.x,
      initialY: node.y,
      startX,
      startY,
    };

    return true;
  }

  /**
   * Update the resize based on current pointer position.
   * @param currentX - Current pointer X position (SVG coordinates)
   * @param currentY - Current pointer Y position (SVG coordinates)
   */
  updateResize(currentX: number, currentY: number): boolean {
    if (!this.resizeState) return false;

    const d = this.state.getDiagram();
    const node = d?.getNode(this.resizeState.nodeId);
    if (!d || !node || !(node instanceof GroupNode)) return false;

    const dx = currentX - this.resizeState.startX;
    const dy = currentY - this.resizeState.startY;

    let newWidth = this.resizeState.initialWidth;
    let newHeight = this.resizeState.initialHeight;
    let newX = this.resizeState.initialX;
    let newY = this.resizeState.initialY;

    // Apply resize based on handle
    switch (this.resizeState.handle) {
      case 'nw':
        newWidth = this.resizeState.initialWidth - dx;
        newHeight = this.resizeState.initialHeight - dy;
        newX = this.resizeState.initialX + dx;
        newY = this.resizeState.initialY + dy;
        break;
      case 'n':
        newHeight = this.resizeState.initialHeight - dy;
        newY = this.resizeState.initialY + dy;
        break;
      case 'ne':
        newWidth = this.resizeState.initialWidth + dx;
        newHeight = this.resizeState.initialHeight - dy;
        newY = this.resizeState.initialY + dy;
        break;
      case 'e':
        newWidth = this.resizeState.initialWidth + dx;
        break;
      case 'se':
        newWidth = this.resizeState.initialWidth + dx;
        newHeight = this.resizeState.initialHeight + dy;
        break;
      case 's':
        newHeight = this.resizeState.initialHeight + dy;
        break;
      case 'sw':
        newWidth = this.resizeState.initialWidth - dx;
        newHeight = this.resizeState.initialHeight + dy;
        newX = this.resizeState.initialX + dx;
        break;
      case 'w':
        newWidth = this.resizeState.initialWidth - dx;
        newX = this.resizeState.initialX + dx;
        break;
    }

    // Apply minimum size constraints
    const minWidth = 100;
    const minHeight = 80;

    if (newWidth < minWidth) {
      if (this.resizeState.handle.includes('w')) {
        newX = this.resizeState.initialX + this.resizeState.initialWidth - minWidth;
      }
      newWidth = minWidth;
    }

    if (newHeight < minHeight) {
      if (this.resizeState.handle.includes('n')) {
        newY = this.resizeState.initialY + this.resizeState.initialHeight - minHeight;
      }
      newHeight = minHeight;
    }

    // Update node position and size
    node.setPosition(newX, newY);
    this.operations.resizeGroupNode(this.resizeState.nodeId, newWidth, newHeight);

    return true;
  }

  /**
   * End the resize operation.
   */
  endResize(): void {
    if (!this.resizeState) return;

    this.resizeState = null;
    
    // Force a render update
    this.state.incrementRenderTick();
  }

  /**
   * Check if a resize operation is currently active.
   */
  isResizing(): boolean {
    return this.resizeState !== null;
  }

  /**
   * Get the current resize state (for debugging or UI feedback).
   */
  getResizeState(): ResizeState | null {
    return this.resizeState;
  }
}

import { Injectable } from '@angular/core';
import { serializeDiagram } from '../../../../graph-core';
import type { DiagramJson } from '../../../../graph-core';
import { GraphEditorStateService } from './graph-editor-state.service';

const MAX_UNDO = 50;

/**
 * Manages undo/redo history for the graph editor. Pushes snapshots of the diagram (DiagramJson)
 * before mutations; restore replaces current diagram and selection via state service.
 * Max undo steps: 50.
 */
@Injectable({ providedIn: 'root' })
export class GraphUndoRedoService {
  private _undoStack: DiagramJson[] = [];
  private _redoStack: DiagramJson[] = [];

  constructor(private state: GraphEditorStateService) {}

  /**
   * Push current diagram state onto undo stack and clear redo.
   * Call once before a user-triggered mutation (add node, delete, create link, paste, drag start).
   */
  pushState(): void {
    const d = this.state.getDiagram();
    if (!d) return;
    this._undoStack.push(serializeDiagram(d));
    if (this._undoStack.length > MAX_UNDO) {
      this._undoStack.shift();
    }
    this._redoStack = [];
  }

  /** Restore diagram and selection from JSON; used by load, undo, redo. Clears selection. */
  restoreFromJson(json: DiagramJson): void {
    this.state.setDiagramFromJson(json);
  }

  /** Undo one step: push current to redo, pop from undo and restore. */
  undo(): boolean {
    const d = this.state.getDiagram();
    if (this._undoStack.length === 0 || !d) return false;
    this._redoStack.push(serializeDiagram(d));
    const json = this._undoStack.pop()!;
    this.restoreFromJson(json);
    return true;
  }

  /** Redo one step: push current to undo, pop from redo and restore. */
  redo(): boolean {
    const d = this.state.getDiagram();
    if (this._redoStack.length === 0 || !d) return false;
    this._undoStack.push(serializeDiagram(d));
    const json = this._redoStack.pop()!;
    this.restoreFromJson(json);
    return true;
  }

  get canUndo(): boolean {
    return this._undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this._redoStack.length > 0;
  }
}

import { Injectable } from '@angular/core';
import type { NodeId } from '../../../../graph-core';
import type { Rect } from '../../../../graph-core';
import { GraphEditorStateService } from './graph-editor-state.service';

const DEFAULT_VIEW_WIDTH = 800;
const DEFAULT_VIEW_HEIGHT = 600;
const MIN_ZOOM = 0.1;
const MAX_ZOOM = 10;
const DEFAULT_ZOOM_FACTOR = 1.2;
const FIT_PADDING = 40;

/**
 * Service for pan/zoom and "zoom to" operations. Reads and updates viewBox via GraphEditorStateService.
 * All viewport logic is here; component passes container dimensions for fit/zoom-to-node/selection.
 */
@Injectable({ providedIn: 'root' })
export class GraphViewportService {
  constructor(private readonly state: GraphEditorStateService) {}

  /**
   * Pan the view by dx, dy in SVG coordinates.
   * @param dx - Horizontal delta (positive = move view left)
   * @param dy - Vertical delta (positive = move view up)
   */
  pan(dx: number, dy: number): void {
    const vb = this.state.viewBox();
    this.state.setViewBox({
      ...vb,
      x: vb.x - dx,
      y: vb.y - dy,
    });
  }

  /**
   * Zoom by factor around an optional center point (SVG coords).
   * Factor > 1 zooms in, < 1 zooms out. If center omitted, uses viewBox center.
   * @param factor - Zoom factor
   * @param centerInSvg - Optional center point in diagram coordinates
   */
  zoomAt(factor: number, centerInSvg?: { x: number; y: number }): void {
    const vb = this.state.viewBox();
    let newW = vb.width / factor;
    let newH = vb.height / factor;
    const scaleW = DEFAULT_VIEW_WIDTH / newW;
    const scaleH = DEFAULT_VIEW_HEIGHT / newH;
    const scale = Math.min(scaleW, scaleH);
    const clampedScale = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, scale));
    newW = DEFAULT_VIEW_WIDTH / clampedScale;
    newH = DEFAULT_VIEW_HEIGHT / clampedScale;

    const cx = centerInSvg?.x ?? vb.x + vb.width / 2;
    const cy = centerInSvg?.y ?? vb.y + vb.height / 2;
    const newX = cx - ((cx - vb.x) * newW) / vb.width;
    const newY = cy - ((cy - vb.y) * newH) / vb.height;

    this.state.setViewBox({
      x: newX,
      y: newY,
      width: newW,
      height: newH,
    });
  }

  /** Zoom in/out around view center. Factor > 1 = zoom in. */
  zoomToCenter(factor: number): void {
    this.zoomAt(factor);
  }

  /**
   * Set viewBox so the given node is centered with padding.
   * Preserves aspect ratio from containerWidth/containerHeight if provided.
   * @param nodeId - Node to center
   * @param padding - Padding around the node
   * @param containerWidth - Optional container width for aspect ratio
   * @param containerHeight - Optional container height for aspect ratio
   */
  zoomToNode(
    nodeId: NodeId,
    padding: number = FIT_PADDING,
    containerWidth?: number,
    containerHeight?: number
  ): void {
    const d = this.state.getDiagram();
    if (!d) return;
    const node = d.getNode(nodeId);
    if (!node) return;
    const r = node.getRect();
    this.fitRect(
      { x: r.x, y: r.y, width: r.width, height: r.height },
      padding,
      containerWidth,
      containerHeight
    );
  }

  /**
   * Set viewBox to fit selected nodes with padding. If no selection, does nothing.
   * @param padding - Padding around the selection
   * @param containerWidth - Optional container width
   * @param containerHeight - Optional container height
   */
  zoomToSelection(
    padding: number = FIT_PADDING,
    containerWidth?: number,
    containerHeight?: number
  ): void {
    const d = this.state.getDiagram();
    const ids = this.state.selectedNodeIds();
    if (!d || ids.size === 0) return;
    const rect = this.bboxOfNodeIds(d, ids);
    if (!rect) return;
    this.fitRect(rect, padding, containerWidth, containerHeight);
  }

  /**
   * Fit all nodes (or default rect) in view with padding.
   * Uses container aspect ratio when containerWidth and containerHeight are provided.
   * @param padding - Padding around content
   * @param containerWidth - Optional container width
   * @param containerHeight - Optional container height
   */
  fitToView(
    padding: number = FIT_PADDING,
    containerWidth?: number,
    containerHeight?: number
  ): void {
    const d = this.state.getDiagram();
    const rect = d && d.nodes.length > 0
      ? this.bboxOfNodes(d.nodes.map((n) => n.getRect()))
      : {
          x: 0,
          y: 0,
          width: DEFAULT_VIEW_WIDTH,
          height: DEFAULT_VIEW_HEIGHT,
        };
    this.fitRect(rect, padding, containerWidth, containerHeight);
  }

  /** Zoom in one step (toolbar). */
  zoomIn(): void {
    this.zoomToCenter(DEFAULT_ZOOM_FACTOR);
  }

  /** Zoom out one step (toolbar). */
  zoomOut(): void {
    this.zoomToCenter(1 / DEFAULT_ZOOM_FACTOR);
  }

  /**
   * Reset zoom to 100% (1:1). Keeps view center; container size determines viewBox size.
   * @param containerWidth - Container width in pixels
   * @param containerHeight - Container height in pixels
   */
  resetZoom(containerWidth: number, containerHeight: number): void {
    const vb = this.state.viewBox();
    const cx = vb.x + vb.width / 2;
    const cy = vb.y + vb.height / 2;
    this.state.setViewBox({
      x: cx - containerWidth / 2,
      y: cy - containerHeight / 2,
      width: containerWidth,
      height: containerHeight,
    });
  }

  private bboxOfNodeIds(
    d: { getNode(id: NodeId): { getRect(): Rect } | undefined },
    ids: Set<NodeId>
  ): Rect | null {
    const rects: Rect[] = [];
    for (const id of ids) {
      const node = d.getNode(id);
      if (node) rects.push(node.getRect());
    }
    return rects.length > 0 ? this.bboxOfNodes(rects) : null;
  }

  private bboxOfNodes(rects: Rect[]): Rect {
    let xMin = rects[0].x;
    let yMin = rects[0].y;
    let xMax = rects[0].x + rects[0].width;
    let yMax = rects[0].y + rects[0].height;
    for (let i = 1; i < rects.length; i++) {
      const r = rects[i];
      xMin = Math.min(xMin, r.x);
      yMin = Math.min(yMin, r.y);
      xMax = Math.max(xMax, r.x + r.width);
      yMax = Math.max(yMax, r.y + r.height);
    }
    return {
      x: xMin,
      y: yMin,
      width: xMax - xMin,
      height: yMax - yMin,
    };
  }

  private fitRect(
    rect: Rect,
    padding: number,
    containerWidth?: number,
    containerHeight?: number
  ): void {
    const contentW = rect.width + 2 * padding;
    const contentH = rect.height + 2 * padding;
    const contentCenterX = rect.x + rect.width / 2;
    const contentCenterY = rect.y + rect.height / 2;

    const cw = containerWidth ?? DEFAULT_VIEW_WIDTH;
    const ch = containerHeight ?? DEFAULT_VIEW_HEIGHT;
    const viewAspect = cw / ch;
    const contentAspect = contentW / contentH;

    let w: number;
    let h: number;
    if (contentAspect > viewAspect) {
      w = contentW;
      h = contentW / viewAspect;
    } else {
      h = contentH;
      w = contentH * viewAspect;
    }

    this.state.setViewBox({
      x: contentCenterX - w / 2,
      y: contentCenterY - h / 2,
      width: w,
      height: h,
    });
  }
}

