/**
 * Delete all selected nodes and links.
 * Pushes undo before deleting. For group nodes, the implementation checks
 * and the UI may show a confirmation dialog before dispatching (handled in component/facade).
 */
export class DeleteSelectionAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  /** If true, caller should skip dispatch when user cancels group-delete confirmation. */
  static confirmGroupDelete(): boolean {
    return window.confirm(
      'Delete group and all its contents? This will remove the group and all nodes/links inside it.'
    );
  }

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    if (!d) return;
    const nodeIds = ctx.state.selectedNodeIds();
    const linkIds = ctx.state.selectedLinkIds();
    if (nodeIds.size === 0 && linkIds.size === 0) return;

    for (const nodeId of nodeIds) {
      const node = d.getNode(nodeId);
      if (!node || node.locked) continue;
      if (node instanceof GroupNode) {
        for (const childNodeId of node.childNodeIds) {
          d.removeNode(childNodeId);
        }
        for (const childLinkId of node.childLinkIds) {
          d.removeLink(childLinkId);
        }
      }
      d.removeNode(nodeId);
    }
    for (const linkId of linkIds) {
      const link = d.getLink(linkId);
      if (link && !link.locked) d.removeLink(linkId);
    }
    ctx.state.clearSelection();
    ctx.state.setDiagram(d, true);
  }
}

import { Node } from './node';
import { Link } from './link';
import { Port } from './port';
import { Point } from './point';
import type { NodeId, LinkId, PortId } from './types';

/**
 * Diagram – container for nodes and links; single source of truth for the graph model.
 * Removing a node also removes any links connected to that node's ports.
 */
export class Diagram {
  private _nodes: Map<NodeId, Node> = new Map();
  private _links: Map<LinkId, Link> = new Map();

  /** All nodes in the diagram, sorted by zIndex ascending (lower = behind). */
  get nodes(): Node[] {
    return [...this._nodes.values()].sort((a, b) => (a.zIndex ?? 0) - (b.zIndex ?? 0));
  }

  /** All links in the diagram, sorted by zIndex ascending (lower = behind). */
  get links(): Link[] {
    return [...this._links.values()].sort((a, b) => (a.zIndex ?? 0) - (b.zIndex ?? 0));
  }

  /**
   * Add a node. Replaces existing node with same id.
   * @param node - Node to add
   */
  addNode(node: Node): void {
    this._nodes.set(node.id, node);
  }

  /**
   * Remove a node and any links connected to its ports.
   * @param id - Node id to remove
   * @returns true if the node existed and was removed
   */
  removeNode(id: NodeId): boolean {
    const node = this._nodes.get(id);
    if (!node) return false;
    for (const link of this._links.values()) {
      const sourceNode = this.getNodeByPortId(link.sourcePortId);
      const targetNode = this.getNodeByPortId(link.targetPortId);
      if (sourceNode?.id === id || targetNode?.id === id) {
        this._links.delete(link.id);
      }
    }
    return this._nodes.delete(id);
  }

  /**
   * Get node by id.
   * @param id - Node id
   * @returns Node or undefined
   */
  getNode(id: NodeId): Node | undefined {
    return this._nodes.get(id);
  }

  /**
   * Add a link. Replaces existing link with same id.
   * @param link - Link to add
   */
  addLink(link: Link): void {
    this._links.set(link.id, link);
  }

  /**
   * Remove link by id.
   * @param id - Link id to remove
   * @returns true if the link existed and was removed
   */
  removeLink(id: LinkId): boolean {
    return this._links.delete(id);
  }

  /**
   * Get link by id.
   * @param id - Link id
   * @returns Link or undefined
   */
  getLink(id: LinkId): Link | undefined {
    return this._links.get(id);
  }

  /**
   * Get absolute position of a port by id (searches all nodes).
   * Accounts for node rotation: port position is rotated around node center.
   * @param portId - Port id
   * @returns Point in diagram coordinates, or undefined if port not found
   */
  getPortPosition(portId: PortId): Point | undefined {
    for (const node of this._nodes.values()) {
      const port = node.getPort(portId);
      if (port) {
        const rect = node.getRect();
        const pos = port.getAbsolutePosition(rect);
        const angle = node.rotation ?? 0;
        if (angle === 0) return pos;
        const cx = rect.x + rect.width / 2;
        const cy = rect.y + rect.height / 2;
        return Point.rotateAround(pos, cx, cy, angle);
      }
    }
    return undefined;
  }

  private getNodeByPortId(portId: PortId): Node | undefined {
    for (const node of this._nodes.values()) {
      if (node.getPort(portId)) return node;
    }
    return undefined;
  }
}

import { Node, type NodeConfig } from './node';
import { Link } from './link';
import type { NodeId, LinkId, PointLike, Rect } from './types';

/**
 * Configuration for creating a GroupNode.
 * Extends NodeConfig with group-specific child and scale data.
 */
export interface GroupNodeConfig extends NodeConfig {
  /** IDs of nodes contained in the group. */
  childNodeIds?: NodeId[];
  /** IDs of links contained in the group. */
  childLinkIds?: LinkId[];
  /** Original positions of children before grouping (for ungroup restore). */
  originalPositions?: Map<NodeId, PointLike>;
  /** Child node instances (for preview and ungroup). */
  childNodes?: Node[];
  /** Child link instances (for ungroup). */
  childLinks?: Link[];
  /** Preview scale factor (fit content in group bounds). */
  scale?: number;
}

/**
 * GroupNode – container node that groups multiple child nodes and links.
 * Displays miniature preview of contents and external ports for connections outside the group.
 * Stores full child node and link data for restoration on ungroup.
 */
export class GroupNode extends Node {
  childNodeIds: Set<NodeId>;
  childLinkIds: Set<LinkId>;
  originalPositions: Map<NodeId, PointLike>;
  childNodes: Map<NodeId, Node>;
  childLinks: Map<LinkId, Link>;
  scale: number;

  constructor(config: GroupNodeConfig) {
    super({
      ...config,
      nodeType: 'group',
      shape: 'rectangle', // Groups are always rectangular
    });
    this.childNodeIds = new Set(config.childNodeIds ?? []);
    this.childLinkIds = new Set(config.childLinkIds ?? []);
    this.originalPositions = config.originalPositions ?? new Map();
    this.childNodes = new Map();
    this.childLinks = new Map();
    this.scale = config.scale ?? 1;

    // Store child nodes and links if provided
    if (config.childNodes) {
      for (const node of config.childNodes) {
        this.childNodes.set(node.id, node);
      }
    }
    if (config.childLinks) {
      for (const link of config.childLinks) {
        this.childLinks.set(link.id, link);
      }
    }
  }

  /**
   * Add a child node to the group.
   * @param node - Node to add as child
   * @param originalPosition - Optional position to store for ungroup
   */
  addChildNode(node: Node, originalPosition?: PointLike): void {
    this.childNodeIds.add(node.id);
    this.childNodes.set(node.id, node);
    if (originalPosition) {
      this.originalPositions.set(node.id, originalPosition);
    }
  }

  /**
   * Add a child link to the group.
   * @param link - Link to add as child
   */
  addChildLink(link: Link): void {
    this.childLinkIds.add(link.id);
    this.childLinks.set(link.id, link);
  }

  /**
   * Remove a child node from the group.
   * @param nodeId - ID of child node to remove
   * @returns true if the child existed and was removed
   */
  removeChildNode(nodeId: NodeId): boolean {
    this.originalPositions.delete(nodeId);
    this.childNodes.delete(nodeId);
    return this.childNodeIds.delete(nodeId);
  }

  /**
   * Remove a child link from the group.
   * @param linkId - ID of child link to remove
   * @returns true if the child existed and was removed
   */
  removeChildLink(linkId: LinkId): boolean {
    this.childLinks.delete(linkId);
    return this.childLinkIds.delete(linkId);
  }

  /**
   * Get stored child node by ID.
   * @param nodeId - Child node id
   * @returns Node or undefined
   */
  getChildNode(nodeId: NodeId): Node | undefined {
    return this.childNodes.get(nodeId);
  }

  /**
   * Get stored child link by ID.
   * @param linkId - Child link id
   * @returns Link or undefined
   */
  getChildLink(linkId: LinkId): Link | undefined {
    return this.childLinks.get(linkId);
  }

  /** Get all stored child nodes. */
  getStoredChildNodes(): Node[] {
    return Array.from(this.childNodes.values());
  }

  /** Get all stored child links. */
  getStoredChildLinks(): Link[] {
    return Array.from(this.childLinks.values());
  }

  /** Get all child node IDs. */
  getChildNodeIds(): NodeId[] {
    return Array.from(this.childNodeIds);
  }

  /** Get all child link IDs. */
  getChildLinkIds(): LinkId[] {
    return Array.from(this.childLinkIds);
  }

  /**
   * Get original position of a child node (before grouping).
   * @param nodeId - Child node id
   * @returns Stored position or undefined
   */
  getOriginalPosition(nodeId: NodeId): PointLike | undefined {
    return this.originalPositions.get(nodeId);
  }

  /**
   * Check if a node is a child of this group.
   * @param nodeId - Node id to check
   */
  hasChildNode(nodeId: NodeId): boolean {
    return this.childNodeIds.has(nodeId);
  }

  /**
   * Check if a link is a child of this group.
   * @param linkId - Link id to check
   */
  hasChildLink(linkId: LinkId): boolean {
    return this.childLinkIds.has(linkId);
  }

  /**
   * Calculate bounding box of all child nodes using stored/original positions and dimensions.
   * Used for preview scaling so the full picture fits.
   * @returns Rect encompassing all children
   */
  getBounds(): Rect {
    if (this.childNodes.size === 0) {
      return { x: 0, y: 0, width: 0, height: 0 };
    }

    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;

    for (const node of this.childNodes.values()) {
      const pos = this.originalPositions.get(node.id) ?? { x: node.x, y: node.y };
      minX = Math.min(minX, pos.x);
      minY = Math.min(minY, pos.y);
      maxX = Math.max(maxX, pos.x + node.width);
      maxY = Math.max(maxY, pos.y + node.height);
    }

    return {
      x: minX,
      y: minY,
      width: maxX - minX,
      height: maxY - minY,
    };
  }

  /** Minimum scale below which we show a generic placeholder instead of detailed preview. */
  static readonly MIN_PREVIEW_SCALE = 0.2;

  /**
   * Calculate the scale factor for preview content: fit entire bounds in the preview area.
   * Never scale up; if scale would be below MIN_PREVIEW_SCALE, we still return it (caller shows placeholder).
   * @returns Scale factor (0..1)
   */
  calculatePreviewScale(): number {
    const bounds = this.getBounds();
    if (bounds.width === 0 || bounds.height === 0) {
      return 1;
    }

    const padding = 20;
    const previewAreaY = 30;
    const previewAreaHeight = this.height - 50;
    const availableWidth = this.width - 2 * padding;
    const availableHeight = Math.max(previewAreaHeight, 40);

    const scaleX = availableWidth / bounds.width;
    const scaleY = availableHeight / bounds.height;

    // Fit entire picture; never scale up
    return Math.min(scaleX, scaleY, 1);
  }

  /** True when preview scale is below minimum and we should show generic placeholder. */
  shouldShowPlaceholder(): boolean {
    return this.scale < GroupNode.MIN_PREVIEW_SCALE && this.childNodes.size > 0;
  }

  /** Recompute and set scale from current bounds and size (call after resize). */
  updateScale(): void {
    this.scale = this.calculatePreviewScale();
  }
}

import {
  Node,
  GroupNode,
  Link,
  Port,
} from '../../../../graph-core';
import type { Diagram, NodeId, NodeShape, LinkId, PortId } from '../../../../graph-core';
import type { ActionContext } from './action-context';
import type { GraphEditorAction } from './graph-editor-action';

/** Modes for aligning or distributing selected nodes (toolbar, Draw.io-style). */
export type AlignMode =
  | 'alignLeft'
  | 'alignCenterH'
  | 'alignRight'
  | 'alignTop'
  | 'alignMiddleV'
  | 'alignBottom'
  | 'distributeH'
  | 'distributeV';

/** Add a new node at view center with default in/out ports. */
export class AddNodeAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    if (!d) return;
    const nodeId = `n${ctx.state.incrementNodeIdCounter()}` as NodeId;
    const vb = ctx.state.viewBox();
    const centerX = vb.x + vb.width / 2 - 60;
    const centerY = vb.y + vb.height / 2 - 30;
    const { x, y } = ctx.state.snapToGridEnabled()
      ? ctx.coordinate.snapToGrid(centerX, centerY)
      : { x: centerX, y: centerY };
    const maxZ = d.nodes.length > 0
      ? Math.max(...d.nodes.map((n) => n.zIndex ?? 0))
      : -1;
    const node = new Node({
      id: nodeId,
      x,
      y,
      width: 120,
      height: 60,
      label: `Node ${ctx.state.getNodeIdCounter()}`,
      zIndex: maxZ + 1,
      ports: [],
    });
    node.addPort(
      new Port({
        id: `${nodeId}-in` as PortId,
        nodeId,
        side: 'left',
        offset: 30,
        type: 'input',
      })
    );
    node.addPort(
      new Port({
        id: `${nodeId}-out` as PortId,
        nodeId,
        side: 'right',
        offset: 30,
        type: 'output',
      })
    );
    d.addNode(node);
    ctx.state.setDiagram(d, true);
  }
}

/** Add a new node from the palette at the given SVG coordinates. */
export class AddNodeFromPaletteAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(
    private readonly shape: NodeShape,
    private readonly svgX: number,
    private readonly svgY: number,
    private readonly customShapeId?: string
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    if (!d) return;
    const { x, y } = ctx.state.snapToGridEnabled()
      ? ctx.coordinate.snapToGrid(this.svgX, this.svgY)
      : { x: this.svgX, y: this.svgY };
    const nodeId = `n${ctx.state.incrementNodeIdCounter()}` as NodeId;
    const maxZ = d.nodes.length > 0
      ? Math.max(...d.nodes.map((n) => n.zIndex ?? 0))
      : -1;
    const node = new Node({
      id: nodeId,
      x,
      y,
      width: 120,
      height: 60,
      label: `Node ${ctx.state.getNodeIdCounter()}`,
      shape: this.shape,
      zIndex: maxZ + 1,
      ...(this.shape === 'custom' && this.customShapeId != null && { customShapeId: this.customShapeId }),
      ports: [],
    });
    node.addPort(
      new Port({
        id: `${nodeId}-in` as PortId,
        nodeId,
        side: 'left',
        offset: 30,
        type: 'input',
      })
    );
    node.addPort(
      new Port({
        id: `${nodeId}-out` as PortId,
        nodeId,
        side: 'right',
        offset: 30,
        type: 'output',
      })
    );
    d.addNode(node);
    ctx.state.setDiagram(d, true);
  }
}

/** Apply delta to nodes by id (used during drag). Caller pushes undo once at drag start. */
export class MoveNodesAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = false;

  constructor(
    private readonly initialPositions: Map<NodeId, { x: number; y: number }>,
    private readonly dx: number,
    private readonly dy: number
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    if (!d) return;
    for (const [nodeId, pos] of this.initialPositions) {
      const n = d.getNode(nodeId);
      if (n && !n.locked) {
        const newX = pos.x + this.dx;
        const newY = pos.y + this.dy;
        const { x, y } = ctx.state.snapToGridEnabled()
          ? ctx.coordinate.snapToGrid(newX, newY)
          : { x: newX, y: newY };
        n.setPosition(x, y);
      }
    }
    ctx.state.incrementRenderTick();
  }
}

/** Rotate selected nodes by angleDeg degrees (clockwise). */
export class RotateNodesAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(private readonly angleDeg: number) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const nodeIds = ctx.state.selectedNodeIds();
    if (!d || nodeIds.size === 0) return;
    for (const nodeId of nodeIds) {
      const n = d.getNode(nodeId);
      if (n && !n.locked) n.setRotation((n.rotation ?? 0) + this.angleDeg);
    }
    ctx.state.setDiagram(d, true);
  }
}

/** Align or distribute selected nodes by the given mode. */
export class AlignNodesAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(private readonly mode: AlignMode) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const nodeIds = ctx.state.selectedNodeIds();
    if (!d || nodeIds.size < 2) return;
    if ((this.mode === 'distributeH' || this.mode === 'distributeV') && nodeIds.size < 3) return;

    const orderedIds = Array.from(nodeIds);
    const refId = orderedIds[0];
    const ref = d.getNode(refId);
    if (!ref) return;

    const nodes: Node[] = [];
    for (const id of nodeIds) {
      const n = d.getNode(id);
      if (n) nodes.push(n);
    }
    if (nodes.length < 2) return;
    if ((this.mode === 'distributeH' || this.mode === 'distributeV') && nodes.length < 3) return;

    const snap = (x: number, y: number) =>
      ctx.state.snapToGridEnabled()
        ? ctx.coordinate.snapToGrid(x, y)
        : { x, y };

    const isAlignMode =
      this.mode === 'alignLeft' ||
      this.mode === 'alignCenterH' ||
      this.mode === 'alignRight' ||
      this.mode === 'alignTop' ||
      this.mode === 'alignMiddleV' ||
      this.mode === 'alignBottom';

    if (isAlignMode) {
      for (const n of nodes) {
        if (n.id === refId || n.locked) continue;
        if (this.mode === 'alignLeft') {
          const { x, y } = snap(ref.x, n.y);
          n.setPosition(x, y);
        } else if (this.mode === 'alignCenterH') {
          const newX = ref.x + ref.width / 2 - n.width / 2;
          const { x, y } = snap(newX, n.y);
          n.setPosition(x, y);
        } else if (this.mode === 'alignRight') {
          const newX = ref.x + ref.width - n.width;
          const { x, y } = snap(newX, n.y);
          n.setPosition(x, y);
        } else if (this.mode === 'alignTop') {
          const { x, y } = snap(n.x, ref.y);
          n.setPosition(x, y);
        } else if (this.mode === 'alignMiddleV') {
          const newY = ref.y + ref.height / 2 - n.height / 2;
          const { x, y } = snap(n.x, newY);
          n.setPosition(x, y);
        } else if (this.mode === 'alignBottom') {
          const newY = ref.y + ref.height - n.height;
          const { x, y } = snap(n.x, newY);
          n.setPosition(x, y);
        }
      }
    } else {
      let minX = Infinity;
      let maxX = -Infinity;
      let minY = Infinity;
      let maxY = -Infinity;
      for (const n of nodes) {
        const left = n.x;
        const right = n.x + n.width;
        const top = n.y;
        const bottom = n.y + n.height;
        if (left < minX) minX = left;
        if (right > maxX) maxX = right;
        if (top < minY) minY = top;
        if (bottom > maxY) maxY = bottom;
      }
      if (this.mode === 'distributeH') {
        const sorted = [...nodes].sort((a, b) => a.x + a.width / 2 - (b.x + b.width / 2));
        const totalWidth = sorted.reduce((sum, n) => sum + n.width, 0);
        const bboxWidth = maxX - minX;
        const gap = (bboxWidth - totalWidth) / (sorted.length - 1);
        let x = minX;
        for (const n of sorted) {
          if (n.locked) {
            x += n.width + gap;
            continue;
          }
          const { x: sx, y } = snap(x, n.y);
          n.setPosition(sx, y);
          x += n.width + gap;
        }
      } else if (this.mode === 'distributeV') {
        const sorted = [...nodes].sort((a, b) => a.y + a.height / 2 - (b.y + b.height / 2));
        const totalHeight = sorted.reduce((sum, n) => sum + n.height, 0);
        const bboxHeight = maxY - minY;
        const gap = (bboxHeight - totalHeight) / (sorted.length - 1);
        let y = minY;
        for (const n of sorted) {
          if (n.locked) {
            y += n.height + gap;
            continue;
          }
          const { x, y: sy } = snap(n.x, y);
          n.setPosition(x, sy);
          y += n.height + gap;
        }
      }
    }

    ctx.state.setDiagram(d, true);
  }
}

function getNodeByPortId(d: Diagram, portId: PortId): Node | undefined {
  for (const node of d.nodes) {
    if (node.getPort(portId)) return node;
  }
  return undefined;
}

/** Group selected nodes into a GroupNode. */
export class GroupNodesAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const selectedNodeIds = ctx.state.selectedNodeIds();
    if (!d || selectedNodeIds.size < 2) return;

    const selectedNodes: Node[] = [];
    for (const nodeId of selectedNodeIds) {
      const node = d.getNode(nodeId);
      if (!node || node.nodeType === 'group') return;
      selectedNodes.push(node);
    }

    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    const originalPositions = new Map<NodeId, { x: number; y: number }>();
    for (const node of selectedNodes) {
      minX = Math.min(minX, node.x);
      minY = Math.min(minY, node.y);
      maxX = Math.max(maxX, node.x + node.width);
      maxY = Math.max(maxY, node.y + node.height);
      originalPositions.set(node.id, { x: node.x, y: node.y });
    }

    const padding = 30;
    const groupX = minX - padding;
    const groupY = minY - padding;
    const groupWidth = maxX - minX + 2 * padding;
    const groupHeight = maxY - minY + 2 * padding;

    const groupId = `g${ctx.state.incrementNodeIdCounter()}` as NodeId;
    const maxZ = d.nodes.length > 0
      ? Math.max(...d.nodes.map((n) => n.zIndex ?? 0))
      : -1;
    const groupNode = new GroupNode({
      id: groupId,
      x: groupX,
      y: groupY,
      width: groupWidth,
      height: groupHeight,
      label: `Group ${ctx.state.getNodeIdCounter()}`,
      childNodeIds: Array.from(selectedNodeIds),
      childLinkIds: [],
      originalPositions,
      scale: 1,
      zIndex: maxZ + 1,
      ports: [],
    });

    const childNodeIdSet = new Set(selectedNodeIds);
    const internalLinkIds: LinkId[] = [];
    const externalLinks: Array<{
      link: Link;
      isOutgoing: boolean;
      childPortId: PortId;
      externalPortId: PortId;
    }> = [];

    for (const link of d.links) {
      const sourceNode = getNodeByPortId(d, link.sourcePortId);
      const targetNode = getNodeByPortId(d, link.targetPortId);
      const sourceInGroup = sourceNode && childNodeIdSet.has(sourceNode.id);
      const targetInGroup = targetNode && childNodeIdSet.has(targetNode.id);

      if (sourceInGroup && targetInGroup) {
        internalLinkIds.push(link.id);
      } else if (sourceInGroup && !targetInGroup) {
        externalLinks.push({
          link,
          isOutgoing: true,
          childPortId: link.sourcePortId,
          externalPortId: link.targetPortId,
        });
      } else if (!sourceInGroup && targetInGroup) {
        externalLinks.push({
          link,
          isOutgoing: false,
          childPortId: link.targetPortId,
          externalPortId: link.sourcePortId,
        });
      }
    }

    groupNode.childLinkIds = new Set(internalLinkIds);

    for (const node of selectedNodes) {
      groupNode.childNodes.set(node.id, node);
    }
    for (const linkId of internalLinkIds) {
      const link = d.getLink(linkId);
      if (link) groupNode.childLinks.set(linkId, link);
    }

    const portMap = new Map<PortId, PortId>();
    for (const { link, isOutgoing, childPortId } of externalLinks) {
      let groupPortId = portMap.get(childPortId);
      if (!groupPortId) {
        groupPortId = `${groupId}-ext-${childPortId}` as PortId;
        portMap.set(childPortId, groupPortId);
        const childNode = getNodeByPortId(d, childPortId);
        let side: 'top' | 'right' | 'bottom' | 'left' = 'right';
        let offset = groupHeight / 2;
        if (childNode) {
          const childCenterX = childNode.x + childNode.width / 2;
          const childCenterY = childNode.y + childNode.height / 2;
          const groupCenterX = groupX + groupWidth / 2;
          const groupCenterY = groupY + groupHeight / 2;
          const dx = childCenterX - groupCenterX;
          const dy = childCenterY - groupCenterY;
          if (Math.abs(dx) > Math.abs(dy)) {
            side = dx > 0 ? 'right' : 'left';
            offset = childCenterY - groupY;
          } else {
            side = dy > 0 ? 'bottom' : 'top';
            offset = childCenterX - groupX;
          }
        }
        const port = new Port({
          id: groupPortId,
          nodeId: groupId,
          side,
          offset,
          type: isOutgoing ? 'output' : 'input',
        });
        groupNode.addPort(port);
      }
      d.removeLink(link.id);
      const newLink = new Link({
        id: link.id,
        sourcePortId: isOutgoing ? groupPortId! : link.sourcePortId,
        targetPortId: isOutgoing ? link.targetPortId : groupPortId!,
        points: link.points.map((p) => ({ x: p.x, y: p.y })),
        routing: link.routing,
      });
      d.addLink(newLink);
    }

    for (const nodeId of selectedNodeIds) {
      d.removeNode(nodeId);
    }
    d.addNode(groupNode);
    groupNode.updateScale();
    ctx.state.clearSelection();
    ctx.state.setNodeSelection(new Set([groupId]));
    ctx.state.setDiagram(d, true);
  }
}

/** Ungroup a GroupNode, restoring child nodes and links. */
export class UngroupNodeAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(private readonly groupId: NodeId) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const groupNode = d?.getNode(this.groupId);
    if (!d || !groupNode || !(groupNode instanceof GroupNode)) return;

    const restoredNodeIds: NodeId[] = [];
    for (const childNodeId of groupNode.childNodeIds) {
      const storedNode = groupNode.getChildNode(childNodeId);
      const originalPos = groupNode.getOriginalPosition(childNodeId);
      if (storedNode && originalPos) {
        storedNode.setPosition(originalPos.x, originalPos.y);
        d.addNode(storedNode);
        restoredNodeIds.push(childNodeId);
      }
    }

    for (const childLinkId of groupNode.childLinkIds) {
      const storedLink = groupNode.getChildLink(childLinkId);
      if (storedLink) d.addLink(storedLink);
    }

    const portMap = new Map<PortId, PortId>();
    for (const port of groupNode.ports) {
      const match = port.id.match(/-ext-(.+)$/);
      if (match) portMap.set(port.id, match[1] as PortId);
    }

    const linksToUpdate = d.links.filter(
      (l) => portMap.has(l.sourcePortId) || portMap.has(l.targetPortId)
    );
    for (const link of linksToUpdate) {
      const childSourcePortId = portMap.get(link.sourcePortId);
      const childTargetPortId = portMap.get(link.targetPortId);
      if (!childSourcePortId && !childTargetPortId) continue;
      d.removeLink(link.id);
      const newLink = new Link({
        id: link.id,
        sourcePortId: childSourcePortId ?? link.sourcePortId,
        targetPortId: childTargetPortId ?? link.targetPortId,
        points: link.points.map((p) => ({ x: p.x, y: p.y })),
        routing: link.routing,
      });
      d.addLink(newLink);
    }

    d.removeNode(this.groupId);
    ctx.state.clearSelection();
    ctx.state.setNodeSelection(new Set(restoredNodeIds));
    ctx.state.setDiagram(d, true);
  }
}

/** Resize a group node; caller pushes undo at resize start. */
export class ResizeGroupNodeAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = false;

  constructor(
    private readonly groupId: NodeId,
    private readonly newWidth: number,
    private readonly newHeight: number
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const groupNode = d?.getNode(this.groupId);
    if (!d || !groupNode || !(groupNode instanceof GroupNode) || groupNode.locked) return;
    groupNode.width = Math.max(this.newWidth, 100);
    groupNode.height = Math.max(this.newHeight, 80);
    groupNode.updateScale();
    ctx.state.incrementRenderTick();
  }
}

import { Point } from './point';
import type { LinkId, PortId } from './types';
import type { Diagram } from './diagram';

/** Routing style for links: straight (free angles) or orthogonal (H/V only). */
export type LinkRouting = 'straight' | 'orthogonal';

/**
 * Configuration for creating a Link.
 */
export interface LinkConfig {
  /** Unique link identifier. */
  id: LinkId;
  /** Source (output) port id. */
  sourcePortId: PortId;
  /** Target (input) port id. */
  targetPortId: PortId;
  /** Optional waypoints for polyline; otherwise straight between ports. */
  points?: Array<{ x: number; y: number }>;
  /** Path routing; defaults to 'straight'. */
  routing?: LinkRouting;
  /** Z-order for stacking; higher = on top. Default 0. */
  zIndex?: number;
  /** When true, link cannot be edited (waypoints) or deleted. Default false. */
  locked?: boolean;
}

/**
 * Link – connection between two ports. Optional waypoints for polyline; otherwise straight line.
 * With orthogonal routing, segments are horizontal or vertical only.
 */
export class Link implements LinkConfig {
  readonly id: LinkId;
  readonly sourcePortId: PortId;
  readonly targetPortId: PortId;
  points: Point[] = [];
  routing: LinkRouting = 'straight';
  zIndex: number;
  locked: boolean;

  constructor(config: LinkConfig) {
    this.id = config.id;
    this.sourcePortId = config.sourcePortId;
    this.targetPortId = config.targetPortId;
    this.points = (config.points ?? []).map((p) => new Point(p.x, p.y));
    this.routing = config.routing ?? 'straight';
    this.zIndex = config.zIndex ?? 0;
    this.locked = config.locked ?? false;
  }

  /** Set z-order (higher = on top). */
  setZIndex(value: number): void {
    this.zIndex = value;
  }

  /** Set locked state (when true, link cannot be edited or deleted). */
  setLocked(value: boolean): void {
    this.locked = value;
  }

  /**
   * Build SVG path d attribute: M source L target, or M source L waypoint... L target.
   * For orthogonal routing, inserts corner points so segments are H or V only.
   * @param diagram - Used to resolve port positions
   * @returns Path d string, or '' if port positions not found
   */
  buildPath(diagram: Diagram): string {
    const source = diagram.getPortPosition(this.sourcePortId);
    const target = diagram.getPortPosition(this.targetPortId);
    if (!source || !target) {
      return '';
    }

    const pts = [source, ...this.points, target];

    if (this.routing === 'orthogonal') {
      return this.buildOrthogonalPath(pts);
    }

    const segments: string[] = [`M ${pts[0].x} ${pts[0].y}`];
    for (let i = 1; i < pts.length; i++) {
      segments.push(`L ${pts[i].x} ${pts[i].y}`);
    }
    return segments.join(' ');
  }

  /**
   * Build orthogonal path: only horizontal and vertical segments.
   * Between non-aligned points A and B, inserts corner (B.x, A.y) or (A.x, B.y).
   */
  private buildOrthogonalPath(pts: Array<{ x: number; y: number }>): string {
    if (pts.length < 2) return '';
    const result: string[] = [`M ${pts[0].x} ${pts[0].y}`];

    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i];
      const b = pts[i + 1];
      if (a.x === b.x || a.y === b.y) {
        result.push(`L ${b.x} ${b.y}`);
      } else {
        const corner = this.orthogonalCorner(a, b);
        result.push(`L ${corner.x} ${corner.y} L ${b.x} ${b.y}`);
      }
    }
    return result.join(' ');
  }

  /** Choose corner for A->B: horizontal first from A, then vertical. */
  private orthogonalCorner(
    a: { x: number; y: number },
    b: { x: number; y: number }
  ): { x: number; y: number } {
    return { x: b.x, y: a.y };
  }
}

import { Link, Point } from '../../../../graph-core';
import type { LinkId, LinkRouting, NodeId, PortId } from '../../../../graph-core';
import type { ActionContext } from './action-context';
import type { GraphEditorAction } from './graph-editor-action';

/** Create a link from source port to target port. Respects max links per port and no duplicate. */
export class CreateLinkAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(
    private readonly sourcePortId: PortId,
    private readonly targetPortId: PortId,
    private readonly targetNodeId: string
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    if (!d) return;
    const duplicate = d.links.some(
      (l) =>
        l.sourcePortId === this.sourcePortId && l.targetPortId === this.targetPortId
    );
    if (duplicate) return;

    const defaultMax = ctx.state.defaultMaxLinksPerPort();
    const getPort = (portId: PortId) => {
      for (const node of d!.nodes) {
        const p = node.getPort(portId);
        if (p) return p;
      }
      return undefined;
    };
    const countLinksAtPort = (portId: PortId) =>
      d.links.filter(
        (l) => l.sourcePortId === portId || l.targetPortId === portId
      ).length;

    const sourcePort = getPort(this.sourcePortId);
    const targetPort = getPort(this.targetPortId);
    const maxSource = sourcePort?.maxLinks ?? defaultMax;
    const maxTarget = targetPort?.maxLinks ?? defaultMax;
    if (maxSource > 0 && countLinksAtPort(this.sourcePortId) >= maxSource) return;
    if (maxTarget > 0 && countLinksAtPort(this.targetPortId) >= maxTarget) return;

    const linkId = `l${ctx.state.incrementLinkIdCounter()}`;
    const maxZ =
      d.links.length > 0
        ? Math.max(...d.links.map((l) => l.zIndex ?? 0))
        : -1;
    d.addLink(
      new Link({
        id: linkId,
        sourcePortId: this.sourcePortId,
        targetPortId: this.targetPortId,
        routing: ctx.state.defaultLinkRouting(),
        zIndex: maxZ + 1,
      })
    );
    ctx.state.setDiagram(d, true);
  }
}

/** Set routing for all selected links. */
export class SetSelectedLinksRoutingAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(private readonly routing: LinkRouting) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const linkIds = ctx.state.selectedLinkIds();
    if (!d || linkIds.size === 0) return;
    for (const linkId of linkIds) {
      const link = d.getLink(linkId);
      if (link) link.routing = this.routing;
    }
    ctx.state.setDiagram(d, true);
  }
}

/** Add a waypoint to a link at the given index. */
export class AddLinkWaypointAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(
    private readonly linkId: LinkId,
    private readonly index: number,
    private readonly x: number,
    private readonly y: number
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const link = d?.getLink(this.linkId);
    if (!d || !link || link.locked) return;
    let px = this.x;
    let py = this.y;
    if (ctx.state.snapToGridEnabled()) {
      const snapped = ctx.coordinate.snapToGrid(this.x, this.y);
      px = snapped.x;
      py = snapped.y;
    }
    link.points.splice(this.index, 0, new Point(px, py));
    ctx.state.setDiagram(d, true);
  }
}

/** Move an existing waypoint; caller pushes undo at drag start. */
export class MoveLinkWaypointAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = false;

  constructor(
    private readonly linkId: LinkId,
    private readonly index: number,
    private readonly x: number,
    private readonly y: number
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const link = d?.getLink(this.linkId);
    if (!d || !link || link.locked || this.index < 0 || this.index >= link.points.length) return;
    let px = this.x;
    let py = this.y;
    if (ctx.state.snapToGridEnabled()) {
      const snapped = ctx.coordinate.snapToGrid(this.x, this.y);
      px = snapped.x;
      py = snapped.y;
    }
    link.points[this.index] = new Point(px, py);
    ctx.state.incrementRenderTick();
  }
}

/** Remove a waypoint from a link. */
export class RemoveLinkWaypointAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(
    private readonly linkId: LinkId,
    private readonly index: number
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const link = d?.getLink(this.linkId);
    if (!d || !link || link.locked || this.index < 0 || this.index >= link.points.length) return;
    link.points.splice(this.index, 1);
    ctx.state.setDiagram(d, true);
  }
}

/** Move a segment by (dx, dy); caller pushes undo at drag start. */
export class MoveLinkSegmentAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = false;

  constructor(
    private readonly linkId: LinkId,
    private readonly segmentIndex: number,
    private readonly dx: number,
    private readonly dy: number
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const link = d?.getLink(this.linkId);
    if (!d || !link || link.locked) return;
    const n = link.points.length;
    if (n === 0) return;
    if (this.segmentIndex === 0) {
      link.points[0] = new Point(link.points[0].x + this.dx, link.points[0].y + this.dy);
    } else if (this.segmentIndex >= n) {
      link.points[n - 1] = new Point(
        link.points[n - 1].x + this.dx,
        link.points[n - 1].y + this.dy
      );
    } else {
      link.points[this.segmentIndex - 1] = new Point(
        link.points[this.segmentIndex - 1].x + this.dx,
        link.points[this.segmentIndex - 1].y + this.dy
      );
      link.points[this.segmentIndex] = new Point(
        link.points[this.segmentIndex].x + this.dx,
        link.points[this.segmentIndex].y + this.dy
      );
    }
    ctx.state.incrementRenderTick();
  }
}

/** Clear all waypoints from a link. */
export class ClearLinkWaypointsAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(private readonly linkId: LinkId) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    const link = d?.getLink(this.linkId);
    if (!d || !link || link.locked || link.points.length === 0) return;
    link.points.length = 0;
    ctx.state.setDiagram(d, true);
  }
}

/** Set maxLinks on all ports of the given nodes. */
export class SetPortMaxLinksAction implements GraphEditorAction {
  readonly pushUndoBeforeExecute = true;

  constructor(
    private readonly nodeIds: NodeId[],
    private readonly value: number
  ) {}

  execute(ctx: ActionContext): void {
    const d = ctx.state.getDiagram();
    if (!d || this.nodeIds.length === 0) return;
    for (const nodeId of this.nodeIds) {
      const node = d.getNode(nodeId);
      if (!node) continue;
      for (const port of node.ports) {
        port.maxLinks = this.value;
      }
    }
    ctx.state.setDiagram(d, true);
  }
}

