import { Component, ChangeDetectionStrategy, computed, input, output } from '@angular/core';
import type { NodeShape } from '../../../../graph-core';
import type { GraphEditorPaletteConfig } from '../config/graph-editor-config';

export interface ShapeDragStartPayload {
  shape: NodeShape;
  pointerId: number;
  customShapeId?: string;
}

const BUILTIN_SHAPES: { shape: NodeShape; label: string }[] = [
  { shape: 'rectangle', label: 'Rectangle' },
  { shape: 'roundedRect', label: 'Rounded rect' },
  { shape: 'circle', label: 'Circle' },
  { shape: 'ellipse', label: 'Ellipse' },
  { shape: 'diamond', label: 'Diamond' },
  { shape: 'triangle', label: 'Triangle' },
  { shape: 'hexagon', label: 'Hexagon' },
  { shape: 'parallelogram', label: 'Parallelogram' },
  { shape: 'pentagon', label: 'Pentagon' },
  { shape: 'cross', label: 'Cross' },
];

const CUSTOM_SHAPES: { assetId: string; label: string }[] = [
  { assetId: 'shapes/star.svg', label: 'Star' },
  { assetId: 'shapes/gear.svg', label: 'Gear' },
  { assetId: 'shapes/arrow.svg', label: 'Arrow' },
  { assetId: 'shapes/heart.svg', label: 'Heart' },
];

/**
 * Sidebar palette of node shapes. User can drag a shape onto the canvas to add a node.
 */
@Component({
  selector: 'app-graph-palette',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './graph-palette.component.html',
  styleUrl: './graph-palette.component.scss',
})
export class GraphPaletteComponent {
  readonly shapeDragStart = output<ShapeDragStartPayload>();

  /** Palette config; shapes: 'all' or array of NodeShape to show. */
  readonly paletteConfig = input<GraphEditorPaletteConfig | undefined>(undefined);

  protected readonly builtinShapes = computed(() => {
    const cfg = this.paletteConfig();
    const filter = cfg?.shapes;
    if (!filter || filter === 'all') return BUILTIN_SHAPES;
    const set = new Set(filter);
    return BUILTIN_SHAPES.filter((item) => set.has(item.shape));
  });

  protected readonly customShapes = CUSTOM_SHAPES;

  protected readonly assetsBase = '/assets/';

  protected onBuiltinPointerDown(shape: NodeShape, event: PointerEvent): void {
    event.preventDefault();
    this.shapeDragStart.emit({ shape, pointerId: event.pointerId });
    (event.target as Element).setPointerCapture?.(event.pointerId);
  }

  protected onCustomPointerDown(assetId: string, event: PointerEvent): void {
    event.preventDefault();
    this.shapeDragStart.emit({
      shape: 'custom',
      pointerId: event.pointerId,
      customShapeId: assetId,
    });
    (event.target as Element).setPointerCapture?.(event.pointerId);
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
} from '@angular/core';
import type { DiagramJson } from '../../../../graph-core';
import {
  MOCK_DIAGRAM_EMPTY,
  MOCK_DIAGRAM_SINGLE_NODE,
  MOCK_DIAGRAM_CHAIN,
  MOCK_DIAGRAM_DIAMOND,
} from '../../../../graph-core';
import type { LinkRouting } from '../../../../graph-core';
import type { AlignMode } from '../services/graph-operations.service';
import type { GraphEditorToolbarConfig } from '../config/graph-editor-config';

/** Toolbar: add node, delete selection, load example/file/storage, save. Emits events; parent handles logic. */
@Component({
  selector: 'app-graph-toolbar',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './graph-toolbar.component.html',
  styleUrl: './graph-toolbar.component.scss',
})
export class GraphToolbarComponent {
  /** Toolbar config; when a flag is false, that section/button is hidden. */
  readonly toolbarConfig = input<GraphEditorToolbarConfig | undefined>(undefined);

  readonly disabled = input<boolean>(false);
  readonly hasSelection = input<boolean>(false);
  /** True when at least one node is selected (for rotate buttons). */
  readonly hasNodeSelection = input<boolean>(false);
  /** True when can group (2+ regular nodes selected). */
  readonly canGroup = input<boolean>(false);
  /** True when can ungroup (1 group node selected). */
  readonly canUngroup = input<boolean>(false);
  /** True when 2+ nodes selected (for align buttons). */
  readonly canAlign = input<boolean>(false);
  /** True when 3+ nodes selected (for distribute buttons). */
  readonly canDistribute = input<boolean>(false);
  readonly snapToGridEnabled = input<boolean>(true);
  /** True when LOD and Canvas rendering are enabled. */
  readonly lodEnabled = input<boolean>(false);
  /** True when viewport culling is enabled (render only visible nodes/links). */
  readonly viewportCullingEnabled = input<boolean>(true);
  /** Current link routing for connector select (from selection or default). */
  readonly linkRouting = input<LinkRouting>('orthogonal');
  /** True when all selected nodes/links are locked (shows Unlock vs Lock). */
  readonly hasLockedSelection = input<boolean>(false);
  /** True when Pan tool is active (toolbar button pressed). */
  readonly panToolActive = input<boolean>(false);
  /** Current zoom as percentage (e.g. 100) for display. */
  readonly zoomPercent = input<number>(100);
  /** Max links per port value for toolbar input (0 = unlimited). */
  readonly maxLinksPerPortValue = input<number>(1);

  readonly addNode = output<void>();
  readonly deleteSelection = output<void>();
  readonly rotateCw = output<void>();
  readonly rotateCcw = output<void>();
  readonly group = output<void>();
  readonly ungroup = output<void>();
  readonly panToolToggle = output<void>();
  readonly zoomIn = output<void>();
  readonly zoomOut = output<void>();
  readonly resetZoom = output<void>();
  readonly fitToView = output<void>();
  readonly zoomToSelection = output<void>();
  readonly snapToGridToggle = output<void>();
  readonly lodToggle = output<void>();
  readonly viewportCullingToggle = output<void>();
  readonly loadExample = output<DiagramJson>();
  readonly saveRequest = output<void>();
  readonly loadFromFile = output<DiagramJson>();
  readonly loadFromStorage = output<void>();
  readonly align = output<AlignMode>();
  readonly linkRoutingChange = output<LinkRouting>();
  readonly bringToFront = output<void>();
  readonly sendToBack = output<void>();
  readonly lockUnlock = output<void>();
  readonly fieldMapperDemoClick = output<void>();
  readonly maxLinksPerPortChange = output<number>();

  protected show(key: keyof GraphEditorToolbarConfig): boolean {
    return this.toolbarConfig()?.[key] !== false;
  }

  /** Emit linkRoutingChange when user changes connector style in select. */
  protected onLinkRoutingChange(event: Event): void {
    const select = event.target as HTMLSelectElement;
    const value = select.value as LinkRouting;
    if (value === 'straight' || value === 'orthogonal') {
      this.linkRoutingChange.emit(value);
    }
  }

  /** Emit maxLinksPerPortChange when user changes the max links input (0 = unlimited). */
  protected onMaxLinksPerPortChange(event: Event): void {
    const inputEl = event.target as HTMLInputElement;
    const parsed = parseInt(inputEl.value, 10);
    if (!Number.isNaN(parsed) && parsed >= 0) {
      this.maxLinksPerPortChange.emit(parsed);
    }
  }

  /** Emit addNode. */
  protected onAddNode(): void {
    this.addNode.emit();
  }

  /** Emit deleteSelection. */
  protected onDeleteSelection(): void {
    this.deleteSelection.emit();
  }

  /** Emit rotateCw (90° clockwise). */
  protected onRotateCw(): void {
    this.rotateCw.emit();
  }

  /** Emit rotateCcw (90° counter-clockwise). */
  protected onRotateCcw(): void {
    this.rotateCcw.emit();
  }

  /** Emit group. */
  protected onGroup(): void {
    this.group.emit();
  }

  /** Emit ungroup. */
  protected onUngroup(): void {
    this.ungroup.emit();
  }

  protected onAlign(mode: AlignMode): void {
    this.align.emit(mode);
  }

  protected onPanToolToggle(): void {
    this.panToolToggle.emit();
  }

  protected onZoomIn(): void {
    this.zoomIn.emit();
  }

  protected onZoomOut(): void {
    this.zoomOut.emit();
  }

  protected onResetZoom(): void {
    this.resetZoom.emit();
  }

  protected onFitToView(): void {
    this.fitToView.emit();
  }

  protected onZoomToSelection(): void {
    this.zoomToSelection.emit();
  }

  protected onSnapToGridToggle(): void {
    this.snapToGridToggle.emit();
  }

  protected onLodToggle(): void {
    this.lodToggle.emit();
  }

  protected onViewportCullingToggle(): void {
    this.viewportCullingToggle.emit();
  }

  /** Emit loadExample with selected diagram JSON. */
  protected onLoadExample(json: DiagramJson): void {
    this.loadExample.emit(json);
  }

  protected readonly exampleEmpty = MOCK_DIAGRAM_EMPTY;
  protected readonly exampleSingle = MOCK_DIAGRAM_SINGLE_NODE;
  protected readonly exampleChain = MOCK_DIAGRAM_CHAIN;
  protected readonly exampleDiamond = MOCK_DIAGRAM_DIAMOND;

  /** Emit saveRequest. */
  protected onSave(): void {
    this.saveRequest.emit();
  }

  /** Emit loadFromStorage. */
  protected onLoadFromStorage(): void {
    this.loadFromStorage.emit();
  }

  protected onBringToFront(): void {
    this.bringToFront.emit();
  }

  protected onSendToBack(): void {
    this.sendToBack.emit();
  }

  protected onLockUnlock(): void {
    this.lockUnlock.emit();
  }

  protected onFieldMapperDemo(): void {
    this.fieldMapperDemoClick.emit();
  }

  /** Trigger file input click. */
  protected onLoadFile(fileInput: HTMLInputElement): void {
    fileInput.click();
  }

  /** Parse selected file as DiagramJson and emit loadFromFile. */
  protected onFileSelected(event: Event, fileInput: HTMLInputElement): void {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const json = JSON.parse(reader.result as string) as DiagramJson;
        if (json && Array.isArray(json.nodes) && Array.isArray(json.links)) {
          this.loadFromFile.emit(json);
        }
      } catch {
        // ignore invalid JSON
      }
      fileInput.value = '';
    };
    reader.readAsText(file);
  }
}

